#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

void initialize(long *offsets, int *keys, Record *records, size_t size, unsigned seed) {
    srand(seed);

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand();

        do {
            keys[i] = rand();
        } while (keys[i] == offsets[i]);

        records[i].value = rand();
    }
}

int main() {
    size_t size = 1000000; // adjust as needed

    long *offsets = malloc(sizeof(*offsets) * size);
    if (offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return 1;
    }

    int *keys = malloc(sizeof(*keys) * size);
    if (keys == NULL) {
        free(offsets);
        fprintf(stderr, "Failed to allocate memory for keys\n");
        return 1;
    }

    Record *records = malloc(sizeof(*records) * size);
    if (records == NULL) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Failed to allocate memory for records\n");
        return 1;
    }

    clock_t start = clock();
    initialize(offsets, keys, records, size, time(NULL));
    clock_t end = clock();

    printf("Initialization took %.3f seconds.\n", (double)(end - start) / CLOCKS_PER_SEC);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
```
