['This is a complex task that requires a deep understanding of C programming, system resource management, concurrency control, error handling, regular expressions, and performance optimization. Here's an outline of how you might approach this problem in C. Please note that writing such a program would be quite extensive and beyond the scope of this platform.

```c
#include <stdio.h>
#include <regex.h>
#include <pthread.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

// Define a struct to hold file information and processing settings
typedef struct {
    char *filename;
    // Add other necessary fields for your use case
} FileInfo;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int lineCount = 0;

// Function to process a file
void* processFile(void *arg) {
    FileInfo *fileInfo = (FileInfo*) arg;

    // Open the file and map it into memory using mmap()
    int fd = open(fileInfo->filename, O_RDONLY);
    if (fd == -1) {
        // Handle error: unable to open file
        return NULL;
    }

    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        // Handle error: unable to get file size
        close(fd);
        return NULL;
    }

    char *file_in_memory = mmap(NULL, sb.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (file_in_memory == MAP_FAILED) {
        // Handle error: unable to map file into memory
        close(fd);
        return NULL;
    }

    // Process the file line by line using a regex pattern
    char *pattern = "your-regex-pattern";
    regex_t regexCompiled;
    regcomp(&regexCompiled, pattern, REG_EXTENDED|REG_NEWLINE);

    char *lineStart = file_in_memory;
    for (char *p = file_in_memory; p < file_in_memory + sb.st_size; ++p) {
        if (*p == '\n') {
            int match = regexec(&regexCompiled, lineStart, 0, NULL, 0);

            // Update shared state (lineCount) under lock to avoid race conditions
            pthread_mutex_lock(&lock);
            if (!match) {
                // Process the matching line
                ++lineCount;
                if (lineCount % 100 == 0) {
                    printf("Processed lines: %d\n", lineCount);
                }
            }
            pthread_mutex_unlock(&lock);

            lineStart = p + 1;
        }
    }

    // Clean up resources
    regfree(&regexCompiled);
    munmap(file_in_memory, sb.st_size);
    close(fd);

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s file1 [file2 ...]\n", argv[0]);
        return 1;
    }

    // Create a thread for each input file
    pthread_t threads[argc - 1];
    FileInfo files[argc - 1];

    for (int i = 1; i < argc; ++i) {
        files[i - 1].filename = argv[i];

        // Create a new thread to process each file
        if (pthread_create(&threads[i - 1], NULL, processFile, &files[i - 1])) {
            fprintf(stderr, "Error creating thread\n");
            return 2;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < argc - 1; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Total processed lines: %d\n", lineCount);

    return 0;
}
```
This is a simplified example and does not cover all the requirements you've specified. It uses POSIX threads for concurrency, mmap() for memory-mapped I/O, regex.h for regular expressions, and pthread_mutex_t for synchronization. You would need to expand this code significantly to meet your specific needs.
']

