#include <stdio.h>
#include <dlfcn.h>
#include <string.h>

typedef struct {
    char* name;
    void* (*hash_func)(const unsigned char*, size_t, unsigned char*);
} HashFunction;

HashFunction* load_crypto_functions() {
    // Load the cryptographic library dynamically at runtime.
    void *handle = dlopen("libcrypto.so", RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "dlopen failed: %s\n", dlerror());
        return NULL;
    }

    // Get the list of available hash functions from the library.
    char* (*get_hash_functions)() = dlsym(handle, "get_hash_functions");
    if (!get_hash_functions) {
        fprintf(stderr, "dlsym failed: %s\n", dlerror());
        return NULL;
    }

    // Get the list of hash functions.
    char* function_names = get_hash_functions();
    if (!function_names) {
        fprintf(stderr, "Failed to retrieve hash function names.\n");
        return NULL;
    }

    // Parse the list of hash functions into a HashFunction struct.
    int num_functions = atoi(strtok(function_names, ","));
    HashFunction* functions = malloc(num_functions * sizeof(HashFunction));
    for (int i = 0; i < num_functions; ++i) {
        char* function_name = strtok(NULL, ",");
        functions[i].name = strdup(function_name);
        functions[i].hash_func = dlsym(handle, function_name);
    }

    return functions;
}
