public class DataRetrievalService
{
    private readonly List<IDataSource> _dataSources;
    private readonly IMemoryCache _cache;

    public DataRetrievalService(IMemoryCache cache)
    {
        _cache = cache;
        _dataSources = new List<IDataSource>
        {
            new SqlDataSource(),
            new NoSqlDataSource(),
            new RestApiDataSource()
        };
    }

    public async Task<IEnumerable<T>> GetDataAsync<T>(string query, int pageNumber, int pageSize)
    {
        var cacheKey = $"{query}_{pageNumber}_{pageSize}";

        if (_cache.TryGetValue(cacheKey, out IEnumerable<T> cachedResult))
            return cachedResult;

        var tasks = new List<Task<IEnumerable<T>>>();

        foreach (var dataSource in _dataSources)
        {
            tasks.Add(dataSource.GetDataAsync<T>(query, pageNumber, pageSize));
        }

        var results = await Task.WhenAll(tasks);

        // Combine and paginate the results...
        var combinedResults = CombineAndPaginate(results, pageNumber, pageSize);

        _cache.Set(cacheKey, combinedResults, TimeSpan.FromMinutes(5));

        return combinedResults;
    }

    private IEnumerable<T> CombineAndPaginate(IEnumerable<IEnumerable<T>> results, int pageNumber, int pageSize)
    {
