```rust
use std::env;
use std::fs::{self, DirEntry};
use std::path::PathBuf;

pub fn initialize_directory_from_environment(default_dir_name: &str) -> Result<String, String> {
    match env::var("TARGET_DIR") {
        Ok(target_dir) => {
            let dir = PathBuf::from(target_dir);
            if !fs::metadata(&dir).is_ok() {
                return Err(format![ "Directory does not exist: {}", target_dir]);
            }
            Ok(target_dir)
        },
        Err(_) => match fs::create_dir(default_dir_name) {
            Ok((_, path)) => {
                env::set_var("TARGET_DIR", path.to_str().unwrap());
                Ok(path.to_str().unwrap().to_string())
            },
            Err(_) => Err("Failed to create directory.".to_string()),
        }
    }
}
```
