    private readonly ILogger<PageElementController> _logger;
    private readonly IMemoryCache _cache;
    private static ReaderWriterLockSlim cacheLock = new ReaderWriterLockSlim();

    public PageElementController(ILogger<PageElementController> logger, IMemoryCache memoryCache)
    {
        _logger = logger;
        _cache = memoryCache;
    }

    [HttpPost]
    public ActionResult UpdateElement([FromBody] ElementUpdateRequest request)
    {
        if (!IsValidSession(request.Token))
            return Unauthorized();

        var cacheKey = $"{request.PageSectionId}_{request.ElementId}";
        try
        {
            // Acquire a write lock to prevent race conditions
            cacheLock.EnterWriteLock();

            if (_cache.TryGetValue(cacheKey, out string htmlContent))
            {
                _logger.LogInformation("Cache hit for key: {key}", cacheKey);
                htmlContent = request.HtmlContent; // Update the cached content
            }
            else
            {
                _logger.LogDebug("Cache miss for key: {key}", cacheKey);
                htmlContent = GetElementFromDatabase(request.PageSectionId, request.ElementId);
                var cacheEntryOptions = new MemoryCacheEntryOptions()
                    .SetSlidingExpiration(TimeSpan.FromSeconds(60)); // Cache options can be configured externally

                _cache.Set(cacheKey, htmlContent, cacheEntryOptions);
            }
        }
        finally
        {
            // Always release the lock
            cacheLock.ExitWriteLock();
        }

        return Ok();
    }

