['Here is a basic implementation of your request using Node.js with `fs` and `path` modules for filesystem operations and `glob` module for recursive directory traversal. This code does not handle network bandwidth constraints or available disk space as those are system-specific and would require additional libraries/APIs to accurately measure, which is beyond the scope of this task.

```javascript
const fs = require('fs');
const path = require('path');
const glob = require("glob");

async function readFiles(dirPath, extension, size) {
    const startTime = Date.now();
    let filesProcessed = 0;
    let totalDelay = 0;

    console.log(`Starting to process files in ${dirPath}...`);

    try {
        // Get all file paths recursively from the directory
        const files = await new Promise((resolve, reject) => {
            glob(`${dirPath}/**/*`, (err, files) => {
                if (err) reject(err);
                else resolve(files);
            });
        });

        // Filter out files based on extension and size criteria
        const filteredFiles = files.filter((file) => {
            const stats = fs.statSync(file);

            if (stats.isFile() && path.extname(file) === `.${extension}` && stats.size > size) {
                return true;
            }

            return false;
        });

        // Get file details and add to result array
        const result = [];
        for (let i = 0; i < filteredFiles.length; i++) {
            const startProcessTime = Date.now();
            filesProcessed += 1;

            try {
                const stats = fs.statSync(filteredFiles[i]);

                result.push({
                    name: path.basename(filteredFiles[i]),
                    lastModified: stats.mtime,
                    size: stats.size
                });
            } catch (err) {
                console.error(`Error processing file ${filteredFiles[i]}`);
            }

            const delay = Date.now() - startProcessTime;
            totalDelay += delay;
        }

        // Log metrics
        const executionTime = (Date.now() - startTime) / 1000;
        console.log(`Processed ${filesProcessed} files in ${executionTime} seconds with an average processing time of ${(totalDelay / filesProcessed).toFixed(2)} ms per file.`);

        return result;
    } catch (err) {
        console.error('Error reading directory:', err);
        throw err;
    }
}
```
This function reads all files in a specified directory and its subdirectories, filters out those that do not meet the extension and size criteria, and returns an array of objects containing file name, last modified timestamp, and size. It also logs metrics about its execution including total processing time, average processing time per file, and number of processed files.
']

