async function runTests(modulePath, tests, config) {
  const logger = pino({ level: config.logLevel || 'info' });
  let module;

  try {
    module = await import(modulePath);
  } catch (error) {
    logger.error('Failed to load module', error);
    return;
  }

  for (const test of tests) {
    if (!shouldRunTest(test, config)) continue; // Skip test based on conditions or tags

    const startTime = Date.now();
    logger.info({ module: modulePath, test: test.name }, 'Starting test');

    try {
      await blueslip.mockAsync(test);

      // Run the test
      await test(module);

      newrelic.recordMetric('TestSuccess', 1);
      logger.info({ module: modulePath, test: test.name }, 'Test succeeded');
    } catch (error) {
      newrelic.recordMetric('TestFailure', 1);
      logger.error({ module: modulePath, test: test.name }, 'Test failed', error);
    } finally {
      const endTime = Date.now();
      logger.info({ module: modulePath, test: test.name, duration: endTime - startTime }, 'Finished test');

      blueslip.resetAllMocks(); // Reset mocking library after each test
    }
  }
}

function shouldRunTest(test, config) {
  // Implement your own logic here to determine whether a test should be run based on conditions or tags
  return true;
}
