["Here's a basic implementation of such function using Node.js with Express framework for handling HTTP requests. This example assumes that you have access to a database (in this case, MongoDB) and an external API for stop word filtering. 

```javascript
const express = require('express');
const app = express();
const mongoose = require('mongoose');
const fetch = require('node-fetch');
app.use(express.json());

// Connect to MongoDB
mongoose.connect('mongodb://localhost/ecommerce', { useNewUrlParser: true, useUnifiedTopology: true });

// Define a schema for product categories
const categorySchema = new mongoose.Schema({
  name: String,
});

// Create a model based on the schema
const Category = mongoose.model('Category', categorySchema);

app.post('/query', async (req, res) => {
  const queryString = req.body.query;

  // Fetch stop words from external API
  const response = await fetch('https://stopwords-api.com/get');
  const stopWords = await response.json();

  // Extract categories from the query string
  let categories = queryString.match(/\b\w+\b/g);

  if (!categories) {
    return res.status(400).send({ error: 'No valid categories found in the query' });
  }

  // Remove stop words and generic terms from the list of categories
  categories = categories.filter((category) => !stopWords.includes(category));

  if (!categories.length) {
    return res.status(400).send({ error: 'No valid categories found in the query after removing stop words' });
  }

  // Count occurrences of each category in the database
  const counts = {};
  for (const category of categories) {
    const count = await Category.countDocuments({ name: category });
    if (count > 0) {
      counts[category] = count;
    }
  }

  res.send(counts);
});

app.listen(3000, () => console.log('Server is running on port 3000'));
```
This code uses MongoDB as a database to store product categories and counts the occurrences of each category in the query string. It fetches stop words from an external API and removes them from the list of categories before counting their occurrences. The function returns an object where each key is a category name and its value is the number of times it appears in the query string.
"]

