class DataCollector {
    constructor() {
        this.streams = [];
        this.isPaused = false;
    }

    addStream(stream) {
        this.streams.push(stream);
    }

    async startCollection() {
        if (this.isPaused) return;

        // Notify monitoring service about the start of data collection
        await notifyMonitoringService('start');

        for (let stream of this.streams) {
            try {
                let data = await stream.getData();

                // Process the data here...

            } catch(error) {
                console.log("Error occurred while collecting data: ", error);
            }
        }
    }

    pauseCollection() {
        this.isPaused = true;

        // Notify monitoring service about the pause of data collection
        notifyMonitoringService('pause');
    }

    resumeCollection() {
        if (this.isPaused) {
            this.isPaused = false;

            // Notify monitoring service about the resume of data collection
            notifyMonitoringService('resume');

            this.startCollection();
        }
    }

    stopCollection() {
        this.streams = [];

        // Notify monitoring service about the stop of data collection
        notifyMonitoringService('stop');
    }
}

async function notifyMonitoringService(eventType) {
