Here is the C function for DNS resolution:

```c
#include <stdio.h>
#include <string.h>
#include <netdb.h>
#include <sys/types.h>
#include <arpa/inet.h>

typedef unsigned char u_char;

int resolveDNS(const char *hostname, u_char ip[INET6_ADDRSTRLEN]) {
    struct addrinfo hints, *res = NULL;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1; // Error occurred
    }

    void *addr = NULL;
    for (struct addrinfo *p = res; p != NULL; p = p->ai_next) {
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            break;
        } else if (p->ai_family == AF_INET6) { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            break;
        }
    }

    if (addr != NULL) {
        inet_ntop(res->ai_family, addr, ip, INET6_ADDRSTRLEN);
    } else {
        fprintf(stderr, "No address found for hostname: %s\n", hostname);
        return -2; // No address found
    }

    freeaddrinfo(res);
    return 0; // Success
}
```
