#include <stdlib.h>
#include <time.h>

typedef struct {
    int sessionId;
    double avgPacketSize;
    int totalPacketsProcessed;
    double maxBandwidthUsage;
} SessionMetrics;

typedef struct Node {
    SessionMetrics* metrics;
    time_t lastActiveTime;
    struct Node* next;
} Node;

Node* head = NULL;

void processSession(int sessionId, int packetSize) {
    // Find the node for this session or create a new one if it doesn't exist.
    Node** ppNode = &head;
    while (*ppNode != NULL && (*ppNode)->metrics->sessionId != sessionId) {
        ppNode = &((*ppNode)->next);
    }

    if (*ppNode == NULL) {
        *ppNode = malloc(sizeof(Node));
        (*ppNode)->metrics = calloc(1, sizeof(SessionMetrics));
        (*ppNode)->metrics->sessionId = sessionId;
        (*ppNode)->next = NULL;
    }

    // Update the metrics for this session.
    SessionMetrics* metrics = (*ppNode)->metrics;
    time_t now = time(NULL);
    if (now - metrics->lastActiveTime > 100) {
        metrics->avgPacketSize = 0;
        metrics->totalPacketsProcessed = 0;
    }

    metrics->avgPacketSize = (metrics->avgPacketSize * metrics->totalPacketsProcessed + packetSize) / (metrics->totalPacketsProcessed + 1);
    metrics->totalPacketsProcessed++;
    metrics->maxBandwidthUsage = fmax(metrics->maxBandwidthUsage, packetSize);

    (*ppNode)->lastActiveTime = now;
}

void cleanupInactiveSessions() {
    time_t now = time(NULL);
    Node** ppNode = &head;
    while (*ppNode != NULL) {
        if (now - (*ppNode)->lastActiveTime > 5) {
            // This session is inactive, so remove it from the list.
            Node* next = (*ppNode)->next;
            free((*ppNode)->metrics);
            free(*ppNode);
            *ppNode = next;
        } else {
            ppNode = &((*ppNode)->next);
        }
    }
}
```
This code maintains a linked list of session nodes, each containing the metrics for one session. The `processSession` function updates these metrics based on new packets received from that session. If a session is inactive (i.e., hasn't had any packets processed in the last 5 seconds), it's removed from the list to free up memory and resources.

Please note that this code does not include any specific tuning for packet frequency or bandwidth thresholds, nor does it return a structured report of session statistics. You would need to add these features as needed based on your specific requirements. Also, you may want to use more efficient data structures or algorithms if performance is a concern (e.g., using a hash table instead of a linked list for faster lookup).
"]

