typedef struct DOMNode {
    char* class;
    char* id;
    char* textContent;
    int numChildren;
    struct DOMNode** children;
} DOMNode;

char* processDOMTree(DOMNode* root, char* resultBuffer, size_t limit, 
                     int (*matchElement)(const char*, const char*)) {
    if (root == NULL || matchElement == NULL) return resultBuffer;

    for (int i = 0; i < root->numChildren; ++i) {
        DOMNode* child = root->children[i];

        if (matchElement(child->class, child->id)) {
            char* content = child->textContent ? child->textContent : "N/A";

            size_t newLength = strlen(resultBuffer) + strlen(content);
            if (newLength > limit) return NULL;

            strncat(resultBuffer, content, limit - strlen(resultBuffer));
        }

        processDOMTree(child, resultBuffer, limit, matchElement);
    }

    return resultBuffer;
}
```
