using NLog; // Assuming you are using NLog as logging framework

public class WebsiteManager
{
    private static Logger logger = LogManager.GetCurrentClassLogger();

    public void StartWebsite(string directoryPath, string siteName)
    {
        try
        {
            var directoryInfo = new DirectoryInfo(directoryPath);

            if (!directoryInfo.Exists)
            {
                logger.Error("Directory does not exist");
                return;
            }

            var webConfigFilePath = Path.Combine(directoryPath, "web.config");
            var webConfigFileInfo = new FileInfo(webConfigFilePath);

            if (!webConfigFileInfo.Exists)
            {
                logger.Error("Web.config file does not exist in the directory");
                return;
            }

            // Checking permissions and applying them if necessary is a complex task 
            // that depends on your specific requirements, so it's omitted here.

            var processStartInfo = new ProcessStartInfo()
            {
                FileName = "iisexpress",
                Arguments = $"/path:\"{directoryPath}\" /port:8080",
                UseShellExecute = false,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                CreateNoWindow = true
            };

            using (var process = new Process { StartInfo = processStartInfo })
            {
                process.OutputDataReceived += (sender, eventArgs) => logger.Debug(eventArgs.Data);
                process.ErrorDataReceived += (sender, eventArgs) => logger.Error(eventArgs.Data);

                if (!process.Start())
                {
                    logger.Error("Failed to start the website");
                    return;
                }

                process.BeginOutputReadLine();
                process.BeginErrorReadLine();
                process.WaitForExit();
            }
        }
        catch (Exception ex)
        {
            logger.Fatal(ex, "An unexpected error occurred");
        }
    }
}
