['Here is a basic implementation of your request in C# using System.Security.Cryptography namespace for TripleDES decryption and Convert.FromBase64String() method for Base64 decoding. 

```csharp
using System;
using System.IO;
using System.Text;
using System.Security.Cryptography;

public class Decoder
{
    private static readonly Dictionary<string, TripleDES> CipherCache = new Dictionary<string, TripleDES>();

    public string Decode(string base64EncodedMessage, byte[] key, byte[] iv, CipherMode mode)
    {
        try
        {
            var cipherKey = $"{Convert.ToBase64String(key)}_{mode}";

            if (!CipherCache.ContainsKey(cipherKey))
            {
                using (var tripleDes = TripleDES.Create())
                {
                    tripleDes.Mode = mode;
                    tripleDes.Padding = PaddingMode.PKCS7;
                    tripleDes.Key = key;
                    tripleDes.IV = iv;

                    CipherCache[cipherKey] = tripleDes;
                }
            }

            var cipher = CipherCache[cipherKey];

            using (var decryptor = cipher.CreateDecryptor(key, iv))
            {
                byte[] encryptedMessageBytes = Convert.FromBase64String(base64EncodedMessage);

                using (MemoryStream msDecrypt = new MemoryStream(encryptedMessageBytes))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            return srDecrypt.ReadToEnd();
                        }
                    }
                }
            }
        }
        catch (CryptographicException e)
        {
            Console.WriteLine("Error: Key not valid or input is malformed.");
            return string.Empty;
        }
    }
}
```

This code creates a TripleDES decryption cipher using the provided key and IV, then uses it to decrypt the Base64-encoded message. It also implements a simple cache for reusing existing ciphers with the same key and mode, which can improve performance when decoding multiple messages that use the same key and mode.

Please note that this is a basic implementation and may need further optimization or adjustments based on your specific requirements and constraints. For example, you might want to add more robust error handling, logging, or caching strategies. Also, be aware of potential security implications when using Triple DES with ECB mode as it's considered insecure for most applications.
