['Here's a basic implementation of your requirements using C# and .NET Core. This code uses in-memory storage for simplicity, but you could easily modify it to use persistent storage like SQL Server or another database system. 

```csharp
using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class HashProcessor
{
    private readonly ILogger<HashProcessor> _logger;
    private readonly ConcurrentDictionary<string, string> _hashes = new ConcurrentDictionary<string, string>();
    private SemaphoreSlim _semaphore = new SemaphoreSlim(10); // Adjust this value based on your needs.

    public HashProcessor(ILogger<Hashprocessor> logger)
    {
        _logger = logger;
    }

    public async Task ProcessAsync(string[] stringsToProcess, CancellationToken cancellationToken)
    {
        var tasks = new List<Task>();

        foreach (var str in stringsToProcess)
        {
            await _semaphore.WaitAsync(cancellationToken);

            tasks.Add(Task.Run(() => ProcessString(str), cancellationToken));
        }

        // Wait for all tasks to complete.
        await Task.WhenAll(tasks);
    }

    private async Task ProcessString(string str)
    {
        try
        {
            using (var sha256 = SHA256.Create())
            {
                var bytes = Encoding.UTF8.GetBytes(str);
                var hashBytes = await sha256.ComputeHashAsync(new MemoryStream(bytes));
                var hash = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

                _hashes[str] = hash;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to process string: {str}");
        }
        finally
        {
            _semaphore.Release();
        }
    }

    public string GetHash(string str)
    {
        if (_hashes.TryGetValue(str, out var hash))
        {
            return hash;
        }

        throw new KeyNotFoundException($"No hash found for string: {str}");
    }
}
```
This code uses a `ConcurrentDictionary` to store the hashes in memory. It also uses a `SemaphoreSlim` to limit the number of concurrent tasks, which can help manage resource utilization and prevent overloading your system or API with too many requests at once. 

The logging level and format are determined by the configuration provided when setting up the logger. This could be adjusted based on whether you're running in a development environment or production environment. 

Please note that this is a basic implementation and may need to be adapted for your specific use case, such as adjusting the concurrency limit or using persistent storage instead of an in-memory dictionary.
