public class AesDecryptionService
{
    private readonly ILogger<AesDecryptionService> _logger;
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly CipherMode _cipherMode;

    public AesDecryptionService(ILogger<AesDecryptionService> logger, byte[] key, byte[] iv, CipherMode cipherMode)
    {
        _logger = logger;
        _key = key;
        _iv = iv;
        _cipherMode = cipherMode;
    }

    public byte[] Decrypt(byte[] cipherText)
    {
        try
        {
            using var aesAlgorithm = Aes.Create();
            aesAlgorithm.Key = _key;
            aesAlgorithm.IV = _iv;
            aesAlgorithm.Mode = _cipherMode;
            aesAlgorithm.Padding = PaddingMode.PKCS7;

            var decryptor = aesAlgorithm.CreateDecryptor(aesAlgorithm.Key, aesAlgorithm.IV);

            using var memoryStream = new MemoryStream(cipherText);
            using var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read);
            using var outputStream = new MemoryStream();

            cryptoStream.CopyTo(outputStream);

            return outputStream.ToArray();
        }
        catch (CryptographicException e)
        {
            _logger.LogError("Decryption failed: " + e.Message);
            throw;
        }
    }
}
