And here is the Java method `establishAndManageConnection`:

```java
import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class ConnectionManager {
    private static final int MAX_RETRIES = 3;
    private static final long INITIAL_BACKOFF = 1000L; // 1 second

    public interface ConnectionListener {
        void onConnectionEstablished();
        void onActiveState(boolean active);
        void onDisconnected();
    }

    private SocketChannel channel;
    private ExecutorService executor = Executors.newSingleThreadExecutor();
    private ScheduledExecutorService retryScheduler = Executors.newSingleThreadScheduledExecutor();
    private ConnectionListener listener;

    public void establishConnection(String host, int port) {
        connectWithRetry(host, port, 0);
    }

    private void connectWithRetry(final String host, final int port, final int retryCount) {
        Future<?> future = executor.submit(() -> {
            try {
                channel = SocketChannel.open();
                channel.configureBlocking(false);
                boolean connected = channel.connect(new InetSocketAddress(host, port));

                if (connected || retryCount >= MAX_RETRIES) {
                    listener.onConnectionEstablished();
                    startListeningForChanges();
                } else {
                    long backoff = INITIAL_BACKOFF * ((long) Math.pow(2, retryCount)); // Exponential backoff
                    retryScheduler.schedule(() -> connectWithRetry(host, port, retryCount + 1), backoff, TimeUnit.MILLISECONDS);
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        });

        try {
            future.get(); // Wait for the connection to finish or timeout.
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        }
    }

    private void startListeningForChanges() {
        executor.submit(() -> {
            while (!Thread.currentThread().isInterrupted()) {
                try {
                    boolean connected = channel.finishConnect(); // Blocking operation.
                    listener.onActiveState(connected);

                    if (!connected) {
                        listener.onDisconnected();
                        break;
                    }
                } catch (IOException e) {
                    listener.onActiveState(false);
                }
            }
        });
    }

    public void setConnectionListener(ConnectionListener listener) {
        this.listener = listener;
    }

    public void close() throws IOException {
        executor.shutdownNow();
        retryScheduler.shutdownNow();

        if (channel != null && channel.isOpen()) {
            channel.close();
        }
    }
}
```
