['Here is a basic implementation in C using POSIX threads (pthreads) for threading and mutexes for synchronization. This code does not include the external authentication service call, which would require network programming to implement correctly. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct UserSession {
    char username[256];
    int sessionID;
    time_t lastActivityTimestamp;
    char ipAddress[16];
} UserSession;

UserSession* sessions[500] = {NULL};
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addSession(char* username, int sessionID, char* ipAddress) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < 500; ++i) {
        if (sessions[i] == NULL) {
            sessions[i] = malloc(sizeof(UserSession));
            strcpy(sessions[i]->username, username);
            sessions[i]->sessionID = sessionID;
            time(&sessions[i]->lastActivityTimestamp);
            strcpy(sessions[i]->ipAddress, ipAddress);

            printf("Added session for user %s\n", username);
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void removeSession(int sessionID) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < 500; ++i) {
        if (sessions[i] != NULL && sessions[i]->sessionID == sessionID) {
            free(sessions[i]);
            sessions[i] = NULL;

            printf("Removed session with ID %d\n", sessionID);
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}
```
This code provides a basic implementation of adding and removing sessions from the list. It uses a mutex to ensure that only one thread can modify the `sessions` array at a time, preventing race conditions. 

