const axios = require('axios');
const fs = require('fs');
const path = require('path');
const mime = require('mime-types');
const asyncPool = require('tiny-async-pool');

// Define constants for file size and type validation
const MAX_FILE_SIZE = 1024 * 1024; // 1MB
const ALLOWED_TYPES = ['image/jpeg', 'image/png'];

// Define the upload function
async function uploadFile(filePath, token) {
    const startTime = Date.now();
    let fileSize = 0;
    try {
        // Validate file size and type
        const stats = fs.statSync(filePath);
        fileSize = stats['size'];
        if (fileSize > MAX_FILE_SIZE) throw new Error('File too large');

        const contentType = mime.lookup(path.extname(filePath));
        if (!ALLOWED_TYPES.includes(contentType)) throw new Error('Invalid file type');

        // Upload the file using axios (or any other HTTP client)
        const response = await axios({
            method: 'post',
            url: 'https://example.com/upload',
            headers: { Authorization: `Bearer ${token}` },
            data: fs.createReadStream(filePath),
        });

        const endTime = Date.now();
        return {
            fileName: path.basename(filePath),
            url: response.data.url,
            startTime,
            endTime,
            duration: (endTime - startTime) / 1000,
            size: fileSize,
            status: 'success',
        };
    } catch (error) {
        console.log(`Error uploading ${filePath}: ${error}`);
        return {
            fileName: path.basename(filePath),
            startTime,
            endTime: Date.now(),
            size: fileSize || 0,
            status: 'failure',
            error: error.message,
        };
    }
}

// Define the main function that manages multiple uploads concurrently
async function manageUploads(filePaths, token) {
    const reports = await asyncPool(10, filePaths, (filePath) => uploadFile(filePath, token));

    // Log a summary of all uploads
    console.log('Upload Summary:');
    reports.forEach((report) => {
        console.log(`- ${report.status === 'success' ? '✅' : '❌'} ${report.fileName} (${report.size} bytes, took ${report.duration}s)`);
    });

    return reports;
}
```
