#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    time_t timestamp;
    long value;
} Record;

Record* database = NULL;
const size_t DB_SIZE = 10000000; // 10 million records
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Custom random number generator
long custom_random(long min, long max) {
    return rand() % (max - min + 1) + min;
}

void* init_record(void* arg) {
    int index = *((int*)arg);

    pthread_mutex_lock(&lock); // Lock to ensure thread-safety

    database[index].key = index;
    database[index].timestamp = time(NULL);
    database[index].value = custom_random(0, 1000000); // Assuming value range is [0, 1000000]

    pthread_mutex_unlock(&lock); // Unlock after operation

    return NULL;
}

void init_database() {
    srand(time(NULL)); // Seed the random number generator

    database = (Record*)malloc(DB_SIZE * sizeof(Record));

    pthread_t threads[DB_SIZE];
    int indices[DB_SIZE];

    for (size_t i = 0; i < DB_SIZE; ++i) {
        indices[i] = i;
        pthread_create(&threads[i], NULL, init_record, &indices[i]);
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < DB_SIZE; ++i) {
        pthread_join(threads[i], NULL);
    }
}
```
This code creates a database of 10 million records, each with a unique key and a random value within the range [0, 1000000]. It uses a custom random number generator to ensure that all values are within this range. The `init_database` function initializes the database by creating one thread for each record, which locks the mutex before modifying the record and then unlocks it after. This ensures that no two threads can modify the same record at the same time, preventing data corruption or race conditions.

