        newRecord->value = rand() % (max - min + 1) + min;
        sprintf(newRecord->log, "Initialized with value: %d", newRecord->value);
        newRecord->status = true;

        records[i] = newRecord;
        systemStatus.activeRecords++;
    }

    systemStatus.mode = true;
}

void updateFromExternalSource() {
    // Simulate latency and potential connectivity issues
    struct timespec ts = {0, 50000000}; // 50ms delay
    nanosleep(&ts, NULL);

    for (size_t i = 0; i < systemStatus.activeRecords; ++i) {
        records[i]->value++;
        sprintf(records[i]->log, "Updated from external source. New value: %d", records[i]->value);
    }
}

void deinitSystem() {
    for (size_t i = 0; i < systemStatus.activeRecords; ++i) {
        free(records[i]);
    }

