typedef struct IP_NODE {
    char* ip;
    int count;
    struct IP_NODE* next;
} IP_NODE;

IP_NODE* add_node(char* ip, IP_NODE* head) {
    IP_NODE* newNode = (IP_NODE*)malloc(sizeof(IP_NODE));
    if (!newNode) {
        printf("Memory allocation failed.\n");
        exit(1);
    }

    newNode->ip = strdup(ip);
    newNode->count = 1;
    newNode->next = head;
    return newNode;
