void find_frequent_ip(IP_NODE* head) {
    if (!head) {
        printf("List is empty.\n");
        return;
    }

    IP_NODE* maxNode = head;
    int maxCount = 0;

    for (IP_NODE* node = head; node != NULL; node = node->next) {
        if (node->count > maxCount) {
            maxNode = node;
            maxCount = node->count;
        }
    }

    printf("Most frequent IP: %s\n", maxNode->ip);
}

int main() {
    char ip[16];
    IP_NODE* head = NULL;

    while (scanf("%s", ip) != EOF) {
        int found = 0;

        for (IP_NODE* node = head; node != NULL; node = node->next) {
            if (strcmp(node->ip, ip) == 0) {
                node->count++;
                found = 1;
                break;
            }
        }

        if (!found) {
            head = add_node(ip, head);
        }
    }

    find_frequent_ip(head);

    while (head != NULL) {
        IP_NODE* nextNode = head->next;
        free(head->ip);
        free(head);
        head = nextNode;
    }

    return 0;
}
