        pthread_mutex_lock(&lock);
        packets[i].payload = uniqueId;
        packets[i].timestamp = time(NULL);
        log("Successfully allocated packet with id: %d", uniqueId);
        pthread_mutex_unlock(&lock);
    }

    return packets;
}
