#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    int RX_UE_INFORMATION_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* head = NULL;
Node* tail = NULL;
int count = 0;
pthread_mutex_t lock;

void add(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if(newNode == NULL) {
        // Handle memory allocation failure
        return;
    }

    srand(time(NULL));
    int randomNumber = rand() % 10 + 1;
    data.CRCFLAG = (randomNumber <= 7) ? 1 : 0;

    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = head;

    pthread_mutex_lock(&lock);
    if(head != NULL) {
        head->prev = newNode;
    } else {
        tail = newNode;
    }
    head = newNode;
    count++;
    pthread_mutex_unlock(&lock);
}

void clear() {
    Node* current = head;

    while(current != NULL) {
        Node* temp = current;
        current = current->next;

        free(temp);
    }

    pthread_mutex_lock(&lock);
    count = 0;
    head = tail = NULL;
    pthread_mutex_unlock(&lock);
}
```
This code creates a doubly linked list and provides functions to add elements at the beginning of the list (add) and clear the entire list (clear). It also uses a mutex for thread-safety. The CRCFLAG is set based on a random number generator, with a 70% chance of being set to 1 and a 30% chance of being set to 0.
