    manager->structures = malloc(10000 * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    manager->count = 0;
    manager->capacity = 10000;
    manager->config.characterSet = characterSet;
    manager->config.stringLength = stringLength;
    manager->config.hashFunction = hashFunction;
}

void addStructure(StructureManager* manager, NFAPI_CRC_INDICATION_PDU_T* structure) {
    pthread_mutex_lock(&manager->config.lock);
    if (manager->count == manager->capacity) {
        log4c_category_log(manager->config.log_category, LOG4C_PRIORITY_ERROR, "Manager capacity exceeded");
        return;
    }
    manager->structures[manager->count++] = structure;
    pthread_mutex_unlock(&manager->config.lock);
}

void removeStructure(StructureManager* manager, NFAPI_CRC_INDICATION_PDU_T* structure) {
    pthread_mutex_lock(&manager->config.lock);
    for (size_t i = 0; i < manager->count; ++i) {
