            free(structure);
            manager->structures[i] = manager->structures[--manager->count];
            break;
        }
    }
    pthread_mutex_unlock(&manager->config.lock);
}

void generateAndHashString(NFAPI_CRC_INDICATION_PDU_T* structure, ManagerConfig* config) {
    unsigned char* string = malloc((config->stringLength + 1) * sizeof(char));
    for (size_t i = 0; i < config->stringLength; ++i) {
        string[i] = config->characterSet[rand() % strlen(config->characterSet)];
