    string[config->stringLength] = '\0';

    unsigned char hash[32]; // Assuming SHA-256
    config->hashFunction((const unsigned char*)string, strlen(string), hash);

    free(structure->CRC_INDICATION_REL8_TAG);
    structure->CRC_INDICATION_REL8_TAG = malloc((2 * 32 + 1) * sizeof(char));
    for (size_t i = 0; i < 32; ++i) {
