typedef struct {
    int id;
    time_t timestamp;
    double value;
} Event;

Event* events[10];
int eventCount = 0;
size_t totalMemoryUsed = 0;

void addEvent(int id, time_t timestamp, double value) {
    if (eventCount >= 10) {
        printf("Maximum number of events reached.\n");
        return;
    }

    Event* event = malloc(sizeof(Event));
    if (event == NULL) {
        printf("Failed to allocate memory for new event.\n");
        return;
    }

    event->id = id;
    event->timestamp = timestamp;
    event->value = value;

    events[eventCount++] = event;
    totalMemoryUsed += sizeof(Event);
}

void printEvents() {
    for (int i = 0; i < eventCount; ++i) {
        printf("Event %d: ID=%d, Timestamp=%ld, Value=%.2f\n", 
               i + 1, events[i]->id, events[i]->timestamp, events[i]->value);
    }

    double averageMemoryPerEvent = (double)totalMemoryUsed / eventCount;
    printf("Total memory used: %zu bytes\n", totalMemoryUsed);
    printf("Average memory per event: %.2f bytes\n", averageMemoryPerEvent);
}

int main() {
    srand(time(NULL));

    for (int i = 0; i < 15; ++i) {
        int id = rand();
        time_t timestamp = time(NULL);
        double value = ((double)rand() / RAND_MAX) * 100.0;

        addEvent(id, timestamp, value);
    }

    printEvents();

    for (int i = 0; i < eventCount; ++i) {
        free(events[i]);
    }

    return 0;
}
