['Here is a basic implementation in C that meets your requirements. This code uses pthreads for thread safety when initializing unique identifiers. It also uses realloc to dynamically resize the array as needed. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* key;
    size_t length;
    float value;
} Entry;

Entry* entries = NULL;
size_t capacity = 0;
size_t size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_entry(char* key, float value) {
    pthread_mutex_lock(&lock);

    if (size >= capacity) {
        // Double the capacity each time we need to resize.
        capacity = capacity == 0 ? 1 : capacity * 2;
        entries = realloc(entries, sizeof(Entry) * capacity);

        if (!entries) {
            printf("Failed to allocate memory for new entry.\n");
            exit(EXIT_FAILURE);
        }
    }

    Entry* new_entry = &entries[size++];
    new_entry->key = strdup(key);  // Duplicate the key string.
    new_entry->length = strlen(key);
    new_entry->value = value;

    pthread_mutex_unlock(&lock);
}

void print_entries() {
    for (size_t i = 0; i < size; ++i) {
        Entry* entry = &entries[i];
        printf("Key: %s, Length: %zu, Value: %f\n", entry->key, entry->length, entry->value);
    }
}

void free_entries() {
    for (size_t i = 0; i < size; ++i) {
        free(entries[i].key);  // Free the duplicated key string.
    }

    free(entries);  // Free the entries array.
}
```

This code is a basic example and may need to be adjusted based on your specific needs, such as error handling or thread safety in other parts of your application. For instance, you might want to use more sophisticated memory management techniques if you expect to have many threads adding entries concurrently. 

Also note that this implementation does not handle the case where `realloc` fails due to insufficient memory. In a real-world scenario, you would need to add appropriate error handling for these cases.
']

