typedef struct {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *data;
} DynamicList;

DynamicList* createList(size_t initialCapacity) {
    if (initialCapacity <= 0) return NULL;

    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = initialCapacity;
    list->size = 0;

    return list;
}

int addElement(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list) return -1;

    if (list->size == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!newData) return -1;

        list->capacity = newCapacity;
        list->data = newData;
    }

    memcpy(&list->data[list->size], &element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size++;

    return 0;
}

void freeList(DynamicList *list) {
    if (list) {
        free(list->data);
        free(list);
    }
}
```
This code creates a dynamic list that grows as needed. It uses `realloc` to increase the size of the array when it is full, which avoids copying all elements each time. The `addElement` function checks if there's enough space in the list and copies the new element into the next available slot. If not, it doubles the size of the list using `realloc`.

