NFAPI_CRC_INDICATION_PDU_T* generateNfaApiIndications(const char* charset, size_t strlen, const EVP_MD* (*hash)(void), int max_indications, const char* password) {
    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * max_indications);
