    unsigned char hash_result[EVP_MAX_MD_SIZE];
    unsigned int hash_len;
    EVP_Digest(password, strlen(password), hash_result, &hash_len, hash(), NULL);

    for (int i = 0; i < max_indications; ++i) {
        indications[i].random_str = malloc(strlen + 1);
        if (indications[i].random_str == NULL) return NULL; // handle allocation error

        RAND_pseudo_bytes((unsigned char*)indications[i].random_str, strlen);
        for (size_t j = 0; j < strlen; ++j) {
            indications[i].random_str[j] = charset[indications[i].random_str[j] % strlen(charset)];
