['Here is a basic implementation of such a function in C using POSIX threads (pthreads) for synchronization and dynamic resizing with error handling. This code does not include real-time data source integration, as it would require additional context or specific details about the data source to be implemented correctly. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int ueId;
    int rnti;
    int crcIndication;
} UEContextInfo;

typedef struct {
    pthread_mutex_t lock;
    UEContextInfo *contexts;
    size_t maxSize;
    size_t currentSize;
} ContextManager;

void initContextManager(ContextManager *manager, size_t initialSize, size_t maxSize) {
    manager->maxSize = maxSize;
    manager->currentSize = 0;
    pthread_mutex_init(&manager->lock, NULL);

    manager->contexts = (UEContextInfo*) malloc(initialSize * sizeof(UEContextInfo));
    if (manager->contexts == NULL) {
        // Handle memory allocation failure
        exit(-1);
    }
}

void addContext(ContextManager *manager, UEContextInfo context) {
    pthread_mutex_lock(&manager->lock);

    if (manager->currentSize >= manager->maxSize) {
        // Handle maximum size reached
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    if (manager->currentSize == manager->maxSize / 2) {
        // Resize array when half full
        UEContextInfo *newArray = realloc(manager->contexts, manager->maxSize * sizeof(UEContextInfo));
        if (newArray == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        manager->contexts = newArray;
    }

    manager->contexts[manager->currentSize++] = context;

    pthread_mutex_unlock(&manager->lock);
}

void updateContext(ContextManager *manager, int ueId, int crcIndication) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->currentSize; ++i) {
        if (manager->contexts[i].ueId == ueId) {
            manager->contexts[i].crcIndication = crcIndication;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}
```
This code provides a basic thread-safe context management system. It uses a mutex to ensure that only one thread can modify the context array at a time, preventing race conditions and data corruption. The `addContext` function dynamically resizes the array when it is half full, ensuring optimal performance under high load conditions. 

Please note that this code does not include real-time updates from an external data source as mentioned in your question. You would need to integrate a mechanism for receiving these updates and calling the `updateContext` function with the new information. This could be done using a separate thread or callback, depending on how you receive the updates.
']

