        arrays->records[i].str = malloc(11);  // "example" plus null terminator.
        if (arrays->records[i].str == NULL) {
            for (size_t j = 0; j < i; ++j) free(arrays->records[j].str);
            free(arrays->offsets);
            free(arrays->keys);
            free(arrays->records);
            free(arrays);
            return NULL;
