['Here is a basic implementation of such a function in C. This code does not include error checking for simplicity but it should give you an idea of how to implement this kind of functionality. 

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

typedef struct Item {
    char* name;
    int priority;
    struct Item *next;
} Item;

Item *head = NULL;
int count = 0;

void add_item(char* name, int priority) {
    if (count >= 10000) {
        printf("Collection is full.\n");
        return;
    }

    Item *new_item = malloc(sizeof(Item));
    new_item->name = strdup(name);
    new_item->priority = priority;
    new_item->next = head;
    head = new_item;
    count++;
}

void remove_item(char* name) {
    Item **link = &head;

    while (*link != NULL) {
        if (strcmp((*link)->name, name) == 0) {
            Item *old_item = *link;
            *link = old_item->next;
            free(old_item->name);
            free(old_item);
            count--;
            return;
        }

        link = &(*link)->next;
    }

    printf("Item not found.\n");
}

void update_priority(char* name, int priority) {
    Item *current = head;

    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            current->priority = priority;
            return;
        }

        current = current->next;
    }

    printf("Item not found.\n");
}

void print_items() {
    Item *current = head;

    while (current != NULL) {
        printf("%s: %d\n", current->name, current->priority);
        current = current->next;
    }
}
```
This code uses a linked list to store the items. Each item is stored in a `struct Item` that contains a pointer to the next item in the list. The `add_item` function adds new items at the beginning of the list, and the `remove_item` function removes an item by name. The `update_priority` function updates the priority level of an existing item.

The code also includes a `print_items` function that prints the name and priority of each item in the collection. This function is used to implement the iterator functionality.

Please note that this is a basic implementation and does not include error checking or other features you might need for a production-quality application, such as thread safety or data validation. You would also likely want to use a more efficient data structure than a linked list if performance is a concern.
