```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <assert.h>

typedef struct {
    void* payload;
    time_t timestamp;
} DataPacket;

typedef struct {
    DataPacket** packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initialCapacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (array == NULL) return NULL;

    array->packets = calloc(initialCapacity, sizeof(DataPacket*));
    if (array->packets == NULL) {
        free(array);
        return NULL;
    }

    array->capacity = initialCapacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->packets[i]);
    }
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_packet(DynamicArray* array, DataPacket* packet) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        DataPacket** newArray = realloc(array->packets, newCapacity * sizeof(DataPacket*));

        if (newArray == NULL) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }

        array->packets = newArray;
        array->capacity = newCapacity;
    }

    array->packets[array->count++] = packet;

    pthread_mutex_unlock(&array->lock);

    return 0;
}
```

