['Here is a basic implementation of such a function using C language. This code does not include all the features you requested but it provides a starting point. It uses pthreads for thread safety, a simple cache to avoid repeated DNS lookups and logs errors with syslog. 

```c
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <unistd.h>
#include <stdlib.h>
#include <errno.h>
#include <syslog.h>

#define MAX_CACHE 1024

typedef struct {
    char *hostname;
    struct addrinfo *addr;
} cache_entry;

cache_entry cache[MAX_CACHE];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
int cache_size = 0;

void log_error(const char *msg) {
    openlog("dns_resolver", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_ERR, "%s: %m\n", msg);
    closelog();
}

struct addrinfo *resolve_hostname(const char *hostname) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; ++i) {
        if (!strcmp(cache[i].hostname, hostname)) {
            struct addrinfo *addr = malloc(sizeof(struct addrinfo));
            memcpy(addr, cache[i].addr, sizeof(struct addrinfo));
            pthread_mutex_unlock(&cache_lock);
            return addr;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int ret = getaddrinfo(hostname, "http", &hints, &res);
    if (ret != 0) {
        log_error("getaddrinfo failed");
        return NULL;
    }

    pthread_mutex_lock(&cache_lock);
    if (cache_size < MAX_CACHE) {
        cache[cache_size].hostname = strdup(hostname);
        cache[cache_size].addr = res;
        ++cache_size;
    } else {
        freeaddrinfo(res);
    }
    pthread_mutex_unlock(&cache_lock);

    return res;
}
