import org.apache.commons.codec.digest.DigestUtils;
import com.google.common.hash.Hashing;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.springframework.web.client.RestTemplate;
import org.springframework.http.*;
import org.apache.commons.lang3.StringUtils;
import com.google.common.collect.Sets;

public class Application {
    private RestTemplate restTemplate = new RestTemplate();

    public String getMD5Hash(String input, String mode) throws Exception {
        switch (mode) {
            case "ECB":
                return Hashing.md5().hashString(input, StandardCharsets.UTF_8).toString();
            case "EDE":
                // Implement EDE mode here
                break;
            case "EDE3":
                // Implement EDE3 mode here
                break;
            case "CFB":
                return DigestUtils.md5Hex(input);
            default:
                throw new Exception("Invalid cryptographic mode");
        }
    }

    public String fetchStringFromAPI() {
        try {
            ResponseEntity<String> response = restTemplate.getForEntity("http://api.example.com/string", String.class);
            if (response.getStatusCode() == HttpStatus.OK && !StringUtils.isEmpty(response.getBody())) {
                return response.getBody();
            } else {
                throw new Exception("Failed to fetch string from API");
            }
        } catch (Exception e) {
            // Handle exception and provide fallback mechanism here
            return "Fallback String";
        }
    }

    public Set<Set<Integer>> findDisjointPairs(int[] array) {
        Map<Integer, Set<Integer>> parent = new HashMap<>();

        for (int num : array) {
            if (!parent.containsKey(num)) {
                parent.put(num, Sets.newHashSet());
            }

            if (parent.containsKey(num - 1)) {
                parent.get(num).addAll(parent.get(num - 1));
                parent.get(num).add(num - 1);
                parent.put(num - 1, parent.get(num));
            }

            if (parent.containsKey(num + 1)) {
                parent.get(num).addAll(parent.get(num + 1));

                for (int neighbor : parent.get(num + 1)) {
                    parent.put(neighbor, parent.get(num));
                }

                parent.get(num).add(num + 1);
            }
        }

        return new HashSet<>(parent.values());
    }

    public static void main(String[] args) throws Exception {
        Application app = new Application();
        String input = app.fetchStringFromAPI();
        System.out.println("MD5 hash: " + app.getMD5Hash(input, "CFB"));

        int[] array = new int[]{1, 2, 3, 7, 8, 9};
        Set<Set<Integer>> disjointPairs = app.findDisjointPairs(array);
        System.out.println("Disjoint pairs: " + disjointPairs);
    }
}
```

This code is a starting point and can be improved in many ways, such as adding more cryptographic modes, handling network failures better, optimizing Union-Find operations, implementing batch processing, etc. Also, it doesn't cover all the points you mentioned due to its complexity but it gives an idea about how to structure such application.
