Profile** createProfiles(size_t numProfiles, size_t maxActionLength) {
    srand((unsigned int)time(NULL));

    Profile** profiles = malloc(numProfiles * sizeof(Profile*));
    if (profiles == NULL) {
        return NULL;  // Failed to allocate memory for profiles array.
    }

    for (size_t i = 0; i < numProfiles; ++i) {
        Profile* profile = malloc(sizeof(Profile));
        if (profile == NULL) {
            return NULL;  // Failed to allocate memory for a single profile.
        }

        size_t numActions = rand() % 10 + 1;  // Random number of actions between 1 and 10.
        Action** actions = malloc(numActions * sizeof(Action*));
        if (actions == NULL) {
            return NULL;  // Failed to allocate memory for actions array.
        }

        for (size_t j = 0; j < numActions; ++j) {
            size_t actionLength = rand() % maxActionLength + 1;  // Random length of the action string.
            char* actionStr = malloc(actionLength * sizeof(char));
            if (actionStr == NULL) {
                return NULL;  // Failed to allocate memory for an action string.
            }

            Action* action = malloc(sizeof(Action));
            if (action == NULL) {
                return NULL;  // Failed to allocate memory for a single action.
            }

            // Generate random action description.
            for (size_t k = 0; k < actionLength - 1; ++k) {
                actionStr[k] = 'a' + rand() % ('z' - 'a');
            }
            actionStr[actionLength - 1] = '\0';

            action->action = actionStr;
            actions[j] = action;
        }

        profile->id = "unique_id";  // Replace with actual unique identifier.
        profile->timestamp = time(NULL);
        profile->actions = actions;
        profile->numActions = numActions;

        profiles[i] = profile;
    }

    return profiles;
}

void freeProfiles(Profile** profiles, size_t numProfiles) {
    for (size_t i = 0; i < numProfiles; ++i) {
        Profile* profile = profiles[i];

        for (size_t j = 0; j < profile->numActions; ++j) {
            free(profile->actions[j]->action);  // Free action string.
            free(profile->actions[j]);  // Free single action.
        }

        free(profile->id);  // Free unique identifier.
        free(profile->actions);  // Free actions array.
        free(profile);  // Free single profile.
    }

    free(profiles);  // Free profiles array.
}
```
