typedef struct {
    FILE *file;
    char *buffer;
    size_t bufferSize;
} FileInfo;

FileInfo openFile(const char *path) {
    FileInfo fileInfo = {NULL, NULL, 0};

    // Open the file
    fileInfo.file = fopen(path, "r+");
    if (fileInfo.file == NULL) {
        perror("Error opening file");
        return fileInfo;
    }

    // Get the size of the file
    fseek(fileInfo.file, 0L, SEEK_END);
    fileInfo.bufferSize = ftell(fileInfo.file);
    rewind(fileInfo.file);

    // Allocate memory for the buffer
    fileInfo.buffer = malloc(fileInfo.bufferSize * sizeof(*fileInfo.buffer));
    if (fileInfo.buffer == NULL) {
        perror("Error allocating memory");
        fclose(fileInfo.file);
        return fileInfo;
    }

    // Read the file into the buffer
    size_t readSize = fread(fileInfo.buffer, sizeof(*fileInfo.buffer), fileInfo.bufferSize, fileInfo.file);
    if (readSize != fileInfo.bufferSize) {
        perror("Error reading file");
        free(fileInfo.buffer);
        fclose(fileInfo.file);
        return fileInfo;
    }

    return fileInfo;
}

void closeFile(FileInfo *fileInfo) {
    if (fileInfo->buffer != NULL) {
        free(fileInfo->buffer);
        fileInfo->buffer = NULL;
    }

    if (fileInfo->file != NULL) {
        fclose(fileInfo->file);
        fileInfo->file = NULL;
    }
}

void encryptFileContents(const char *path, int shouldEncrypt) {
    FileInfo fileInfo = openFile(path);

    if (shouldEncrypt) {
        // Encrypt the buffer using an external library
        encrypt_buffer(fileInfo.buffer, fileInfo.bufferSize);

        // Write the encrypted data back to the file
        rewind(fileInfo.file);
        size_t writeSize = fwrite(fileInfo.buffer, sizeof(*fileInfo.buffer), fileInfo.bufferSize, fileInfo.file);
        if (writeSize != fileInfo.bufferSize) {
            perror("Error writing to file");
        }
    }

    closeFile(&fileInfo);
}
