#include <stdatomic.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node in the list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the linked list
typedef struct LinkedList {
    Node* head;
    atomic_int count;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* createList() {
    LinkedList* list = malloc(sizeof(LinkedList));
    list->head = NULL;
    atomic_init(&list->count, 0);
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = malloc(sizeof(Node));
    newNode->data = data;

    pthread_mutex_lock(&list->lock);
    // Ensure no two consecutive structures in the list share the same RNTI
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == data.RNTI) {
            printf("Error: Duplicate RNTI detected!\n");
            free(newNode);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = current->next;
    }

    newNode->next = list->head;
    list->head = newNode;
    atomic_fetch_add(&list->count, 1);
    pthread_mutex_unlock(&list->lock);
}
```
This is a simple implementation of a linked list with thread safety. It uses a mutex to ensure that only one thread can modify the list at a time. The `insertNode` function checks for duplicate RNTI values before adding a new node to the list, which prevents data corruption during transmission. 

