use std::fs;
use std::path::PathBuf;
use std::env;
use rand::Rng;
use openssl::symm::{Cipher, Crypt, SymmParams};
use openssl::error::ErrorStack;

pub struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG: u8,
    RNTI: u16,
    CRC_INDICATION_REL8_TAG: u32,
}

impl NFAPI_CRC_INDICATION_PDU_T {
    fn new(rnti: u16) -> Self {
        let mut rng = rand::thread_rng();
        NFAPI_CRC_INDICATION_PDU_T {
            RX_UE_INFORMATION_TAG: rng.gen(),
            RNTI: rnti,
            CRC_INDICATION_REL8_TAG: rng.gen(),
        }
    }
}

pub fn create_structures(n: usize) -> Result<Vec<NFAPI_CRC_INDICATION_PDU_T>, ErrorStack> {
    let config_path = env::var("CONFIG_PATH").unwrap_or_else(|_| "config_dir".to_string());
    if !PathBuf::from(&config_path).exists() {
        fs::create_dir_all(&config_path)?;
    }

    let cipher = match env::var("CIPHER") {
        Ok(c) => match c.as_str() {
            "DES-ECB" => Cipher::aes_128_ecb(),
            "DES-EDE" => Cipher::des_ede3(),
            "DES-EDE3" => Cipher::des_ede3(),
            "DES-CFB" => Cipher::des_cfb64(),
            _ => Cipher::null(),
        },
        Err(_) => Cipher::null(),
    };

    let mut structures = Vec::new();
    for i in 0..n {
        structures.push(NFAPI_CRC_INDICATION_PDU_T::new(i as u16));
    }

    Ok((structures, cipher))
}
```
