typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_rwlock_t lock = PTHREAD_RWLOCK_INITIALIZER;
int cacheSize = 0;
time_t lastFlushTime = 0;

void addToList(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    pthread_rwlock_wrlock(&lock);
    if (head == NULL) {
        head = newNode;
    } else {
        Node* temp = head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    cacheSize++;
    pthread_rwlock_unlock(&lock);
}

void flushList() {
    time_t currentTime = time(NULL);
    if (difftime(currentTime, lastFlushTime) >= 60 && cacheSize > 1000) {
        pthread_rwlock_wrlock(&lock);
        Node* temp;
        while (head != NULL) {
            temp = head;
            head = head->next;
            free(temp);
            cacheSize--;
        }
        lastFlushTime = currentTime;
        pthread_rwlock_unlock(&lock);
    }
}
```
