void addStruct(NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&mutex);

    if (currentSize >= maxSize) {
        maxSize *= 2;
        head = realloc(head, sizeof(Node)*maxSize);

        if (!head) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&mutex);
            return;
