        rec->buffer[i] = 'a' + rand() % ('z'-'a');
    }
    rec->buffer[sizeof(rec->buffer)-1] = 0; // null terminate the string

    return NULL;
}

void log_error(const char* message) {
    openlog("record_init", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_ERR, "%s", message);
    closelog();
}

int main() {
