    srand(time(NULL));

    int num_records = 10;
    record *records = malloc(num_records * sizeof(record));
    if (records == NULL) {
        log_error("Failed to allocate memory for records");
        return 1;
    }

    pthread_t threads[num_records];
    int i;
    for (i = 0; i < num_records; ++i) {
        if(pthread_create(&threads[i], NULL, initialize_record, &records[i])) {
            log_error("Failed to create thread");
            return 1;
        }
    }

    for (i = 0; i < num_records; ++i) {
        if(pthread_join(threads[i], NULL)) {
            log_error("Failed to join thread");
            return 1;
        }
    }

    // Clean up allocated resources
    free(records);

    return 0;
}
```
