        if ((*accounts)[i].id == id) {
            strncpy((*accounts)[i].name, name, sizeof((*accounts)[i].name));
            strncpy((*accounts)[i].email, email, sizeof((*accounts)[i].email));
            strncpy((*accounts)[i].password, password, sizeof((*accounts)[i].password));
            (*accounts)[i].timestamp = time(NULL);
            return &(*accounts)[i];
