    DataTransmissionRecord* newRecord = &records[recordCount++];
    newRecord->packetType = packetType;
    newRecord->qosClassId = qosClassId;
    newRecord->latencyValue = latencyValue;

    pthread_mutex_unlock(&mutex);
}
