    size_t len;
    unsigned char *base64_out = base64_encode((unsigned char*)json_str, strlen(json_str), &len);
    pdu->metadata = malloc(len + 1);
    memcpy(pdu->metadata, base64_out, len);
    free(base64_out);

    return pdu;
}

unsigned long calculate_checksum(char* payload) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)payload, strlen(payload), hash);

    // Convert the hash to a single number for simplicity. 
    // This is not secure and should be replaced with a proper checksum algorithm.
    unsigned long checksum = 0;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        checksum = (checksum << 8) + hash[i];
    }

    return checksum;
}
