```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    char status[10]; // active, closed, or pending
} Connection;

Connection* connections[100000];
int connectionCount = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addConnection(int id) {
    pthread_mutex_lock(&lock);

    if (connectionCount < 100000) {
        Connection* newConn = malloc(sizeof(Connection));
        newConn->id = id;
        time(&newConn->timestamp);
        strcpy(newConn->status, "pending");

        connections[connectionCount++] = newConn;
    } else {
        printf("Maximum connection limit reached.\n");
    }

    pthread_mutex_unlock(&lock);
}

void removeConnection(int id) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < connectionCount; ++i) {
        if (connections[i]->id == id) {
            free(connections[i]);

            // Shift all elements after the removed one to fill the gap.
            for (int j = i; j < connectionCount - 1; ++j) {
                connections[j] = connections[j + 1];
            }

            --connectionCount;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void updateConnectionStatus(int id, const char* status) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < connectionCount; ++i) {
        if (connections[i]->id == id) {
            strcpy(connections[i]->status, status);
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}
```
