```C
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    void* payload;
    time_t timestamp;
} DataPacket;

typedef struct {
    DataPacket** packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketArray;

int packet_array_init(PacketArray* array, size_t initialCapacity) {
    array->packets = malloc(sizeof(DataPacket*) * initialCapacity);
    if (array->packets == NULL) return -1;

    array->count = 0;
    array->capacity = initialCapacity;
    pthread_mutex_init(&array->lock, NULL);
    return 0;
}

int packet_array_add(PacketArray* array, DataPacket* packet) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        DataPacket** newArray = realloc(array->packets, sizeof(DataPacket*) * newCapacity);

        if (newArray == NULL) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }

        array->capacity = newCapacity;
        array->packets = newArray;
    }

    array->packets[array->count++] = packet;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

void packet_array_clear(PacketArray* array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->packets[i]->payload);
        free(array->packets[i]);
    }

    array->count = 0;
    pthread_mutex_unlock(&array->lock);
}
```
This code uses a simple dynamic array with a mutex for thread safety. When adding a packet, it checks if there is enough space in the array and doubles its size if necessary. It also handles memory allocation failures by returning -1 when malloc or realloc fail. The clear function frees all packets and resets the count to 0.
