#include <sys/socket.h>
#include <netinet/in.h>

typedef struct {
    int socket;
    pthread_t thread;
} WorkerThread;

void* worker(void *arg) {
    // This is where you would handle the client connection and manage the connection pool
    return NULL;
}

int configureAndInitializeNetworkService(unsigned short port, float maxLoadFactor) {
    int serverSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (serverSocket < 0) {
        perror("Failed to create server socket");
        return -1;
    }

    struct sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(port);
    serverAddress.sin_addr.s_addr = INADDR_ANY;

    if (bind(serverSocket, (struct sockaddr *) &serverAddress, sizeof(serverAddress)) < 0) {
        perror("Failed to bind server socket");
        return -1;
    }

    listen(serverSocket, 5);

    int cpuCount = sysconf(_SC_NPROCESSORS_ONLN);
    int threadCount = maxLoadFactor * cpuCount;
    WorkerThread* threads = malloc(threadCount * sizeof(WorkerThread));

    for (int i = 0; i < threadCount; ++i) {
        threads[i].socket = accept(serverSocket, NULL, NULL);
        if (pthread_create(&threads[i].thread, NULL, worker, &threads[i].socket) != 0) {
            perror("Failed to create thread");
            return -1;
        }
    }

    // This is where you would handle shutdown and cleanup

    free(threads);
    close(serverSocket);

    return 0;
}
```
This code creates a server socket, binds it to the specified port, listens for incoming connections, and then spawns a worker thread for each connection. The number of threads is determined by multiplying the maximum load factor by the number of CPU cores. This is a very basic example and does not include many features you requested such as connection pooling or logging.
