    int key;
    double metric_value;
    struct Record *next;
} Record;

Record* hashTable[100]; // Assuming a size of 100 for the hash table
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int generateKey() {
    static int key = 0;
    return ++key;
}

Record* createRecord(long offset, double metric_value) {
    Record *record = malloc(sizeof(Record));
    if (record == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }

    record->offset = offset;
    record->key = generateKey();
    record->metric_value = metric_value;
    record->next = NULL;

    return record;
}

void insertRecord(long offset, double metric_value) {
    Record *record = createRecord(offset, metric_value);

    pthread_mutex_lock(&lock);
    int index = abs(record->key % 100); // Hash function
    record->next = hashTable[index];
    hashTable[index] = record;
    pthread_mutex_unlock(&lock);
}

void deleteRecord(int key) {
    int index = abs(key % 100); // Hash function

    pthread_mutex_lock(&lock);
    Record *prev = NULL, *curr = hashTable[index];
    while (curr != NULL && curr->key != key) {
        prev = curr;
        curr = curr->next;
    }

    if (curr == NULL) {
        printf("Record not found\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    if (prev != NULL)
        prev->next = curr->next;
    else
        hashTable[index] = curr->next;

    free(curr);
    pthread_mutex_unlock(&lock);
}
```
