void addNode(char* ip, int port) {
    NetworkNode *newNode = malloc(sizeof(NetworkNode));
    if (newNode == NULL) {
        ++allocationFailures;
        return;
    }

    newNode->ip_address = ip;
    newNode->port = port;
    newNode->status = 1; // Assume all nodes are available initially.
    newNode->next = NULL;

    pthread_t thread;
    if (pthread_create(&thread, NULL, checkConnectivity, newNode) != 0) {
        ++allocationFailures;
        free(newNode);
        return;
    }

    pthread_mutex_lock(&lock);
    if (head == NULL) {
        head = newNode;
    } else {
        NetworkNode *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    ++allocatedNodes;
    pthread_mutex_unlock(&lock);
}
