typedef struct item {
    char* key;
    void* buffer;
    size_t bufferSize;
} Item;

Item* createItem(const char* key, const void* content, size_t contentSize) {
    Item* newItem = malloc(sizeof(Item));
    if (newItem == NULL) return NULL;

    newItem->key = strdup(key);
    if (newItem->key == NULL) {
