#include <algorithm>
#include <forward_list>
#include <string>
#include <mutex>
#include <random>

std::mutex mtx;  // mutex for thread safety

void insertAfterFirstOccurrence(std::forward_list<std::string>& flist, const std::string& targetString, const std::string& insertString) {
    std::lock_guard<std::mutex> lock(mtx);  // acquire the mutex
    auto it = std::find(flist.begin(), flist.end(), targetString);
    if (it != flist.end()) {
        flist.insert_after(it, insertString);
    } else {
        flist.push_front(insertString);
    }
}

