    std::lock_guard<std::mutex> lock(memMtx);  // acquire the mutex
    if (allocatedMem + sizeof(NFAPI_CRC_INDICATION_PDU_T) * numStructs > MAX_MEM_SIZE) {
        throw std::runtime_error("Insufficient system resources");
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = new (std::nothrow) NFAPI_CRC_INDICATION_PDU_T[numStructs];
