#include <stdlib.h>
#include <pthread.h>

typedef struct MACEntityContext {
    int id;
    void* parameters;
    char* buffer;
    size_t bufferSize;
    struct MACEntityContext *prev, *next;
} MACEntityContext;

MACEntityContext* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addToList(MACEntityContext* node) {
    pthread_mutex_lock(&lock);
    if (head == NULL) {
        head = node;
        node->prev = node->next = node;
    } else {
        node->next = head;
        node->prev = head->prev;
        head->prev->next = node;
        head->prev = node;
    }
    pthread_mutex_unlock(&lock);
}

void removeFromList(MACEntityContext* node) {
    pthread_mutex_lock(&lock);
    if (node->next == node) {
        head = NULL;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
        if (head == node) head = node->next;
    }
    pthread_mutex_unlock(&lock);
}

MACEntityContext* createMACEntity(int id, void* parameters, size_t bufferSize) {
    MACEntityContext* entity = malloc(sizeof(MACEntityContext));
    if (entity == NULL) return NULL; // Handle allocation failure

    entity->id = id;
    entity->parameters = parameters;
    entity->bufferSize = bufferSize;
    entity->buffer = malloc(bufferSize);
    if (entity->buffer == NULL) {
        free(entity); // Handle allocation failure
        return NULL;
    }

    addToList(entity);
    return entity;
}

void destroyMACEntity(MACEntityContext* entity) {
    removeFromList(entity);
    free(entity->buffer);
    free(entity);
}
```
