SensorDataRecord* allocateAndInitialize(const char* jsonFilePath, size_t recordCount, int seed, bool detailedLogging) {
    // Allocate memory for the array of records
    SensorDataRecord* records = malloc(sizeof(SensorDataRecord) * recordCount);
    if (records == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    // Initialize random number generator
    pcg32_random_t rng;
    pcg32_srandom_r(&rng, seed, 0);

    // Parse JSON file for statistical model data
    json_error_t error;
    json_t* root = json_load_file(jsonFilePath, 0, &error);

    if(!root) {
        free(records);
        return NULL;
    }

    // Generate random values for each record based on the statistical model
    for (size_t i = 0; i < recordCount; ++i) {
        records[i].temperature = json_real(json_object_get(root, "temperature"));
        records[i].index = json_integer(json_object_get(root, "index"));

        // Generate a random value from the statistical model
        double min = json_real(json_object_get(root, "minHumidity"));
        double max = json_real(json_object_get(root, "maxHumidity"));
        records[i].humidity = pcg32_boundedrand_r(&rng, (max - min)) + min;
    }

    // Clean up JSON data and return the array of records
    json_decref(root);
    return records;
}
