['Here is a basic implementation of your task in C++ using Boost library for filesystem operations, OpenSSL for MD5 hash calculation, and spdlog for logging. This code does not handle concurrent file access or deadlocks as it's quite complex and depends on the specific use case. Also, it doesn't resume from last processed file due to lack of persistent storage mechanism.

```cpp
#include <iostream>
#include <fstream>
#include <forward_list>
#include <boost/filesystem.hpp>
#include <openssl/md5.h>
#include "spdlog/spdlog.h"

namespace fs = boost::filesystem;

std::string calculateMD5(const std::string& filename) {
    std::ifstream file(filename, std::ios::binary);
    MD5_CTX md5Context;
    MD5_Init(&md5Context);

    char buf[1024 * 1024]; // read in chunks of 1MB
    while (file.good()) {
        file.read(buf, sizeof(buf));
        MD5_Update(&md5Context, buf, file.gcount());
    }

    unsigned char result[MD5_DIGEST_LENGTH];
    MD5_Final(result, &md5Context);

    std::ostringstream sout;
    sout << std::hex << std::setfill('0');
    for (long long c : result) {
        sout << std::setw(2) << (c & 0xff);
    }

    return sout.str();
}

void processFilesInDirectory(fs::path dirPath, std::forward_list<std::string>& list, const std::string& targetString) {
    if (!fs::exists(dirPath)) return;

    fs::directory_iterator endIter;
    for (fs::directory_iterator file(dirPath); file != endIter; ++file) {
        try {
            if (fs::is_directory(file->status())) {
                processFilesInDirectory(file->path(), list, targetString);
            } else if (!fs::is_regular_file(file->status()) || fs::is_empty(file->path()) || 
                       fs::file_size(file->path()) > 100 * 1024 * 1024) { // ignore hidden files, directories and large files
                continue;
            } else if (file->path().extension() != ".txt" && file->path().extension() != ".log") { // process specific extensions only
                spdlog::info("Processing {}", file->path().string());

                std::string md5Hash = calculateMD5(file->path().string());
                bool targetFound = false;
                for (auto it = list.begin(); it != list.end(); ++it) {
                    if (*it == targetString) {
                        spdlog::info("Target string found, inserting MD5 hash after");
                        list.insert_after(it, md5Hash);
                        targetFound = true;
                        break;
                    }
                }

                if (!targetFound) {
                    spdlog::info("Target string not found, appending MD5 hash to the end of the list");
                    list.insert_after(list.before_begin(), md5Hash);
                }
            }
        } catch (const std::exception &ex) {
            spdlog::error("{}", ex.what());
        }
    }
}
```
This code is a basic implementation and may need to be adjusted according to your specific requirements, such as logging configuration or file extension handling. Also, it doesn't handle interruptions during processing and resumes from the last processed file. It also doesn't manage file handles efficiently to avoid resource leaks. You might want to use RAII (Resource Acquisition Is Initialization) idiom for managing resources in C++.
']

