        if (packet->payload == NULL) {
            fprintf(stderr, "Failed to generate the payload for a data packet\n");
            free(packet);
            break; // Clean up previously allocated packets
        }

        time(&packet->timestamp);
        array[i] = packet;
    }

    if (i < size) {
        fprintf(stderr, "Cleaning up after a failure\n");
        for (; i >= 0; --i) {
            free(array[i]->payload);
            free(array[i]);
        }

        free(array);
        return NULL;
    } else {
        fprintf(stdout, "Successfully allocated %lu packets\n", size);
        return array;
    }
}
