['Here is an example of how you might implement this task using C and POSIX threads (pthreads). This code does not include all the optimizations mentioned in your question due to their complexity and size, but it should give a good starting point for understanding how to manage dynamic collections in a multi-threaded environment.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
    time_t timestamp;
} Record;

typedef struct Collection {
    pthread_mutex_t lock;
    Record* records;
    size_t capacity;
    size_t count;
} Collection;

void init(Collection* collection, size_t initialCapacity) {
    if (pthread_mutex_init(&collection->lock, NULL) != 0) {
        printf("Failed to initialize mutex\n");
        exit(1);
    }

    collection->records = malloc(initialCapacity * sizeof(Record));
    if (collection->records == NULL) {
        printf("Memory allocation failed\n");
        exit(2);
    }

    collection->capacity = initialCapacity;
    collection->count = 0;
}

void add(Collection* collection, Record record) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        Record* newRecords = realloc(collection->records, newCapacity * sizeof(Record));

        if (newRecords == NULL) {
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&collection->lock);
            return;
        }

        collection->records = newRecords;
        collection->capacity = newCapacity;
    }

    collection->records[collection->count++] = record;

    pthread_mutex_unlock(&collection->lock);
}

void update(Collection* collection, int key, Record record) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            collection->records[i] = record;
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

void remove(Collection* collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            collection->records[i] = collection->records[--collection->count];
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

void cleanup(Collection* collection) {
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
}
```
This code uses a simple array to store the records. It starts with an initial capacity and doubles it whenever more space is needed. The `add`, `update`, and `remove` functions are protected by a mutex for thread safety. 

Please note that this is a simplified example and does not include all the optimizations mentioned in your question. For instance, it uses a single global lock for synchronization which might lead to contention issues if many threads try to modify the collection at the same time. A more efficient approach would be to use fine-grained locks or other concurrency control mechanisms.
']

