void* loadResourceBundle(const char* filename, size_t* numItems) {
    FILE* file = fopen(filename, "rb"); // open in binary mode for non-blocking I/O
    if (file == NULL) {
        perror("Failed to open resource bundle");
        return NULL;
    }

    fseek(file, 0L, SEEK_END);
    size_t fileSize = ftell(file);
    rewind(file);

    void* bundle = malloc(fileSize);
    if (bundle == NULL) {
        perror("Failed to allocate memory for resource bundle");
        fclose(file);
        return NULL;
    }

    size_t itemsRead = fread(bundle, 1, fileSize, file);
    if (itemsRead != fileSize) {
        perror("Error reading resource bundle");
        free(bundle);
        fclose(file);
        return NULL;
    }

    *numItems = itemsRead / sizeof(NFAPI_CRC_INDICATION_PDU_T); // adjust as needed
    fclose(file);
    return bundle;
}

DataPacket* initializePackets(size_t numPackets, void** payloads) {
    DataPacket* packets = calloc(numPackets, sizeof(DataPacket));
    if (packets == NULL) {
        perror("Failed to allocate memory for data packets");
        return NULL;
    }

    srand(time(NULL)); // seed the random number generator
