            pdu->RNTI = rand(); // ensure no two consecutive structures share the same RNTI
        }
    }

    return packets;
}

void* initializeData(const char* filename, size_t numPackets) {
    void* bundle;
    size_t numItems;
    pthread_mutex_lock(&lock); // lock to prevent concurrent access
    bundle = loadResourceBundle(filename, &numItems);
    pthread_mutex_unlock(&lock);

    if (bundle == NULL) {
        return NULL;
    }

    DataPacket* packets = initializePackets(numPackets, (void**)bundle);
    // handle partial failures here...

