typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int size = 0;

void add(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);

    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = head;
    head = newNode;
    size++;

    if(size > 1024) {
        Node* temp = head;
        for(int i = 0; i < size - 2; i++) {
            temp = temp->next;
        }

        free(temp->next);
        temp->next = NULL;
        size--;
    }

    pthread_mutex_unlock(&lock);
}

void update(int RNTI, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    while(temp != NULL) {
        if(temp->data.RNTI == RNTI) {
            temp->data = data;
            break;
        }

        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);
}

void remove(int RNTI) {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    Node* prev = NULL;
    while(temp != NULL) {
        if(temp->data.RNTI == RNTI) {
            if(prev == NULL) {
                head = temp->next;
            } else {
                prev->next = temp->next;
            }

            free(temp);
            size--;
            break;
        }

        prev = temp;
        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);
}
```
This code uses a linked list to store the data. It also uses a mutex for thread safety. When adding an element, it checks if the size limit is reached and removes the oldest entry if necessary. The update and remove functions work similarly by iterating through the list until they find the correct node. 

