void init() {
    records = g_array_new(FALSE, FALSE, sizeof(Record));
    pthread_mutex_init(&lock, NULL);
    logFile = fopen("log.txt", "w");
}

void insertAtPosition(int position, Record record) {
    pthread_mutex_lock(&lock);

    if (position > records->len) {
        g_array_set_size(records, position + 1);
    }

    g_array_index(records, Record, position) = record;

    fprintf(logFile, "Inserted at position %d\n", position);

    pthread_mutex_unlock(&lock);
}

void deleteAtPosition(int position) {
    pthread_mutex_lock(&lock);

    if (position < records->len) {
        g_array_remove_index_fast(records, position);

        fprintf(logFile, "Deleted from position %d\n", position);
    }

    pthread_mutex_unlock(&lock);
}

