['Here is a basic implementation of your request using C11 threads, POSIX mutexes, and a linked list structure. This code does not include all the details you requested (like logging or integration with an existing network simulation framework), but it should give you a good starting point. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG* CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;
int successfulAllocations = 0, failedAllocations = 0;
double totalAllocationTime = 0.0;

NFAPI_CRC_INDICATION_PDU_T createData() {
    NFAPI_CRC_INDICATION_PDU_T data;
    data.RX_UE_INFORMATION_TAG = rand(); // replace with actual value
    data.RNTI = rand(); // replace with actual value
    CRC_INDICATION_REL8_TAG* tag = malloc(sizeof(CRC_INDICATION_REL8_TAG));
    if (tag == NULL) {
        failedAllocations++;
        return data;
    }
    tag->CRCFLAG = rand(); // replace with actual value
    data.CRC_INDICATION_REL8_TAG = tag;
    successfulAllocations++;
    return data;
}

void* createNode(void* arg) {
    clock_t start, end;
    double cpu_time_used;

    start = clock();
    pthread_mutex_lock(&lock);
    Node* node = malloc(sizeof(Node));
    if (node == NULL) {
        failedAllocations++;
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    node->data = createData();
    node->next = head;
    head = node;
    end = clock();

    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    totalAllocationTime += cpu_time_used;

    pthread_mutex_unlock(&lock);
    return NULL;
}
```
This code creates a linked list of `NFAPI_CRC_INDICATION_PDU_T` structures. Each node is created in its own thread, and the mutex lock ensures that only one thread can modify the shared data at any given time to prevent data corruption. The statistics for successful and failed allocations are also tracked.
']

