    size_t currentSize;
    long* offsets;
    pthread_mutex_t mutex;
} OffsetArray;

typedef struct {
    size_t maxSize;
    size_t currentSize;
    int* keys;
    Record** records;
    pthread_mutex_t mutex;
} KeyRecordArray;

OffsetArray offsetArray;
KeyRecordArray keyRecordArray;
size_t memoryLimit = 1024 * 1024 * 500; // 500MB limit

void initArrays(long initialSize) {
    offsetArray.maxSize = initialSize;
    offsetArray.currentSize = 0;
    pthread_mutex_init(&offsetArray.mutex, NULL);

    keyRecordArray.maxSize = initialSize;
    keyRecordArray.currentSize = 0;
    pthread_mutex_init(&keyRecordArray.mutex, NULL);
}

void addOffset(long offset) {
    pthread_mutex_lock(&offsetArray.mutex);

    if (offsetArray.currentSize >= memoryLimit) {
        // Handle memory limit exceeded error here
        return;
    }

    if (offsetArray.currentSize == offsetArray.maxSize) {
        size_t newMaxSize = offsetArray.maxSize * 2;

        long* newOffsets = realloc(offsetArray.offsets, sizeof(long) * newMaxSize);
        if (!newOffsets) {
            // Handle memory allocation error here
            return;
        }

        offsetArray.maxSize = newMaxSize;
        offsetArray.offsets = newOffsets;
    }

    offsetArray.offsets[offsetArray.currentSize++] = offset;

    pthread_mutex_unlock(&offsetArray.mutex);
}

void addKeyRecord(int key, Record* record) {
    pthread_mutex_lock(&keyRecordArray.mutex);

    if (keyRecordArray.currentSize >= memoryLimit) {
        // Handle memory limit exceeded error here
        return;
    }

    if (keyRecordArray.currentSize == keyRecordArray.maxSize) {
        size_t newMaxSize = keyRecordArray.maxSize * 2;

        int* newKeys = realloc(keyRecordArray.keys, sizeof(int) * newMaxSize);
        Record** newRecords = realloc(keyRecordArray.records, sizeof(Record*) * newMaxSize);

        if (!newKeys || !newRecords) {
            // Handle memory allocation error here
            return;
        }

        keyRecordArray.maxSize = newMaxSize;
        keyRecordArray.keys = newKeys;
        keyRecordArray.records = newRecords;
    }

    keyRecordArray.keys[keyRecordArray.currentSize] = key;
    keyRecordArray.records[keyRecordArray.currentSize++] = record;

    pthread_mutex_unlock(&keyRecordArray.mutex);
}
```
This code initializes two arrays, one for 'long' offset values and another for 'int' keys with associated records. It uses a mutex to ensure thread safety when adding elements to the arrays. The memory limit is checked before each addition operation to prevent exceeding it. If the maximum size of an array is reached, its size is doubled using realloc.

Please note that this code does not include all the features you requested (like dynamic resizing or memory management under varying workloads), but it should give you a good starting point. You would need to add more error checking and handle edge cases as per your requirements. Also, please remember to free any allocated memory when you're done with it to avoid memory leaks.
