['Here is an example of how you might implement this task using C with a focus on memory efficiency and performance. This solution assumes that the CSV file contains one floating-point number per line, and the configuration file specifies a maximum size for each `char` array. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct {
    double number;
    char* str_array;
} MyStruct;

// Global mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

MyStruct* read_csv(const char* csv_file, const char* config_file) {
    FILE *fp1, *fp2;
    MyStruct *data;
    double number;
    int max_size, count = 0;

    // Open files
    fp1 = fopen(csv_file, "r");
    if (fp1 == NULL) {
        perror("Error opening CSV file");
        return NULL;
    }
    fp2 = fopen(config_file, "r");
    if (fp2 == NULL) {
        perror("Error opening config file");
        return NULL;
    }

    // Read maximum size from configuration file
    if (fscanf(fp2, "%d", &max_size) != 1) {
        perror("Invalid data in config file");
        return NULL;
    }

    // Allocate memory for struct array
    data = malloc(sizeof(MyStruct));
    if (data == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Read CSV file line by line and fill the struct array
    while (fscanf(fp1, "%lf", &number) == 1) {
        pthread_mutex_lock(&lock);  // Lock for thread safety

        data = realloc(data, sizeof(MyStruct) * (count + 1));
        if (data == NULL) {
            perror("Memory allocation failed");
            return NULL;
        }

        data[count].number = number;
        data[count].str_array = malloc(max_size);
        if (data[count].str_array == NULL) {
            perror("Memory allocation failed");
            return NULL;
        }

        // Fill the char array with a specified string repeated max_size times
        memset(data[count].str_array, 'a', max_size);
        data[count].str_array[max_size - 1] = '\0';  // Null-terminate the char array

        count++;

        pthread_mutex_unlock(&lock);  // Unlock for thread safety
    }

    // Close files
    fclose(fp2);
    fclose(fp1);

    return data;
}

void free_memory(MyStruct* data, int count) {
    for (int i = 0; i < count; i++) {
        free(data[i].str_array);  // Free each char array
    }
    free(data);  // Free the struct array
}
```
This code uses `malloc` and `realloc` to allocate memory for the struct array and each `char` array, respectively. It also uses a mutex lock to ensure thread safety when reading from the CSV file and filling the struct array. The function `free_memory` is used to free all allocated memory at the end of the program.

