DataPacket** allocateMemory(size_t numOfPackets, size_t maxSize) {
    DataPacket** packets = malloc(numOfPackets * sizeof(DataPacket*));
    if (packets == NULL) {
        printf("Failed to allocate memory for packets\n");
        return NULL;
    }

    size_t totalSize = 0;
    for (size_t i = 0; i < numOfPackets; ++i) {
        // Assume each payload requires 1 byte of memory. In a real scenario, you would need to know the exact size of each payload.
        size_t packetSize = sizeof(DataPacket);

        if (totalSize + packetSize > maxSize) {
            printf("Reached maximum size limit\n");
            free(packets);
            return NULL;
        }

        packets[i] = malloc(packetSize);
        if (packets[i] == NULL) {
            printf("Failed to allocate memory for packet %zu\n", i + 1);
            // Free previously allocated packets.
            for (size_t j = 0; j < i; ++j) {
                free(packets[j]);
            }
            free(packets);
            return NULL;
        }

        totalSize += packetSize;
    }

    printf("Successfully allocated %zu packets\n", numOfPackets);
    return packets;
}
```
