    json_t *root = json_loads(json, 0, &error);

    if(!root) {
        logError("Failed to parse JSON: %s", error.text);
        return;
    }

    UserAccount account;
    strncpy(account.id, json_string_value(json_object_get(root, "id")), sizeof(account.id) - 1);
    strncpy(account.name, json_string_value(json_object_get(root, "name")), sizeof(account.name) - 1);
    strncpy(account.email, json_string_value(json_object_get(root, "email")), sizeof(account.email) - 1);
    strncpy(account.password, json_string_value(json_object_get(root, "password")), sizeof(account.password) - 1);
    strncpy(account.hostname, json_string_value(json_object_get(root, "hostname")), sizeof(account.hostname) - 1);
    strncpy(account.sub_action, json_string_value(json_object_get(root, "sub_action")), sizeof(account.sub_action) - 1);

    pthread_mutex_lock(&lock);
    if(strcmp(account.id, "") != 0) {
        // Update or create user account
        HASH_ADD_STR(hh, id, account);
    } else if(strcmp(account.sub_action, "delete") == 0) {
        // Delete user account
        UserAccount *user;
        HASH_FIND_STR(hh, account.id, user);
        if(user) {
            HASH_DEL(hh, user);
            free(user);
        }
    } else {
        logError("Invalid request");
    }
    pthread_mutex_unlock(&lock);

    json_decref(root);
}
