["Here is a basic implementation in C using pthreads for threading and a simple hash table with linked list for collision handling. This code does not include all the mentioned constraints and trade-offs, but it should give you a good starting point. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <assert.h>

typedef struct Record {
    int key;
    long offset;
    time_t timestamp;
    long value;
    struct Record *next;
} Record;

Record* records[1000000]; // Assuming a hash table size of 1 million.
pthread_mutex_t locks[1000000];

void init() {
    srand(time(NULL));
    for (int i = 0; i < 1000000; ++i) {
        pthread_mutex_init(&locks[i], NULL);
    }
}

long generateRandomLong() {
    return rand();
}

void addRecord(int key, long value) {
    int index = abs(key % 1000000); // Simple hash function.

    pthread_mutex_lock(&locks[index]);

    Record *record = malloc(sizeof(Record));
    assert(record != NULL);

    record->key = key;
    record->value = value;
    record->timestamp = time(NULL);
    record->offset = generateRandomLong();
    record->next = records[index];
    records[index] = record;

    pthread_mutex_unlock(&locks[index]);
}

void updateRecord(int key, long value) {
    int index = abs(key % 1000000);

    pthread_mutex_lock(&locks[index]);

    Record *record;
    for (record = records[index]; record != NULL; record = record->next) {
        if (record->key == key) {
            record->value = value;
            break;
        }
    }

    pthread_mutex_unlock(&locks[index]);
}

void removeRecord(int key) {
    int index = abs(key % 1000000);

    pthread_mutex_lock(&locks[index]);

    Record *record, *prev;
    for (record = records[index], prev = NULL; record != NULL; prev = record, record = record->next) {
        if (record->key == key) {
            if (prev != NULL) {
                prev->next = record->next;
            } else {
                records[index] = record->next;
            }

            free(record);
            break;
        }
    }

    pthread_mutex_unlock(&locks[index]);
}
```
This code does not include logging, error handling or cleanup. It also doesn't handle memory allocation failures and it uses a simple hash function which may lead to collisions. For a production-grade system you would need to add these features and improve the hash function. 

