function renderFooterScripts(scripts) {
    let html = '';

    if (ENVIRONMENT === 'production') {
        scripts = scripts.filter((script) => {
            return script.key === "PRODUCTION" && INCLUDE_PRODUCTION_SCRIPTS;
        });
    } else {
        scripts = scripts.filter((script) => {
            let priority = parseInt(script.priority);
            return !isNaN(priority) && priority > 100;
        });
    }

    for (let script of scripts) {
        if (!script || !script.key || !script.code) continue;

        html += `<script key="${script.key}">${script.code}</script>\n`;
    }

    return html;
}
