    for (int i = 0; i < num; i++) {
        doubles[i] = i * 1.5;

        strings[i] = malloc(20);
        if (strings[i] == NULL) {
            // Free previously allocated memory and return error code
            for (int j = 0; j < i; j++) free(strings[j]);
            free(doubles);
            free(structs);
            return -1;
        }

        sprintf(strings[i], "%d", i);
    }

    // Initialize the struct array
    for (int i = 0; i < num; i++) {
        structs[i].d = doubles[i];
        structs[i].i = i;
        structs[i].str = strings[i];
    }

    // Free the individual arrays and assign the final array to the output parameter
    free(doubles);
    *elements = structs;

    return 0;
}
