#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

int init_components(long **offsets, int **keys, Record ***records, 
                    size_t offsetSize, size_t keySize, size_t recordSize, 
                    int minVal, int maxVal) {

    if (offsetSize < 0 || keySize < 0 || recordSize < 0 || 
        minVal > maxVal || !offsets || !keys || !records) {
        return -1; // Invalid input
    }

    *offsets = calloc(offsetSize, sizeof(long));
    if (!*offsets) return -2; // Memory allocation failed

    *keys = calloc(keySize, sizeof(int));
    if (!*keys) {
        free(*offsets);
        return -2; // Memory allocation failed
    }

    *records = malloc(recordSize * sizeof(Record*));
    if (!*records) {
        free(*offsets);
        free(*keys);
        return -2; // Memory allocation failed
    }

    srand(time(NULL));
    for (size_t i = 0; i < recordSize; ++i) {
        (*records)[i] = malloc(sizeof(Record));
        if (!(*records)[i]) {
            // Memory allocation failed, clean up and return error
            for (size_t j = 0; j < i; ++j) free((*records)[j]);
            free(*offsets);
            free(*keys);
            free(*records);
            *records = NULL;
            return -2; // Memory allocation failed
        }

        (*records)[i]->value = rand() % (maxVal - minVal + 1) + minVal;
    }

    return 0; // Success
}

void deinit_components(long **offsets, int **keys, Record ***records, size_t recordSize) {
    if (*offsets) free(*offsets);
    if (*keys) free(*keys);
    if (*records) {
        for (size_t i = 0; i < recordSize; ++i) 
            if ((*records)[i]) free((*records)[i]);
        free(*records);
    }
}
