#include <ctime>
#include <random>

struct Entry {
    std::string key;
    time_t timestamp;
    double value;
};

class GameCharacter {
private:
    std::vector<Entry*> entries;
    size_t capacityThreshold;
    bool canAttack = true;
    time_t lastAttackTime = 0;
    const int cooldownPeriod = 9; // 9 seconds
public:
    GameCharacter(size_t threshold) : capacityThreshold(threshold) {}
    ~GameCharacter() {
        for (auto entry : entries) {
            delete entry;
        }
    }

    void addEntry(const std::string& key, double value) {
        if (entries.size() >= capacityThreshold) {
            // Dynamically resize the collection
            entries.reserve(entries.capacity() * 2);
        }
        Entry* newEntry = new Entry{key, std::time(nullptr), value};
        entries.push_back(newEntry);
    }

    void printEntries() {
        for (const auto& entry : entries) {
            std::cout << "Key: " << entry->key 
                      << ", Timestamp: " << entry->timestamp 
                      << ", Value: " << entry->value << "\n";
        }
    }

    void attack() {
        if (!canAttack) return;

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 1); // 50% chance for each attack

        int attackType = dis(gen);
        if (attackType == 0) {
            std::cout << "Attacking with type A\n";
        } else {
            std::cout << "Attacking with type B\n";
        }

        canAttack = false;
        lastAttackTime = std::time(nullptr);
    }

    void update() {
        if (!canAttack && (std::time(nullptr) - lastAttackTime >= cooldownPeriod)) {
            canAttack = true;
        }
    }
};
```
