typedef struct DataPacket {
    int payload;
    time_t timestamp;
    unsigned long id;
    struct DataPacket *next;
} DataPacket;

DataPacket* createPacket(int payload, unsigned long id) {
    DataPacket *packet = malloc(sizeof(DataPacket));
    if (packet == NULL) {
        printf("Failed to allocate memory for packet.\n");
        return NULL;
    }

    packet->payload = payload;
    packet->timestamp = time(NULL);
    packet->id = id;
    packet->next = NULL;

    return packet;
}

void addPacket(DataPacket **head, int payload, unsigned long id) {
    DataPacket *new_packet = createPacket(payload, id);
    if (new_packet == NULL) {
        printf("Failed to add packet.\n");
        return;
    }

    new_packet->next = *head;
    *head = new_packet;
}

DataPacket* getPacket(DataPacket *head, unsigned long id) {
    DataPacket *current = head;
    while (current != NULL) {
        if (current->id == id) {
            return current;
        }
        current = current->next;
    }

    printf("No packet with ID %lu found.\n", id);
    return NULL;
}

void freePackets(DataPacket *head) {
    DataPacket *current;
    while (head != NULL) {
        current = head;
        head = head->next;
        free(current);
    }
}
