['Here is a basic implementation in C using pthreads for thread safety and Open Addressing with Linear Probing for collision handling. This is a simplified version of what you might need to implement in a real-world scenario. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdio.h>

typedef struct KeyValue {
    char* key;
    void* value;
} KeyValue;

typedef struct HashTable {
    int size;
    int count;
    float loadFactor;
    KeyValue** table;
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable(int initialSize) {
    HashTable* ht = malloc(sizeof(HashTable));
    ht->size = initialSize;
    ht->count = 0;
    ht->loadFactor = 0.75f;
    ht->table = calloc(initialSize, sizeof(KeyValue*));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

unsigned long hashCode(char* key) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash;
}

void resize(HashTable* ht, int newSize) {
    KeyValue** oldTable = ht->table;
    int oldSize = ht->size;

    ht->count = 0;
    ht->size = newSize;
    ht->table = calloc(newSize, sizeof(KeyValue*));

    for (int i = 0; i < oldSize; ++i) {
        KeyValue* kv = oldTable[i];
        if (kv != NULL) {
            insert(ht, kv->key, kv->value);
            free(kv);
        }
    }

    free(oldTable);
}

void insert(HashTable* ht, char* key, void* value) {
    pthread_mutex_lock(&ht->lock);

    if ((float)ht->count / ht->size > ht->loadFactor) {
        resize(ht, ht->size * 2);
    }

    KeyValue* kv = malloc(sizeof(KeyValue));
    kv->key = key;
    kv->value = value;

    unsigned long hash = hashCode(key) % ht->size;
    while (ht->table[hash] != NULL && strcmp(ht->table[hash]->key, key) != 0) {
        hash = (hash + 1) % ht->size;
    }

    if (ht->table[hash] == NULL) {
        ++ht->count;
    } else {
        free(ht->table[hash]->value);
    }

    ht->table[hash] = kv;

    pthread_mutex_unlock(&ht->lock);
}
```
This code does not include the logging functionality or customization of resizing thresholds and collision handling strategies. You would need to add these features yourself based on your specific requirements. Also, this is a basic implementation and may not cover all edge cases or performance optimizations that might be necessary for a real-world application.
