int isNumeric(const char* str) {
    while(*str != '\0') {
        if(!isdigit(*str))
            return 0;
        str++;
    }
    return 1;
}

void processLine(char *line, size_t len) {
    char* token = strtok(line, ";");
    int count = 0;
    double weights[] = {0.3, 0.4, 0.3};
    double sum = 0;
    while (token != NULL && count < 3) {
        if (!isNumeric(token)) {
            fprintf(stderr, "Non-numeric value found: %s\n", token);
            return;
        }
        int num = atoi(token);
        sum += weights[count] * num;
        count++;
        token = strtok(NULL, ";");
    }
    if (count == 3) {
        printf("Weighted average: %f\n", sum);
    } else {
        fprintf(stderr, "Less than 3 numeric values found in line.\n");
    }
}

