function renderFooterScripts(scriptObjects) {
    let renderedHTML = '';
    const maxScripts = 15;
    let scriptCount = 0;

    if (scriptObjects.length > maxScripts) {
        console.error('Too many scripts to render, capping at 15');
        scriptObjects = scriptObjects.slice(0, maxScripts);
    }

    for (let script of scriptObjects) {
        if (!script.id || !script.version || !script.activationCriteria) {
            console.error('Invalid script object: ', script);
            continue;
        }

        const userRoles = script.activationCriteria.userRoles || [];
        const envVariables = script.activationCriteria.envVariables || {};

        if (scriptCount >= maxScripts) {
            console.error('Maximum number of scripts reached, skipping remaining');
            break;
        }

        // Conditional rendering based on user roles and environmental variables
        if (userRoles.length > 0 || Object.keys(envVariables).length > 0) {
            const currentUserRole = 'default'; // Replace with actual logic to get the current user role
            const currentEnvVariable = 'default'; // Replace with actual logic to get the current environmental variable

            if (userRoles.includes(currentUserRole) && envVariables[currentEnvVariable]) {
                renderedHTML += `<script id="${script.id}" version="${script.version}">${script.content}</script>`;
                scriptCount++;
            } else {
                console.log(`Skipping script ${script.id}, activation criteria not met`);
            }
        } else {
            renderedHTML += `<script id="${script.id}" version="${script.version}">${script.content}</script>`;
            scriptCount++;
        }
    }

    return renderedHTML;
}
