['Here is a basic implementation of the problem in Java. This code uses Apache Commons library to generate MD5 hash and Guava library for caching. 

```java
import org.apache.commons.codec.digest.DigestUtils;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import java.util.concurrent.TimeUnit;
import java.util.logging.*;

public class MessageProcessor {
    private static final Logger logger = Logger.getLogger(MessageProcessor.class.getName());

    // Cache to store previously computed hashes
    LoadingCache<String, String> cache;

    public MessageProcessor() {
        this.cache = CacheBuilder.newBuilder()
                .maximumSize(10_000)  // Adjust according to your needs
                .expireAfterWrite(24, TimeUnit.HOURS)  // Adjust according to your needs
                .build(new CacheLoader<String, String>() {
                    @Override
                    public String load(String input) throws Exception {
                        return computeHash(input);
                    }
                });
    }

    /**
     * Processes the input string and returns its MD5 hash.
     */
    public String processMessage(String input) {
        // Check if the result is in cache
        if (cache.getIfPresent(input) != null) {
            logger.info("Cache hit for input: " + input);
            return cache.getIfPresent(input);
        } else {
            String hash = computeHash(input);
            // Add to cache
            cache.put(input, hash);
            logger.info("Computed and cached hash for input: " + input);
            return hash;
        }
    }

    /**
     * Computes the MD5 hash of a sanitized string.
     */
    private String computeHash(String input) {
        // Sanitize the input by removing non-alphanumeric characters
        String sanitizedInput = input.replaceAll("[^A-Za-z0-9]", "");

        logger.info("Sanitized input: " + sanitizedInput);

        // Compute and return the MD5 hash
        return DigestUtils.md5Hex(sanitizedInput);
    }
}
```
