#include <pthread.h>
#include <stdlib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* head;
    int maxInstances;
    int currentInstances;
} InstanceManager;

InstanceManager manager = { PTHREAD_MUTEX_INITIALIZER, NULL, 0, 0 };

NFAPI_CRC_INDICATION_PDU_T* getInstance() {
    pthread_mutex_lock(&manager.lock);

    NFAPI_CRC_INDICATION_PDU_T* instance = manager.head;
    if (instance) {
        manager.head = instance->next;
        --manager.currentInstances;
    } else {
        instance = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!instance) {
            // Handle memory allocation failure here
        }
    }

    pthread_mutex_unlock(&manager.lock);

    return instance;
}

void recycleInstance(NFAPI_CRC_INDICATION_PDU_T* instance) {
    pthread_mutex_lock(&manager.lock);

    if (manager.currentInstances < manager.maxInstances) {
        instance->next = manager.head;
        manager.head = instance;
        ++manager.currentInstances;
    } else {
        free(instance);
    }

    pthread_mutex_unlock(&manager.lock);
}
```
