["Here is a basic implementation of the task collection using a dynamic array with custom allocator and resize strategy. This example uses pthread mutex for thread safety, but you may want to use other synchronization primitives depending on your specific requirements. 

```c
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <pthread.h>

typedef struct {
    char *name;
    struct timeval start_time, end_time;
    int priority;
} task;

typedef struct {
    task **tasks;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} task_collection;

task *create_task(const char *name, int priority) {
    task *new_task = malloc(sizeof(task));
    new_task->name = strdup(name);
    gettimeofday(&new_task->start_time, NULL);
    new_task->priority = priority;
    return new_task;
}

void destroy_task(task *t) {
    free(t->name);
    free(t);
}

task_collection *create_collection() {
    task_collection *new_coll = malloc(sizeof(task_collection));
    new_coll->capacity = 10;
    new_coll->count = 0;
    new_coll->tasks = calloc(new_coll->capacity, sizeof(task*));
    pthread_mutex_init(&new_coll->lock, NULL);
    return new_coll;
}

void destroy_collection(task_collection *c) {
    for (size_t i = 0; i < c->count; ++i) {
        destroy_task(c->tasks[i]);
    }
    free(c->tasks);
    pthread_mutex_destroy(&c->lock);
    free(c);
}

void add_task(task_collection *c, task *t) {
    pthread_mutex_lock(&c->lock);

    if (c->count == c->capacity) {
        c->capacity *= 2;
        c->tasks = realloc(c->tasks, c->capacity * sizeof(task*));
    }

    c->tasks[c->count++] = t;

    pthread_mutex_unlock(&c->lock);
}

void end_task(task *t) {
    gettimeofday(&t->end_time, NULL);
}

double task_duration(const task *t) {
    return (t->end_time.tv_sec - t->start_time.tv_sec) +
           (t->end_time.tv_usec - t->start_time.tv_usec) / 1e6;
}
```
