        $query = "INSERT INTO users (name, email, password) VALUES (?, ?, ?)";
        $stmt = $this->db->prepare($query);
        $stmt->execute([$userData['name'], $userData['email'], $userData['password']]);

        return ['success' => 'User created successfully'];
