void* process_session(void* arg) {
    session_data* data = (session_data*)arg;

    // Allocate memory for 10,000 integers
    if ((data->integers = malloc(sizeof(int) * 10000)) == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
