        if (data->count >= 10000) {
            break;
        }
    }

    // Calculate and print the average of all integers in the current session
    double sum = 0.0;
    pthread_mutex_lock(&data->lock);
    for (size_t i = 0; i < data->count; ++i) {
        sum += data->integers[i];
    }
    pthread_mutex_unlock(&data->lock);

    double average = sum / data->count;
    printf("Average: %f\n", average);

    if (average > 100) {
        printf("Warning: The dataset may have an unusually high distribution.\n");
    }

