void addToFreqTracker(int value) {
    for (size_t i = 0; i < freq_tracker_size; ++i) {
        if (freq_tracker[i].value == value) {
            ++freq_tracker[i].frequency;
            return;
        }
    }

    if (freq_tracker_capacity <= freq_tracker_size) {
        freq_tracker = realloc(freq_tracker, sizeof(*freq_tracker) * (freq_tracker_capacity += 10000));
    }

    freq_tracker[freq_tracker_size].value = value;
    freq_tracker[freq_tracker_size].frequency = 1;
    ++freq_tracker_size;
}

int findLargest(const int* array, size_t length) {
    if (length == 0) return INT_MIN;

    int largest = array[0];
    for (size_t i = 1; i < length; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    return largest;
}

void readIntegers() {
    size_t capacity = 100000, size = 0;
    int* array = malloc(sizeof(*array) * capacity);

    while (scanf("%d", &array[size]) == 1 && size < INT_MAX) {
        addToFreqTracker(array[size]);
        ++size;

        if (size == capacity) {
            array = realloc(array, sizeof(*array) * (capacity += 10000));
        }
    }

    int largest = findLargest(array, size);
    printf("The largest integer is: %d\n", largest);

    free(array);
}
