NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulate(int n, int timeout) {
    if (n <= 0 || timeout < 0) {
        printf("Invalid input values\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
