function findElementsByTagAndAttribute(rootElement, tagName, attributeName, attributeValue) {
    let result = [];

    function traverseDOMTree(element) {
        if (element.tagName === tagName && element.getAttribute(attributeName) === attributeValue) {
            result.push(element);
