} MAC_FRAME_INFO_T;

MAC_FRAME_INFO_T* process(PHY_LAYER_PACKET* phyLayerPackets, LAYER3_MESSAGE* layer3Messages, int size) {
    assert(size <= 5000); /* Ensure input size doesn't exceed limit */

    MAC_FRAME_INFO_T *macFrameInfoList = NULL, *tmp;
    UNIQUE_KEY uniqueKey;

    for (int i = 0; i < size; ++i) {
        /* Check if packet/message is already in the list */
        HASH_FIND(hh, macFrameInfoList, &uniqueKey, sizeof(UNIQUE_KEY), tmp);

        if (!tmp) {
            /* Packet/message not found, add it to the list */
            tmp = malloc(sizeof(MAC_FRAME_INFO_T));
            tmp->phyLayerPacket = phyLayerPackets + i;
            tmp->layer3Message = layer3Messages + i;

            /* Compute sequence number and timestamp */
            // ...

            HASH_ADD(hh, macFrameInfoList, phyLayerPacket, sizeof(PHY_LAYER_PACKET), tmp);
        } else {
            /* Packet/message already in the list, free temporary pointer */
            free(tmp);
        }
    }

    return macFrameInfoList;
}
