#include <assert.h>

typedef struct {
    int value;
    time_t timestamp;
} record;

typedef struct {
    long offset;
    int key;
    record *records;
} DataPacket;

typedef struct {
    size_t capacity;
    size_t count;
    DataPacket *packets;
    pthread_mutex_t lock;
} PacketCollection;

void init_collection(PacketCollection *collection, size_t initial_capacity) {
    collection->count = 0;
    collection->capacity = initial_capacity;
    collection->packets = malloc(initial_capacity * sizeof(DataPacket));
    assert(collection->packets != NULL);
    pthread_mutex_init(&collection->lock, NULL);
}

void resize_collection(PacketCollection *collection) {
    collection->capacity *= 2;
    DataPacket *new_packets = realloc(collection->packets, collection->capacity * sizeof(DataPacket));
    assert(new_packets != NULL);
    collection->packets = new_packets;
}

void add_to_collection(PacketCollection *collection, DataPacket packet) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        resize_collection(collection);
    }

    memcpy(&collection->packets[collection->count], &packet, sizeof(DataPacket));
    collection->count++;

    pthread_mutex_unlock(&collection->lock);
}

int rand_range(int min_n, int max_m) {
    return rand() % (max_m - min_n + 1) + min_n;
}

void init_packets(PacketCollection *long_offsets, PacketCollection *keys, PacketCollection *records) {
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < 1e7; ++i) {
        DataPacket packet = { .offset = rand(), .key = rand_range(0, 256), .records = malloc(3 * sizeof(record)) };

        for (size_t j = 0; j < 3; ++j) {
            record rec = { .value = rand_range(0, 1e7), .timestamp = time(NULL) };
            memcpy(&packet.records[j], &rec, sizeof(record));
        }

        add_to_collection(long_offsets, packet);
        add_to_collection(keys, packet);
        add_to_collection(records, packet);
    }
}
