['Here is a basic implementation of your requirements in C using pthreads for thread safety and a doubly linked list to manage the records. Note that this code does not include the integration with an external data source or serialization into binary format, as these would require additional details about how the data is provided and what kind of binary format you want to use.

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
    int value;
    struct Record *prev;
    struct Record *next;
} Record;

typedef struct List {
    pthread_mutex_t lock;
    Record *head;
    Record *tail;
    size_t count;
} List;

List* create_list() {
    List *list = malloc(sizeof(List));
    if (list == NULL) return NULL;

    list->count = 0;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_list(List *list) {
    Record *current = list->head;
    while (current != NULL) {
        Record *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_record(List *list, long offset, int key) {
    Record *new_record = malloc(sizeof(Record));
    if (new_record == NULL) return -1;

    new_record->offset = offset;
    new_record->key = key;
    srand(time(NULL));
    new_record->value = rand() % 100 + 1; // Random value between 1 and 100
    new_record->prev = NULL;
    new_record->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = new_record;
        list->tail = new_record;
    } else {
        new_record->prev = list->tail;
        list->tail->next = new_record;
        list->tail = new_record;
    }

    list->count++;

    pthread_mutex_unlock(&list->lock);

    return 0;
}
```
This code creates a doubly linked list with thread safety. It also includes an `add_record` function that adds a new record to the end of the list, initializing its value with a random number between 1 and 100. The `destroy_list` function frees all memory allocated for the records in the list and then the list itself.
']

