['Here is an example of how you might structure this program using C++ with Boost library for network communication and logging. This code does not include all the features mentioned in the task description due to its complexity but it provides a good starting point. 

```cpp
#include <boost/asio.hpp>
#include <boost/log/trivial.hpp>
#include <iostream>
#include <string>
#include <thread>
#include <vector>

using boost::asio::ip::tcp;

void send_request(const std::string& server, const std::string& path) {
    try {
        boost::asio::io_service io_service;
        tcp::resolver resolver(io_service);
        tcp::resolver::query query(server, "http");
        tcp::resolver::iterator endpoint_iterator = resolver.resolve(query);
        tcp::socket socket(io_service);
        boost::asio::connect(socket, endpoint_iterator);

        boost::asio::streambuf request;
        std::ostream request_stream(&request);
        request_stream << "GET " << path << " HTTP/1.0\r\n";
        request_stream << "Host: " << server << "\r\n";
        request_stream << "Accept: */*\r\n";
        request_stream << "Connection: close\r\n\r\n";

        boost::asio::write(socket, request);

        boost::asio::streambuf response;
        boost::system::error_code error;
        while (boost::asio::read(socket, response, boost::asio::transfer_at_least(1), error)) {
            BOOST_LOG_TRIVIAL(info) << &response;
        }

        if (error != boost::asio::error::eof) {
            throw boost::system::system_error(error);
        }
    } catch (std::exception& e) {
        BOOST_LOG_TRIVIAL(error) << "Exception: " << e.what();
    }
}

int main() {
    std::vector<std::thread> threads;

    // Add your endpoints here
    std::vector<std::pair<std::string, std::string>> endpoints = { {"localhost", "/"}, {"example.com", "/"} };

    for (const auto& endpoint : endpoints) {
        threads.push_back(std::thread(send_request, endpoint.first, endpoint.second));
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
```
This code creates a simple HTTP client that sends GET requests to multiple endpoints concurrently using separate threads. It uses Boost ASIO library for network communication and Boost Log for logging. The log messages include the timestamp, status codes, and error details. However, this is a basic example and does not cover all the features mentioned in your task description.
