using System.Text;
using Newtonsoft.Json;

public class PageUpdateController : Controller
{
    private readonly ILogger<PageUpdateController> _logger;
    private readonly IMemoryCache _cache;
    private static HttpClient _httpClient = new HttpClient();
    private const string ContentManagementServiceUrl = "https://content-management.service/api";

    public PageUpdateController(ILogger<PageUpdateController> logger, IMemoryCache memoryCache)
    {
        _logger = logger;
        _cache = memoryCache;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateElement([FromBody] UpdateRequest request)
    {
        // Verify the user is authorized and validate the provided data.
        if (!IsAuthorized(request.UserId))
            return Unauthorized();

        if (!ValidateContent(request.HtmlContent))
            return BadRequest("Invalid content");

        var cacheKey = $"{request.PageSectionId}_{request.ElementId}";
        string cachedHtml;

        // Check the cache first to avoid unnecessary service calls and CDN access.
        if (!_cache.TryGetValue(cacheKey, out cachedHtml))
        {
            var policy = Policy
                .Handle<Exception>()
                .RetryAsync(3);

            await policy.ExecuteAsync(async () =>
            {
                // Call the external content management service to perform the update.
                var response = await _httpClient.PostAsync(ContentManagementServiceUrl, new StringContent(JsonConvert.SerializeObject(request), Encoding.UTF8, "application/json"));

                if (!response.IsSuccessStatusCode)
                    throw new Exception("Failed to update content");
            });

            // Update the cache with the new HTML content.
            _cache.Set(cacheKey, request.HtmlContent);
        }

        // Return a response indicating whether the page should be refreshed and metrics for performance monitoring.
        return Ok(new { RefreshPage = true });
    }

