    AES_set_decrypt_key(key, 128, &aesKey);
    AES_cbc_encrypt(ciphertext, plaintext, ciphertextLen, &aesKey, iv, AES_DECRYPT);

    // Return managed array of structs and decrypted plaintext
    void* result = malloc(sizeof(DataStruct*) + sizeof(unsigned char*));
    if (!result) {
