    return new Promise((resolve, reject) => {
        const sandbox = vm.createContext({});
        let module;

        try {
            module = require(modulePath);
        } catch (e) {
            reject(`Error loading module: ${e}`);
        }

        blueslip.reset(); // Reset mock state before each test

        sandbox[f.name] = function () {
            try {
                f.apply(module, arguments);
                resolve('Test passed');
            } catch (e) {
                reject(`Error executing test: ${e}`);
            }
        };

        vm.runInContext(f.toString(), sandbox);
    });
}

function runTests() {
    const testModules = ['module1', 'module2']; // Assume these are the paths to your test modules

    let results = [];

    for (let modulePath of testModules) {
        try {
            const module = require(modulePath);

            for (let f in module) {
                if (typeof module[f] === 'function') {
                    executeTest(modulePath, module[f])
                        .then((result) => results.push({ module: modulePath, test: f, result }))
                        .catch((error) => results.push({ module: modulePath, test: f, error }));
                }
            }
        } catch (e) {
            console.log(`Error loading module ${modulePath}: ${e}`);
        }
    }

    // Aggregate results and report to the test framework
    testFramework.reportResults(results);
}
```
This code uses Node's built-in `vm` module to create a sandboxed environment for each test, ensuring that no side effects on global state occur between tests. It also uses `blueslip` to simulate dependencies and external data sources before each test execution. The results of the tests are aggregated and reported to the test framework at the end.
"]

