['Here is a basic implementation of the described function using Boost Asio library for asynchronous I/O operations, Boost Beast for HTTP requests, and Boost Log for logging. This code does not include the probabilistic model or resource management part due to its complexity. 

```cpp
#include <boost/asio.hpp>
#include <boost/beast.hpp>
#include <boost/log/trivial.hpp>
#include <fstream>

namespace net = boost::asio;                    // from <boost/asio.hpp>
using tcp = net::ip::tcp;                       // from <boost/asio/ip/tcp.hpp>
namespace beast = boost::beast;                 // from <boost/beast.hpp>
namespace http = beast::http;                   // from <boost/beast/http.hpp>

net::awaitable<void> make_request(std::string host, std::string port) {
    try {
        net::io_context ioc;
        tcp::resolver resolver(ioc);
        beast::tcp_stream stream(ioc);

        auto const results = co_await resolver.async_resolve(host, port);

        co_await beast::get_lowest_layer(stream).async_connect(results);

        http::request<http::string_body> req{http::verb::get, "/", 11};
        req.set(http::field::host, host);
        req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);

        co_await http::async_write(stream, req);

        beast::flat_buffer buffer;
        http::response<http::dynamic_body> res;

        co_await http::async_read(stream, buffer, res);

        std::ofstream logfile("log.txt", std::ios::app);
        logfile << beast::make_printable(res.body().data()) << "\n";
    } catch (std::exception const& e) {
        BOOST_LOG_TRIVIAL(error) << "Error: " << e.what() << std::endl;
    }
}

int main() {
    net::io_context ioc;
    net::co_spawn(ioc, make_request("example.com", "80"), net::detached);
    ioc.run();
    return 0;
}
```
