char* processString(const char *input, int sizeLimit, bool strictFlag, char **output) {
    if (sizeLimit <= 0 || input == NULL) {
        return NULL;
    }

    int len = strlen(input);
    if (len >= sizeLimit - 1) {
        return NULL;
    }

    *output = malloc((strictFlag ? sizeLimit : sizeLimit + 1) * sizeof(char));
    if (*output == NULL) {
        memoryError = true;
        return NULL;
    }

    strncpy(*output, input, len);
    (*output)[len] = '\0';

    if (len < sizeLimit - 1) {
        (*output)[len] = strictFlag ? ',' : ' ';
        (*output)[len + 1] = '\0';
    }

    return *output;
}
