DataPacket* initialize_data_packets(int max_packets, size_t max_payload_size) {
    pthread_mutex_lock(&lock);

    DataPacket *packets = malloc(max_packets * sizeof(DataPacket));
    if (packets == NULL) {
        log_event("Failed to allocate memory for packets");
        return NULL;
    }

    int allocated = 0;
    for (int i = 0; i < max_packets; ++i) {
        size_t payload_size = rand() % max_payload_size + 1;  // Random payload size

        char *payload = malloc(payload_size);
        if (payload == NULL && max_payload_size > 0) {
            log_event("Failed to allocate memory for payload");
            break;
        }

        packets[i].payload = payload;
        packets[i].timestamp = time(NULL);
        ++allocated;
    }

    atomic_fetch_add(&allocated_packets, allocated);
    log_event("Successfully allocated memory for packets");

    pthread_mutex_unlock(&lock);

    return packets;
}

void deinitialize_data_packets(DataPacket *packets, int num_packets) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_packets; ++i) {
        free(packets[i].payload);
    }
    atomic_fetch_sub(&allocated_packets, num_packets);
    log_event("Deallocated memory");

    pthread_mutex_unlock(&lock);
}
