#include <time.h>

typedef struct Record {
    long offset;
    int key;
    int value;
    time_t expiration;
    struct Record *next;
} Record;

Record* head = NULL;
int recordCount = 0;
pthread_mutex_t lock;

void* backgroundWorker(void* arg) {
    while (1) {
        sleep(60); // Sleep for a minute

        pthread_mutex_lock(&lock);
        Record *current = head, *prev = NULL;
        time_t now = time(NULL);

        while (current != NULL) {
            if (difftime(now, current->expiration) > 0) {
                // Remove the record
                if (prev == NULL) {
                    head = current->next;
                } else {
                    prev->next = current->next;
                }

                free(current);
                recordCount--;
            }

            prev = current;
            current = current->next;
        }

        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

void insertRecord(long offset, int key, int value) {
    Record* newRecord = malloc(sizeof(Record));
    if (newRecord == NULL) {
        // Handle memory allocation failure
        return;
    }

    newRecord->offset = offset;
    newRecord->key = key;
    newRecord->value = value;
    time(&newRecord->expiration);
    newRecord->next = NULL;

    pthread_mutex_lock(&lock);
    if (head == NULL) {
        head = newRecord;
    } else {
        Record* current = head;
        while (current->next != NULL) {
            current = current->next;
        }

        current->next = newRecord;
    }

    recordCount++;
    pthread_mutex_unlock(&lock);
}
```
