#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray *a, size_t initialSize) {
    a->array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(initialSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (a->array == NULL) {
        // Handle memory allocation failure
        return;
    }
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&(a->lock), NULL);
}

void insertDynamicArray(DynamicArray *a, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&(a->lock));

    if (a->used == a->size) {
        a->size *= 2;
        a->array = (NFAPI_CRC_INDICATION_PDU_T*) realloc(a->array, a->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (a->array == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&(a->lock));
            return;
        }
    }

    a->array[a->used++] = element;

    pthread_mutex_unlock(&(a->lock));
}

void freeDynamicArray(DynamicArray *a) {
    pthread_mutex_destroy(&(a->lock));
    free(a->array);
    a->array = NULL;
    a->used = a->size = 0;
}
```
