['Here is an example of how you might implement this in C using POSIX threads (pthreads) for thread safety and dynamic memory allocation with realloc for resizing. Note that this is a simplified version and does not include all features mentioned, but it should give you a good starting point. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    void* payload;
    time_t timestamp;
    int status; // 0 for success, -1 for failure
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    unsigned long ignoreMask;
} PacketArray;

void initPacket(DataPacket* packet) {
    packet->payload = NULL;
    packet->timestamp = 0;
    packet->status = -1; // initially set to failure
}

int initPacketArray(PacketArray* array, size_t initialCapacity) {
    if (pthread_mutex_init(&array->lock, NULL) != 0) {
        return -1;
    }

    array->packets = malloc(initialCapacity * sizeof(DataPacket));
    if (!array->packets) {
        pthread_mutex_destroy(&array->lock);
        return -1;
    }

    for (size_t i = 0; i < initialCapacity; ++i) {
        initPacket(&array->packets[i]);
    }

    array->capacity = initialCapacity;
    array->count = 0;
    array->ignoreMask = 0; // initially ignore no packets

    return 0;
}

void destroyPacketArray(PacketArray* array) {
    pthread_mutex_destroy(&array->lock);
    free(array->packets);
}

int addPacket(PacketArray* array, DataPacket packet) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity * 0.75) { // resize when reaching 75% capacity
        size_t newCapacity = array->capacity * 2;
        DataPacket* newArray = realloc(array->packets, newCapacity * sizeof(DataPacket));

        if (!newArray) {
            pthread_mutex_unlock(&array->lock);
            return -1; // failed to resize array
        }

        array->packets = newArray;
        array->capacity = newCapacity;
    }

    if ((array->ignoreMask & (1 << packet.status)) == 0) { // check if packet should be ignored
        initPacket(&array->packets[array->count++]);
    }

    pthread_mutex_unlock(&array->lock);
    return 0;
}
```
This code provides a basic structure for managing an array of `DataPacket` structures. It uses a mutex to ensure thread safety, and reallocates memory when the array reaches 75% capacity. The `ignoreMask` field can be used to selectively ignore certain packet types based on their status indicator.

