std::mutex mtx; // Mutex for thread safety

void insertAfter(std::forward_list<std::string>& flist, const std::string& target, const std::string& toInsert) {
    std::lock_guard<std::mutex> lock(mtx); // Lock the mutex

    auto prev = flist.before_begin();
    for (auto it = flist.begin(); it != flist.end(); ++it, ++prev) {
        if (*it == target) {
            flist.insert_after(it, toInsert); // Insert after the first occurrence of the target string
            return;
        }
    }

    // If the target string is not found, append it to the end of the list
    flist.insert_after(prev, toInsert);
}
