['Here is a basic implementation in C using libtiff library to parse TIFF files. This code does not handle all your requirements but it gives you an idea of how to start with. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>

typedef struct {
    uint16 bitsPerSample;
    uint16 samplesPerPixel;
    char compression[25];
    uint32 width;
    uint32 height;
} ImageMetadata;

void parseTIFF(const char* filename, ImageMetadata *metadata) {
    TIFF* tiff = TIFFOpen(filename, "r");
    if (tiff == NULL) {
        fprintf(stderr, "Failed to open file %s\n", filename);
        return;
    }

    uint32 width, height;
    TIFFGetField(tiff, TIFFTAG_IMAGEWIDTH, &width);
    TIFFGetField(tiff, TIFFTAG_IMAGELENGTH, &height);
    metadata->width = width;
    metadata->height = height;

    uint16 bps, spp;
    if (TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &bps) && 
        TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &spp)) {

        metadata->bitsPerSample = bps;
        metadata->samplesPerPixel = spp;
    } else {
        fprintf(stderr, "Failed to read bits per sample or samples per pixel\n");
    }

    char compression[25];
    if (TIFFGetField(tiff, TIFFTAG_COMPRESSION, &compression)) {
        strcpy(metadata->compression, compression);
    } else {
        fprintf(stderr, "Failed to read compression type\n");
    }

    // TODO: Implement decompression and error handling for different types of images.

    TIFFClose(tiff);
}
```
This code reads the basic metadata from a TIFF file (width, height, bits per sample, samples per pixel, compression type). It does not handle decompression or edge cases as you requested. You would need to implement these features yourself based on your specific requirements and constraints. 

