```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

#define SALT_LEN 8
#define IV_LEN EVP_MAX_IV_LENGTH
#define KEY_LEN 32 // AES-256

typedef struct {
    unsigned char key[KEY_LEN];
    unsigned char iv[IV_LEN];
} aes256_context;

void handleErrors(void) { /* Error handling code here */ }

int aes256_init(aes256_context *ctx, const char *password, int password_len) {
    unsigned char salt[SALT_LEN];
    RAND_bytes(salt, SALT_LEN);

    if(!EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, (unsigned char*)password, password_len, 10000, ctx->key, ctx->iv)) {
        handleErrors();
        return 0;
    }

    return 1;
}

int aes256_encrypt(aes256_context *ctx, unsigned char *plaintext, int plaintext_len, unsigned char **ciphertext) {
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();

    if(!EVP_EncryptInit_ex(cipher_ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        handleErrors();
        return -1;
    }

    int len = 0;
    if(!EVP_EncryptUpdate(cipher_ctx, *ciphertext, &len, plaintext, plaintext_len)) {
        handleErrors();
        return -1;
    }

    int ciphertext_len = len;
    if(!EVP_EncryptFinal_ex(cipher_ctx, *ciphertext + len, &len)) {
        handleErrors();
        return -1;
    }

    ciphertext_len += len;
    EVP_CIPHER_CTX_free(cipher_ctx);

    return ciphertext_len;
}

int aes256_decrypt(aes256_context *ctx, unsigned char *ciphertext, int ciphertext_len, unsigned char **plaintext) {
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();

    if(!EVP_DecryptInit_ex(cipher_ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        handleErrors();
        return -1;
    }

    int len = 0;
    if(!EVP_DecryptUpdate(cipher_ctx, *plaintext, &len, ciphertext, ciphertext_len)) {
        handleErrors();
        return -1;
    }

    int plaintext_len = len;
    if(!EVP_DecryptFinal_ex(cipher_ctx, *plaintext + len, &len)) {
        handleErrors();
        return -1;
    }

    plaintext_len += len;
    EVP_CIPHER_CTX_free(cipher_ctx);

    return plaintext_len;
}
```
