```java
import org.apache.http.HttpResponse;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;

public class Application {
    private static final Logger logger = LoggerFactory.getLogger(Application.class);
    private static final String TEMP_FILENAME = "tempfile";
    private static final CloseableHttpClient httpclient = HttpClients.createDefault();

    public void executeCommandAndInteractWithExternalService() {
        try {
            deleteTempFileIfExists(TEMP_FILENAME);

            Process process = Runtime.getRuntime().exec("command");
            int exitCode = process.waitFor();
            logger.info("Command execution completed with exit code: " + exitCode);

            HttpGet request = new HttpGet("http://external-service.com/endpoint");
            HttpResponse response = httpclient.execute(request);
            int statusCode = response.getStatusLine().getStatusCode();
            logger.info("HTTP GET request completed with status code: " + statusCode);

        } catch (IOException | InterruptedException e) {
            logger.error("An error occurred during command execution or HTTP request", e);
        } finally {
            httpclient.closeQuietly();
        }
    }

    private void deleteTempFileIfExists(String filename) throws IOException {
        if (Files.exists(Paths.get(filename))) {
            Files.delete(Paths.get(filename));
            logger.info("Temporary file deleted: " + filename);
        } else {
            logger.info("No temporary file found to delete");
        }
    }
}
```
This code does not include all the details you mentioned, but it should give you a good starting point for your application. You would need to add more error handling and logging as per your requirements. Also, please note that this is a simplified version of what you might do in a real-world scenario. In a production environment, you would want to handle exceptions more gracefully, use connection pooling for HTTP clients, manage resources properly, etc.
