#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <jansson.h>

typedef struct {
    int value;
    short sequence_number;
    long timestamp;
} record;

typedef struct {
    long* offsets;
    int* keys;
    short* sequence_numbers;
    record* records;
    size_t max_size;
    size_t current_size;
    pthread_mutex_t lock;
} data_structure;

data_structure* create_data_structure(size_t max_size) {
    data_structure* ds = malloc(sizeof(data_structure));
    if (ds == NULL) return NULL;

    ds->offsets = malloc(max_size * sizeof(long));
    ds->keys = malloc(max_size * sizeof(int));
    ds->sequence_numbers = malloc(max_size * sizeof(short));
    ds->records = calloc(max_size, sizeof(record));

    if (ds->offsets == NULL || ds->keys == NULL || ds->sequence_numbers == NULL || ds->records == NULL) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->sequence_numbers);
        free(ds->records);
        free(ds);
        return NULL;
    }

    ds->max_size = max_size;
    ds->current_size = 0;
    pthread_mutex_init(&ds->lock, NULL);

    return ds;
}

void destroy_data_structure(data_structure* ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->sequence_numbers);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

int validate_token(const char* json) {
    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    if(!root) return 0;

    json_t *access_token = json_object_get(root, "access_token");
    json_t *expires_in = json_object_get(root, "expires_in");
    json_t *token_type = json_object_get(root, "token_type");

    if(!json_is_string(access_token) || !json_is_integer(expires_in) || !json_is_string(token_type)) {
        json_decref(root);
        return 0;
    }

    if(strcmp(json_string_value(token_type), "Bearer") != 0 || json_integer_value(expires_in) <= 0) {
        json_decref(root);
        return 0;
    }

    json_decref(root);
    return 1;
}
```
