        _httpClient = httpClient;
        _configuration = configuration;
    }

    public async Task<UploadConfirmation> ProcessAndUploadAsync(byte[] data)
    {
        var startTime = DateTime.UtcNow;

        using (var compressedStream = new MemoryStream())
        using (var deflateStream = new DeflateStream(compressedStream, CompressionLevel.Optimal))
        {
            await deflateStream.WriteAsync(data, 0, data.Length);
            await deflateStream.FlushAsync();

            var compressedData = compressedStream.ToArray();
            var hash = GetHash(compressedData);

            var headers = GenerateHeaders(_configuration);
            var metadata = GenerateMetadata(_configuration);

            HttpResponseMessage response;
            int retryCount = 0;
            do
            {
                try
                {
                    using (var content = new ByteArrayContent(compressedData))
                    {
                        foreach (var header in headers)
                            _httpClient.DefaultRequestHeaders.Add(header.Key, header.Value);

                        response = await _httpClient.PostAsync(_configuration["StorageServiceUrl"], content);
                    }
                }
                catch (Exception ex)
                {
                    // Log the exception here

                    if (retryCount >= int.Parse(_configuration["MaxRetryAttempts"]))
                        throw;

                    await Task.Delay(int.Parse(_configuration["InitialBackoffInterval"]) * (int)Math.Pow(2, retryCount));
                }

                retryCount++;
            } while (!response.IsSuccessStatusCode);

            var endTime = DateTime.UtcNow;
            return new UploadConfirmation { Hash = hash, TimeTaken = endTime - startTime, Size = compressedData.Length };
