using System.Threading.Tasks;
using Newtonsoft.Json;

public class LogProcessor
{
    private static readonly string OutputFilePath = "output.csv";

    public async Task ProcessLogAsync(string logFilePath)
    {
        using (var reader = new StreamReader(logFilePath))
        {
            var headerWritten = false;

            while (!reader.EndOfStream)
            {
                var line = await reader.ReadLineAsync();

                try
                {
                    var logEntry = JsonConvert.DeserializeObject<LogEntry>(line);

                    if (logEntry != null)
                    {
                        using (var writer = new StreamWriter(OutputFilePath, true))
                        {
                            if (!headerWritten)
                            {
                                await writer.WriteLineAsync("Timestamp,ErrorCode,SubsystemId");
                                headerWritten = true;
                            }

                            var csvLine = $"{logEntry.Timestamp},{logEntry.ErrorCode},{logEntry.SubsystemId}";
                            await writer.WriteLineAsync(csvLine);
                        }
                    }
                }
                catch (JsonReaderException)
                {
                    Console.WriteLine("Skipping malformed JSON entry: " + line);
                }
            }
        }
    }

    public class LogEntry
    {
        public DateTime Timestamp { get; set; }
        public int ErrorCode { get; set; }
        public string SubsystemId { get; set; }
    }
}
```
