public class AESDecryptionService
{
    private readonly RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider();
    private readonly Aes aesAlgorithm = Aes.Create();

    public byte[] Decrypt(byte[] cipherText, byte[] key, byte[] iv)
    {
        try
        {
            using (var decryptor = aesAlgorithm.CreateDecryptor(key, iv))
            {
                return PerformCryptography(cipherText, decryptor);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error during decryption: " + ex.Message);
            throw;
        }
    }

    private byte[] PerformCryptography(byte[] data, ICryptoTransform cryptoTransformer)
    {
        using (var ms = new MemoryStream())
        {
            using (var cs = new CryptoStream(ms, cryptoTransformer, CryptoStreamMode.Write))
            {
                cs.Write(data, 0, data.Length);
            }

            return ms.ToArray();
        }
    }

    private void GenerateRandomBytes(byte[] buffer)
    {
        rng.GetBytes(buffer);
    }
}
```
