```javascript
const { exec } = require('child_process');
const os = require('os');

function executeCommand(command) {
    return new Promise((resolve, reject) => {
        const process = exec(command);

        // Streaming the output in real-time to the client.
        process.stdout.on('data', (data) => {
            console.log(`stdout: ${data}`);
        });

        process.stderr.on('data', (data) => {
            console.error(`stderr: ${data}`);
        });

        process.on('close', (code) => {
            if (code !== 0) {
                reject(new Error(`Command failed with exit code ${code}`));
            } else {
                resolve();
            }
        });
    });
}
```

This function takes a command as input and returns a Promise that resolves when the command finishes successfully, or rejects if it fails. The output of the command is streamed to the console in real-time. 

