from abc import ABC, abstractmethod

class ConfigFactory(ABC):
    @abstractmethod
    def load(self, data: str) -> dict:
        pass

    @abstractmethod
    def dump(self, data: dict) -> str:
        pass

class JsonConfigFactory(ConfigFactory):
    def load(self, data: str) -> dict:
        return json.loads(data)

    def dump(self, data: dict) -> str:
        return json.dumps(data)

class YamlConfigFactory(ConfigFactory):
    def load(self, data: str) -> dict:
        return yaml.safe_load(data)

    def dump(self, data: dict) -> str:
        return yaml.dump(data)

class ConfigManager:
    def __init__(self):
        self._factories = {
            'json': JsonConfigFactory(),
            'yaml': YamlConfigFactory()
        }

    def register_factory(self, format: str, factory: ConfigFactory):
        self._factories[format] = factory

    def load(self, data: str, format: str) -> dict:
        return self._factories[format].load(data)

    def dump(self, data: dict, format: str) -> str:
        return self._factories[format].dump(data)
```

