#include <stdlib.h>
#include <time.h>
#include <assert.h>
#include <string.h>

typedef struct record {
    long offset;
    int key;
} Record;

Record* initialize(size_t size, long minOffset, long maxOffset) {
    assert(maxOffset > minOffset);

    // Allocate memory for the arrays
    long *offsets = malloc(sizeof(long) * size);
    int *keys = malloc(sizeof(int) * size);
    Record *records = calloc(size, sizeof(Record));

    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the keys array with sequential integers
    for (size_t i = 0; i < size; ++i) {
        keys[i] = i;
    }

    // Initialize the offsets array with unique random values within a predefined range
    srand(time(NULL));
    long *usedOffsets = calloc(maxOffset - minOffset + 1, sizeof(long));
    if (usedOffsets == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < size; ++i) {
        long offset;
        do {
            offset = rand() % (maxOffset - minOffset + 1) + minOffset;
        } while (usedOffsets[offset - minOffset] != 0);

        usedOffsets[offset - minOffset] = 1;
        offsets[i] = offset;
    }

    free(usedOffsets);

    // Initialize the records array
    for (size_t i = 0; i < size; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    free(keys);
    free(offsets);

    return records;
}
```
This code uses dynamic memory allocation to create the arrays and structures. It also verifies that all offsets are unique within the specified range before proceeding with the rest of the initialization process. If a memory allocation fails, it prints an error message and terminates the program. After initialization, it returns a pointer to the first element of the `record` array. Finally, it frees all allocated memory after the function execution completes.
