```c
#include <stdio.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>

// Define a structure to hold the cache data
typedef struct {
    char hostname[256];
    in_addr_t addresses[10]; // Assuming max 10 IPs per hostname
    time_t timestamp;
} dns_cache_entry;

// Define a global array to hold the cache data
#define CACHE_SIZE 256
dns_cache_entry cache[CACHE_SIZE];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Define a function to handle signals and clear the cache
void sig_handler(int signum) {
    pthread_mutex_lock(&cache_lock);
    memset(cache, 0, sizeof(cache));
    pthread_mutex_unlock(&cache_lock);
}

// Define a function to resolve DNS and handle caching
in_addr_t* dns_resolve(const char *hostname) {
    static in_addr_t addresses[10]; // Assuming max 10 IPs per hostname

    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (!strcmp(hostname, cache[i].hostname)) {
            // If the entry is in the cache and not expired, return it
            if ((time(NULL) - cache[i].timestamp) < 300) {
                pthread_mutex_unlock(&cache_lock);
                return cache[i].addresses;
            } else {
                // If the entry is in the cache but expired, remove it
                memset(&cache[i], 0, sizeof(dns_cache_entry));
                break;
            }
        }
    }

    struct hostent *host = gethostbyname(hostname);
    if (host == NULL) {
        pthread_mutex_unlock(&cache_lock);
        return NULL; // Return error code or handle the error gracefully
    }

    for (int i = 0; host->h_addr_list[i] != NULL && i < 10; ++i) {
        addresses[i] = *(in_addr_t*)host->h_addr_list[i];
    }

    // Add the new entry to the cache
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (!cache[i].timestamp) {
            strncpy(cache[i].hostname, hostname, sizeof(cache[i].hostname));
            memcpy(cache[i].addresses, addresses, sizeof(addresses));
            cache[i].timestamp = time(NULL);
            break;
        }
    }

    pthread_mutex_unlock(&cache_lock);
    return addresses;
}

int main() {
    // Register the signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(struct sigaction));
    sa.sa_handler = &sig_handler;
    sigaction(SIGUSR1, &sa, NULL);

    // Use the dns_resolve function in your code
    const char *hostname = "example.com";
    in_addr_t *addresses = dns_resolve(hostname);
    if (addresses == NULL) {
        printf("Failed to resolve hostname\n");
    } else {
        for (int i = 0; addresses[i] != 0 && i < 10; ++i) {
            struct in_addr addr = { .s_addr = addresses[i] };
            printf("%s\n", inet_ntoa(addr));
        }
    }

    return 0;
}
```
