typedef struct {
    int id; // unique identifier
} MAC_HEADER;

typedef struct {
    char* data; // variable-length data field
    size_t length; 
} MAC_DATA;

typedef struct {
    MAC_HEADER header;
    MAC_DATA data;
} MAC_PDU;

typedef struct Node {
    MAC_PDU pdu;
    struct Node* next;
} Node;

Node* head = NULL; // linked list to manage PDUs
size_t maxPDUs = 1024; // maximum number of PDUs that can be managed

void addPDU(MAC_HEADER header, MAC_DATA data) {
    if (getSize() >= maxPDUs) return; // check if we have reached the limit

    Node* newNode = malloc(sizeof(Node));
    newNode->pdu.header = header;
    newNode->pdu.data = data;
    newNode->next = head;
    head = newNode;
}

void removePDU(int id) {
    Node* temp = head, *prev = NULL;

    while (temp != NULL && temp->pdu.header.id != id) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // PDU not found

    if (prev != NULL) 
        prev->next = temp->next;

    if (temp == head) 
        head = temp->next;

    free(temp);
}

void updatePDUData(int id, char* newData, size_t length) {
    Node* temp = head;

    while (temp != NULL && temp->pdu.header.id != id) 
        temp = temp->next;

    if (temp == NULL) return; // PDU not found

    free(temp->pdu.data.data); // free old data
    temp->pdu.data.length = length;
    temp->pdu.data.data = malloc(length);
    memcpy(temp->pdu.data.data, newData, length); // copy new data
}

size_t getSize() {
    size_t count = 0; 
    Node* temp = head;

    while (temp != NULL) {
        count++;
        temp = temp->next;
    }

    return count;
}
```
This code uses a linked list to manage the PDUs. It provides functions for adding, removing and updating PDUs. The `getSize` function is used to check if we have reached the limit of PDUs that can be managed. 

