typedef struct {
    // Define the structure members here
} PHY_LAYER_FRAME_INFO;

// Custom memory allocator
void* custom_alloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        // Handle allocation failure
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Custom memory de-allocator
void custom_free(void* ptr) {
    free(ptr);
}

PHY_LAYER_FRAME_INFO** allocate_frame_info(int num_channels, int* total_allocation) {
    if (num_channels < 5 || num_channels > MAX_CHANNELS) {
        // Handle invalid number of channels
        exit(EXIT_FAILURE);
    }

    *total_allocation = sizeof(PHY_LAYER_FRAME_INFO*) + (num_channels * sizeof(PHY_LAYER_FRAME_INFO));
    PHY_LAYER_FRAME_INFO** frame_info = custom_alloc(*total_allocation);

    if (frame_info == NULL) {
        // Handle allocation failure
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_channels; ++i) {
        frame_info[i] = custom_alloc(sizeof(PHY_LAYER_FRAME_INFO));

        if (frame_info[i] == NULL) {
            // Handle allocation failure
            for (--i; i >= 0; --i) {
                custom_free(frame_info[i]);
            }

            custom_free(frame_info);
            exit(EXIT_FAILURE);
        }
    }

    return frame_info;
}
