    printf("Starting server with port: %d, max connections: %d, auth type: %s, logging preferences: %d\n", 
           config->port, config->max_connections, config->auth_type, config->logging_preferences);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <config file 1> <config file 2> ...\n", argv[0]);
        return -1;
    }

    for (int i = 1; i < argc; ++i) {
        ServerConfig *config = load_config(argv[i]);
        if (config != NULL) {
            start_server(config);
            free(config);
        } else {
            return -1;
        }
    }

    return 0;
}
```
