['Here is a basic implementation of your requirements in C#:

```csharp
using System;
using UnityEngine;

public class DynamicRangeGenerator
{
    private float minValue = 0f;
    private float maxValue = 100f;
    private float scaleFactor = 1.0f;

    public float MinValue 
    { 
        get => minValue; 
        set 
        {
            if (value >= maxValue)
            {
                Debug.LogWarning("Invalid range detected, resetting to default values.");
                minValue = 0f;
                maxValue = 100f;
            }
            else
            {
                minValue = value;
            }
        } 
    }

    public float MaxValue 
    { 
        get => maxValue; 
        set 
        {
            if (value <= minValue)
            {
                Debug.LogWarning("Invalid range detected, resetting to default values.");
                minValue = 0f;
                maxValue = 100f;
            }
            else
            {
                maxValue = value;
            }
        } 
    }

    public float ScaleFactor 
    { 
        get => scaleFactor; 
        set => scaleFactor = value; 
    }

    public int GenerateRandomInt(bool inclusive = true)
    {
        if (inclusive)
            return Mathf.RoundToInt(UnityEngine.Random.Range(minValue, maxValue + 1) * scaleFactor);
        else
            return UnityEngine.Random.Range(Mathf.CeilToInt(minValue), Mathf.FloorToInt(maxValue)) * scaleFactor;
    }

    public float GenerateRandomFloat(bool inclusive = true)
    {
        if (inclusive)
            return UnityEngine.Random.Range(minValue, maxValue + 1) * scaleFactor;
        else
            return UnityEngine.Random.Range(Mathf.CeilToInt(minValue), Mathf.FloorToInt(maxValue)) * scaleFactor;
    }

    public void Reset()
    {
        minValue = 0f;
        maxValue = 100f;
        Debug.Log("Range reset to default values.");
    }

    public override string ToString()
    {
        return $"Current range: [{minValue}, {maxValue}] with scale factor of {scaleFactor}";
    }
}
```

