typedef struct Record {
    int key;
    time_t timestamp;
    long offsets[10]; // assuming max of 10 offsets for simplicity
} Record;

Record* allocateRecords(size_t num, size_t threshold) {
    if (num * sizeof(Record) > threshold) {
        fprintf(stderr, "Memory allocation exceeded the threshold.\n");
        return NULL;
    }

    Record* records = malloc(num * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records.");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int) time(NULL)); // seed the random number generator
    for (size_t i = 0; i < num; ++i) {
        records[i].key = rand();
        records[i].timestamp = time(NULL);

        for (int j = 0; j < 10; ++j) { // assuming max of 10 offsets for simplicity
            records[i].offsets[j] = rand();
        }
    }

    return records;
}
