} ResultBuffer;

void* traverse(void *arg) {
    DOMNode *node = (DOMNode *) arg;
    if (!node || visited[node]) return NULL;

    visited[node] = 1;
    char *content = get_element_content(node);
    pthread_mutex_lock(&resultBuffer.lock);
    if (strlen(resultBuffer.buffer) + strlen(content) < MAX_BUFFER_SIZE && depth <= MAX_DEPTH) {
        resultBuffer.buffer = realloc(resultBuffer.buffer, strlen(resultBuffer.buffer) + strlen(content) + 1);
        strcat(resultBuffer.buffer, content);
    } else {
        pthread_mutex_unlock(&resultBuffer.lock);
        return NULL;
    }
    pthread_mutex_unlock(&resultBuffer.lock);

    int i;
    for (i = 0; i < numSelectors; ++i) {
        if (match_selector(node, selectors[i])) {
            traverse(get_child_nodes(node));
        }
    }
}

char* processDOMTree(DOMNode *root, char **selectors, int numSelectors) {
    pthread_t thread;

    visited = calloc(numNodes, sizeof(int)); // assuming you have a count of nodes
    resultBuffer.buffer = malloc(1);
    resultBuffer.buffer[0] = '\0';
    pthread_mutex_init(&resultBuffer.lock, NULL);

    traverse(root);

    if (pthread_create(&thread, NULL, &traverse, root)) {
        return NULL; // failed to create thread
    }

    pthread_join(thread, NULL);

    free(visited);
    return resultBuffer.buffer;
}
