['Here's a basic implementation in C using linked list concept. This does not include all the features you mentioned like handling external data sources, managing multiple threads, or unit tests. Also, it doesn't handle memory leaks as it's assumed that the program will end after usage and OS will clean up the memory.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG* crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;

void insert(int RX_UE_INFORMATION_TAG, int RNTI) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data.RNTI = RNTI;
    newNode->data.crcTag = (CRC_INDICATION_REL8_TAG*) malloc(sizeof(CRC_INDICATION_REL8_TAG));
    newNode->data.crcTag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    newNode->next = NULL;

    if (head == NULL || head->data.RX_UE_INFORMATION_TAG > RX_UE_INFORMATION_TAG) {
        newNode->next = head;
        head = newNode;
    } else {
        Node* current = head;
        while (current->next != NULL && current->next->data.RX_UE_INFORMATION_TAG < RX_UE_INFORMATION_TAG) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
}

void remove(int RNTI) {
    if (head == NULL) return;

    Node* temp;
    while (head != NULL && head->data.RNTI == RNTI) {
        temp = head;
        head = head->next;
        free(temp);
    }

    if (head != NULL) {
        Node* current = head;
        while (current->next != NULL) {
            if (current->next->data.RNTI == RNTI) {
                temp = current->next;
                current->next = current->next->next;
                free(temp);
            } else {
                current = current->next;
            }
        }
    }
}

void printList() {
    Node* temp = head;
    while (temp != NULL) {
        printf("RNTI: %d, CRCFLAG: %d\n", temp->data.RNTI, temp->data.crcTag->CRCFLAG);
        temp = temp->next;
    }
}
```
This code creates a linked list where each node contains an NFAPI_CRC_INDICATION_PDU_T structure. The `insert` function inserts new nodes in ascending order based on the RX_UE_INFORMATION_TAG field, and the `remove` function removes all nodes with a specific RNTI value. The `printList` function prints the RNTI and CRCFLAG values for each node in the list.
']

