#include <string.h>

typedef struct {
    char name[50];
    int age;
    float salary;
    char department[50];
} Employee;

Employee* read_employees(FILE *file, int *count) {
    // Read the number of employees from the file.
    fread(count, sizeof(int), 1, file);

    // Allocate memory for all employees.
    Employee *employees = malloc(*count * sizeof(Employee));
    if (employees == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Read each employee from the file.
    for (int i = 0; i < *count; i++) {
        fread(&employees[i], sizeof(Employee), 1, file);
    }

    return employees;
}

float calculate_average_salary(Employee *employees, int count, int minAge, int maxAge, char *department) {
    float total = 0.0f;
    int numInRange = 0;

    for (int i = 0; i < count; i++) {
        if (employees[i].age >= minAge && employees[i].age <= maxAge 
            && strcmp(employees[i].department, department) == 0) {

            total += employees[i].salary;
            numInRange++;
        }
    }

    if (numInRange > 0) {
        return total / numInRange;
    } else {
        return 0.0f;
    }
}

int main() {
    FILE *file = fopen("employees.bin", "rb");
    if (file == NULL) {
        printf("Failed to open file.\n");
        exit(EXIT_FAILURE);
    }

    int count;
    Employee *employees = read_employees(file, &count);

    float averageSalary = calculate_average_salary(employees, count, 25, 30, "Sales");
    printf("Average salary: %.2f\n", averageSalary);

    free(employees);
    fclose(file);

    return 0;
}
