class ConfigManager {
public:
    ConfigManager() {
        loadConfig();
    }

    void loadConfig(const std::string& filePath = "config.json") {
        std::ifstream i(filePath);
        if (i) {
            try {
                nlohmann::json j;
                i >> j;
                config_ = j;
            } catch (std::exception &e) {
                SPDLOG_ERROR("Failed to load configuration: {}", e.what());
            }
        } else {
            SPDLOG_WARN("Configuration file not found, using default settings");
        }
    }

    void updateConfig(const std::string& key, const nlohmann::json& value) {
        config_[key] = value;
        saveConfig();
    }

private:
    void saveConfig() {
        std::ofstream o("config.json");
        o << std::setw(4) << config_ << std::endl;
    }

    nlohmann::json config_;
};

class Server {
public:
    Server(net::io_context& ioc, tcp::endpoint endpoint, ConfigManager& cm)
        : acceptor_(ioc), socket_(ioc), configManager_(cm) {
        beast::error_code ec;
        acceptor_.open(endpoint.protocol(), ec);
        acceptor_.bind(endpoint, ec);
        acceptor_.listen(net::socket_base::max_listen_connections, ec);
    }

    void run() {
        acceptor_.async_accept(socket_, [this](beast::error_code ec) {
            if (!ec) {
                handleRequest();
            } else {
                SPDLOG_ERROR("Failed to accept connection: {}", ec.message());
            }
            run();
        });
    }

private:
