['Here is an example implementation in C++ using `std::unordered_map` from STL which provides thread safety and efficient insertion, deletion and lookup operations. For periodic pruning, we can use a separate thread that periodically checks the map for events older than a certain time window and removes them.

```cpp
#include <iostream>
#include <unordered_map>
#include <chrono>
#include <thread>
#include <mutex>
#include <atomic>

class NetworkEvent {
public:
    NetworkEvent(int id, std::time_t timestamp, int version, std::string type) : 
        id_(id), timestamp_(timestamp), version_(version), type_(type) {}

    // Getters and setters for the class members go here.

private:
    int id_;
    std::time_t timestamp_;
    int version_;
    std::string type_;
};

class NetworkEventManager {
public:
    void insert(const NetworkEvent& event) {
        std::lock_guard<std::mutex> lock(mtx_);
        events_.insert({event.id(), event});
    }

    bool remove(int id) {
        std::lock_guard<std::mutex> lock(mtx_);
        return events_.erase(id) > 0;
    }

    NetworkEvent find(int id) const {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = events_.find(id);
        if (it != events_.end()) {
            return it->second;
        } else {
            throw std::runtime_error("Event not found");
        }
    }

    void startPruningThread() {
        pruningThreadRunning_ = true;
        pruningThread_ = std::thread([this](){
            while (pruningThreadRunning_) {
                std::this_thread::sleep_for(std::chrono::seconds(10)); // Adjust this to your needs.

                auto now = std::chrono::system_clock::now();
                std::lock_guard<std::mutex> lock(mtx_);
                for (auto it = events_.begin(); it != events_.end();) {
                    if (it->second.timestamp() < now - std::chrono::seconds(30)) { // Adjust this to your needs.
                        it = events_.erase(it);
                    } else {
                        ++it;
                    }
                }
            }
        });
    }

    void stopPruningThread() {
        pruningThreadRunning_ = false;
        if (pruningThread_.joinable()) {
            pruningThread_.join();
        }
    }

private:
    std::unordered_map<int, NetworkEvent> events_;
    mutable std::mutex mtx_;
    std::thread pruningThread_;
    std::atomic<bool> pruningThreadRunning_{false};
};
```
This code provides a basic implementation of the requirements. It uses `std::unordered_map` for efficient insertion, deletion and lookup operations. The map is protected by a mutex to ensure thread safety. A separate thread periodically checks the map for events older than a certain time window and removes them.

Please note that this code does not include any custom allocator optimization or integration with legacy systems as these are complex topics and would require more detailed requirements. Also, it doesn't handle scalability issues such as memory usage under high load. For handling large volumes of data efficiently, a database system or distributed computing framework might be necessary.
