typedef struct Node {
    char* ip_address;
    struct Node* next;
} Node;

Node* add_node(Node** head, char* ip) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->ip_address = strdup(ip);
    new_node->next = *head;
    *head = new_node;
    return new_node;
}

void remove_all(Node** head) {
    while (*head != NULL) {
        Node* next_node = (*head)->next;
        free((*head)->ip_address);
        free(*head);
        *head = next_node;
    }
}

char* find_frequent_ip(Node** head) {
    if (!head || !*head) return NULL;

    Node* current = *head;
    char* max_ip = current->ip_address;
    int max_count = 0, count = 0;
    while (current != NULL) {
        count = 1;
        Node* temp = current;
        while (temp->next != NULL) {
            if (strcmp(current->ip_address, temp->next->ip_address) == 0)
                count++;
            temp = temp->next;
        }

        if (count > max_count) {
            max_count = count;
            max_ip = current->ip_address;
        }
        current = current->next;
    }

    return max_ip;
}

void process(GTPV2_PDU_T* gtpv2_pdu, int num) {
    Node* head = NULL;
    for (int i = 0; i < num; ++i) {
        add_node(&head, gtpv2_pdu[i].ip_address);
    }

    char* frequent_ip = find_frequent_ip(&head);
    if (frequent_ip != NULL) printf("Most frequent IP: %s\n", frequent_ip);

    remove_all(&head);
}
```
