["Here is an example of how you might start implementing this in C, using OpenSSL as the underlying crypto library. This code does not include all the features requested (like integration with KMS or performance optimizations), but it should give you a good starting point. 

```c
#include <openssl/evp.h>
#include <openssl/err.h>
#include <stdio.h>

typedef enum {
    AES_CBC,
    AES_CTR,
    AES_GCM,
    AES_XTS,
    AES_NULL
} aes_mode;

void handleErrors(void)
{
    ERR_print_errors_fp(stderr);
    abort();
}

int encrypt(unsigned char *plaintext, int plaintext_len, unsigned char *key,
            unsigned char *iv, unsigned char *ciphertext, aes_mode mode)
{
    EVP_CIPHER_CTX *ctx;

    int len;

    int ciphertext_len;

    if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();

    switch (mode) {
        case AES_CBC:
            if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) handleErrors();
            break;
        case AES_CTR:
            if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_ctr(), NULL, key, iv)) handleErrors();
            break;
        case AES_GCM:
            if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) handleErrors();
            break;
        case AES_XTS:
            if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_xts(), NULL, key, iv)) handleErrors();
            break;
        case AES_NULL:
            // No encryption
            memcpy(ciphertext, plaintext, plaintext_len);
            return plaintext_len;
    }

    if(1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) handleErrors();
    ciphertext_len = len;

    if(1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) handleErrors();
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}
```
This is a very basic example and does not include error handling for the KMS or logging. You would need to add those features in a real-world application. Also, this code assumes that you have already retrieved your key from the KMS service and that it's 256 bits long (which is typical for AES).
