        populateFromLocalCache(offsets, keys, records);
    } else {
        // Lock mutex before updating shared data
        pthread_mutex_lock(&lock);

        // Populate from external service
        if (!populateFromExternalService(offsets, keys, records)) {
            return 0;
        }

        // Unlock mutex after updating shared data
        pthread_mutex_unlock(&lock);
    }

    // Compress memory footprint (simple algorithm)
    compressMemoryFootprint(offsets, keys, records, maxSize);

    return 1;
}
```
