    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > max) max = arr[i];
    }
    return max;
}

int populateList(NFAPI_CRC_INDICATION_PDU_T** list, size_t* count, const int* RNTIs, size_t nRNTI) {
