typedef struct {
    NetworkEvent** events;
    size_t count;
    size_t capacity;
} EventManager;

void init(EventManager* manager) {
    manager->events = malloc(sizeof(NetworkEvent*) * 10);
    manager->count = 0;
    manager->capacity = 10;
}

void add_event(EventManager* manager, NetworkEvent* event) {
    if (manager->count == manager->capacity) {
        manager->events = realloc(manager->events, sizeof(NetworkEvent*) * manager->capacity * 2);
        manager->capacity *= 2;
    }
    manager->events[manager->count++] = event;
}

void remove_event(EventManager* manager, long timestamp) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i]->timestamp == timestamp) {
            free(manager->events[i]);
            manager->events[i] = manager->events[--manager->count];
            --i;
        }
    }
}

NetworkEvent* get_event(EventManager* manager, int eventType) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i]->eventType == eventType) {
            return manager->events[i];
        }
    }
    return NULL;
}
