['Here's a basic implementation of what you asked for. This code does not include all the features you requested (like efficient file structure or CLI tool), but it should give you an idea on how to start implementing these features. 

```cpp
#include <iostream>
#include <fstream>
#include <unordered_map>
#include <shared_mutex>
#include <vector>
#include <algorithm>

struct Record {
    int key;
    long offset;
};

class RecordManager {
public:
    void loadRecords(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file");
        }

        // Lock for write operation
        std::unique_lock<std::shared_mutex> lock(_mutex);
        _records.clear();

        Record record;
        while (file.read(reinterpret_cast<char*>(&record), sizeof(Record))) {
            _records[record.key] = record;
        }
    }

    void saveRecords(const std::string& filename) {
        std::ofstream file(filename, std::ios::binary);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file");
        }

        // Lock for read operation
        std::shared_lock<std::shared_mutex> lock(_mutex);
        for (const auto& pair : _records) {
            file.write(reinterpret_cast<const char*>(&pair.second), sizeof(Record));
        }
    }

    Record getRecord(int key) {
        // Lock for read operation
        std::shared_lock<std::shared_mutex> lock(_mutex);
        auto it = _records.find(key);
        if (it != _records.end()) {
            return it->second;
        } else {
            throw std::runtime_error("Record not found");
        }
    }

    void addRecord(const Record& record) {
        // Lock for write operation
        std::unique_lock<std::shared_mutex> lock(_mutex);
        _records[record.key] = record;
    }

    void removeRecord(int key) {
        // Lock for write operation
        std::unique_lock<std::shared_mutex> lock(_mutex);
        auto it = _records.find(key);
        if (it != _records.end()) {
            _records.erase(it);
        } else {
            throw std::runtime_error("Record not found");
        }
    }

    std::vector<Record> getAllRecords() {
        // Lock for read operation
        std::shared_lock<std::shared_mutex> lock(_mutex);

        std::vector<Record> records;
        records.reserve(_records.size());
        for (const auto& pair : _records) {
            records.push_back(pair.second);
        }
        return records;
    }

private:
    std::unordered_map<int, Record> _records;
    mutable std::shared_mutex _mutex;
};
```

For the CLI tool, you can use a simple `switch` statement to handle different commands. Here's an example of how you might implement this:

