            try {
                manager.loadRecords(filename);
                std::cout << "Loaded records from file\n";
            } catch (const std::exception& e) {
                std::cerr << "Failed to load records: " << e.what() << "\n";
            }
        } else if (command == "save") {
            std::string filename;
            std::cin >> filename;
            try {
                manager.saveRecords(filename);
                std::cout << "Saved records to file\n";
            } catch (const std::exception& e) {
                std::cerr << "Failed to save records: " << e.what() << "\n";
            }
        } else if (command == "get") {
            int key;
            std::cin >> key;
            try {
                Record record = manager.getRecord(key);
                std::cout << "Key: " << record.key << ", Offset: " << record.offset << "\n";
            } catch (const std::exception& e) {
                std::cerr << "Failed to get record: " << e.what() << "\n";
            }
        } else if (command == "add") {
            Record record;
            std::cin >> record.key >> record.offset;
            manager.addRecord(record);
            std::cout << "Added record\n";
        } else if (command == "remove") {
            int key;
            std::cin >> key;
            try {
                manager.removeRecord(key);
                std::cout << "Removed record\n";
            } catch (const std::exception& e) {
                std::cerr << "Failed to remove record: " << e.what() << "\n";
            }
        } else if (command == "list") {
            auto records = manager.getAllRecords();
            for (const auto& record : records) {
                std::cout << "Key: " << record.key << ", Offset: " << record.offset << "\n";
            }
        } else if (command == "quit") {
            break;
        } else {
            std::cerr << "Unknown command\n";
        }
    }

    return 0;
}
