    double latitude, longitude;
    char status[20];
} DeviceNode;

typedef struct {
    time_t timestamp;
    int sensorID;
    float value;
} SensorData;

#define MAX_NODES 10000
#define MAX_DATA 50000
DeviceNode* deviceNodes[MAX_NODES];
pthread_mutex_t nodeMutexes[MAX_NODES];
int numAllocatedNodes = 0;

SensorData* sensorData[MAX_DATA];
pthread_mutex_t dataMutexes[MAX_DATA];
int numAllocatedData = 0;

void* customMalloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        // Handle allocation failure, log error etc.
    }
    return ptr;
}

DeviceNode* createDeviceNode(int deviceID, double latitude, double longitude, const char* status) {
    DeviceNode* node = customMalloc(sizeof(DeviceNode));
    if (node == NULL) {
        // Handle allocation failure, log error etc.
        return NULL;
    }

    pthread_mutex_init(&nodeMutexes[numAllocatedNodes], NULL);
    node->deviceID = deviceID;
    node->latitude = latitude;
    node->longitude = longitude;
    strncpy(node->status, status, sizeof(node->status) - 1);
    node->status[sizeof(node->status) - 1] = '\0';

    deviceNodes[numAllocatedNodes++] = node;
    return node;
}

SensorData* createSensorData(time_t timestamp, int sensorID, float value) {
    SensorData* data = customMalloc(sizeof(SensorData));
    if (data == NULL) {
        // Handle allocation failure, log error etc.
        return NULL;
    }

    pthread_mutex_init(&dataMutexes[numAllocatedData], NULL);
    data->timestamp = timestamp;
    data->sensorID = sensorID;
    data->value = value;

    sensorData[numAllocatedData++] = data;
    return data;
}

void updateNodeStatus(DeviceNode* node, const char* status) {
    pthread_mutex_lock(&nodeMutexes[node - deviceNodes]);
    strncpy(node->status, status, sizeof(node->status) - 1);
    node->status[sizeof(node->status) - 1] = '\0';
    pthread_mutex_unlock(&nodeMutexes[node - deviceNodes]);
}

void updateSensorData(SensorData* data, time_t timestamp, float value) {
    pthread_mutex_lock(&dataMutexes[data - sensorData]);
    data->timestamp = timestamp;
    data->value = value;
    pthread_mutex_unlock(&dataMutexes[data - sensorData]);
}
