#include <pthread.h>
#include <glib.h>
#include <time.h>
#include <stdlib.h>
#include <unistd.h>

typedef struct {
    int offset;
    int key;
    char* record;
    GHashTable* metadata;
    pthread_mutex_t lock;
    time_t lastAccessed;
    time_t initTimestamp;
} Element;

GHashTable* table;
pthread_rwlock_t rwLock = PTHREAD_RWLOCK_INITIALIZER;

void* initializeElement(int offset, char* record) {
    Element* element = malloc(sizeof(Element));
    if (element == NULL) return NULL;

    pthread_mutex_init(&element->lock, NULL);
    srand(time(NULL));
    element->key = rand() % 1000000 + 1; // Random number between 1 and 1 million
    element->offset = offset;
    element->record = record;
    element->metadata = g_hash_table_new(g_str_hash, g_str_equal);
    time(&element->lastAccessed);
    time(&element->initTimestamp);

    return element;
}

void* getElement(int offset) {
    pthread_rwlock_rdlock(&rwLock);
    void* element = g_hash_table_lookup(table, &offset);
    if (element != NULL) {
        pthread_mutex_lock(&((Element*)element)->lock);
        time(&((Element*)element)->lastAccessed);
        pthread_mutex_unlock(&((Element*)element)->lock);
    }
    pthread_rwlock_unlock(&rwLock);

    return element;
}

void addElement(int offset, char* record) {
    void* newElement = initializeElement(offset, record);
    if (newElement == NULL) return;

    pthread_rwlock_wrlock(&rwLock);
    g_hash_table_insert(table, &((Element*)newElement)->offset, newElement);
    pthread_rwlock_unlock(&rwLock);
}
```
