#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* payload;
    time_t timestamp;
} DataPacket;

extern void log_info(const char* message);
extern void log_error(const char* message);

DataPacket** initialize_data_packets(size_t num_packets, size_t payload_size) {
    DataPacket** packets = (DataPacket**)malloc(num_packets * sizeof(DataPacket*));
    if (!packets) {
        log_error("Failed to allocate memory for data packets");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    size_t i, successfully_allocated = 0;
    for (i = 0; i < num_packets; ++i) {
        packets[i] = (DataPacket*)malloc(sizeof(DataPacket));

        if (!packets[i]) {
            log_error("Failed to allocate memory for data packet");
            continue;
        }

        packets[i]->payload = (char*)malloc(payload_size);

        if (!packets[i]->payload) {
            log_error("Failed to allocate memory for payload");
            free(packets[i]);
            continue;
        }

        packets[i]->timestamp = time(NULL);
        ++successfully_allocated;
    }

    char message[100];
    sprintf(message, "Successfully allocated %zu data packets", successfully_allocated);
    log_info(message);

    return packets;
}
```

