typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock;

void addElement(NFAPI_CRC_INDICATION_PDU_T element, int N) {
    pthread_mutex_lock(&lock);

    if (head == NULL) {
        head = malloc(sizeof(Node));
        head->data = element;
        head->next = NULL;
    } else {
        Node* current = head;
        int count = 1;

        while (current->next != NULL && count < N) {
            current = current->next;
            count++;
        }

        if (count == N) {
            pthread_mutex_unlock(&lock);
            return;
        }

        Node* newNode = malloc(sizeof(Node));
        newNode->data = element;
        newNode->next = NULL;
        current->next = newNode;
    }

    pthread_mutex_unlock(&lock);
}

void clearList() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    head = NULL;

    pthread_mutex_unlock(&lock);
}
```
This code creates a linked list where each node contains an NFAPI_CRC_INDICATION_PDU_T structure. The addElement function adds a new element to the end of the list, up to a maximum size specified by the user. It uses a mutex for thread safety. The clearList function frees all memory allocated for nodes in the list and sets the head pointer to NULL.
