typedef struct HashTable {
    UserSession** sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable(size_t initialCapacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->sessions = calloc(initialCapacity, sizeof(UserSession*));
    if (table->sessions == NULL) {
        free(table);
        return NULL;
    }

    table->capacity = initialCapacity;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void insertSession(HashTable* table, UserSession* session) {
    pthread_mutex_lock(&table->lock);

    if (table->count == table->capacity) {
        // Resize the hash table and rehash all sessions
    }

    size_t index = hash(session->sessionID, table->capacity);
    while (table->sessions[index] != NULL) {
        if (++index == table->capacity) index = 0;
    }

    table->sessions[index] = session;
    table->count++;

    pthread_mutex_unlock(&table->lock);
}

UserSession* getSession(HashTable* table, int sessionID) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash(sessionID, table->capacity);
    while (table->sessions[index] != NULL && table->sessions[index]->sessionID != sessionID) {
        if (++index == table->capacity) index = 0;
    }

    UserSession* session = table->sessions[index];

    pthread_mutex_unlock(&table->lock);

    return session;
}
```
