#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct item {
    int id;
    char* description;
    int status;
} Item;

typedef struct collection {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    Item** items;
} Collection;

Collection* create_collection(size_t initial_capacity) {
    Collection* col = malloc(sizeof(Collection));
    if (col == NULL) return NULL;

    pthread_mutex_init(&col->lock, NULL);
    col->count = 0;
    col->capacity = initial_capacity;
    col->items = malloc(sizeof(Item*) * col->capacity);
    if (col->items == NULL) {
        free(col);
        return NULL;
    }

    return col;
}

void destroy_collection(Collection* col) {
    for (size_t i = 0; i < col->count; ++i) {
        free(col->items[i]->description);
        free(col->items[i]);
    }

    pthread_mutex_destroy(&col->lock);
    free(col->items);
    free(col);
}

int add_item(Collection* col, int id, const char* description, int status) {
    Item* item = malloc(sizeof(Item));
    if (item == NULL) return -1;

    item->id = id;
    item->description = strdup(description);
    if (item->description == NULL) {
        free(item);
        return -1;
    }

    item->status = status;

    pthread_mutex_lock(&col->lock);

    // Check for duplicate IDs
    for (size_t i = 0; i < col->count; ++i) {
        if (col->items[i]->id == id) {
            free(item->description);
            free(item);
            pthread_mutex_unlock(&col->lock);
            return -1;
        }
    }

    // Resize the array if necessary
    if (col->count == col->capacity) {
        size_t new_capacity = col->capacity * 2;
        Item** new_items = realloc(col->items, sizeof(Item*) * new_capacity);
        if (new_items == NULL) {
            free(item->description);
            free(item);
            pthread_mutex_unlock(&col->lock);
            return -1;
        }

        col->capacity = new_capacity;
        col->items = new_items;
    }

    // Add the item to the array
    col->items[col->count++] = item;

    pthread_mutex_unlock(&col->lock);

    return 0;
}
```
