    arr2 = calloc(len2, sizeof(*arr2));  // initialize to zero
    if (arr2 == NULL) {
        fprintf(stderr, "Memory allocation failed for int array\n");
        free(arr1);
        return;
    }

    *records = calloc(len3, sizeof(**records));  // initialize to zero
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for record array\n");
        free(arr1);
        free(arr2);
        return;
    }

    int *existing_keys = calloc((max - min + 1), sizeof(*existing_keys));  // initialize to zero
    if (existing_keys == NULL) {
        fprintf(stderr, "Memory allocation failed for existing keys array\n");
        free(arr1);
        free(arr2);
        free(*records);
        return;
    }

    // Initialize records with random values within the specified range
    for (size_t i = 0; i < len3; ++i) {
        int key;
        do {
            key = rand() % (max - min + 1) + min;  // generate a random number in the range [min, max]
        } while (existing_keys[key - min]);  // repeat until we get an unused key

        existing_keys[key - min] = 1;  // mark this key as used
        (*records)[i].data = key;
    }

    free(existing_keys);
}
```

