using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

public class DataProcessor
{
    private List<(double timestamp, double value)> data;
    private ReaderWriterLockSlim lock_ = new ReaderWriterLockSlim();

    public DataProcessor(List<(double, double)> initialData)
    {
        if (!initialData.Any() || IsChronological(initialData))
            this.data = initialData;
        else
            throw new ArgumentException("Initial data must be in chronological order");
    }

    public (double, double)? GetDataAtTime(double timestamp)
    {
        lock_.EnterReadLock();
        try
        {
            return this.data.FirstOrDefault(d => d.Item1 == timestamp);
        }
        finally
        {
            lock_.ExitReadLock();
        }
    }

    public List<(double, double)> GetFilteredData(int threshold)
    {
        lock_.EnterReadLock();
        try
        {
            return this.data.Where(d => d.Item2 > threshold).ToList();
        }
        finally
        {
            lock_.ExitReadLock();
        }
    }

    public override string ToString()
    {
        lock_.EnterReadLock();
        try
        {
            return string.Join(", ", this.data);
        }
        finally
        {
            lock_.ExitReadLock();
        }
    }

    public void UpdateData(List<(double, double)> newData)
    {
        if (!IsChronological(newData))
            throw new ArgumentException("New data must be in chronological order");

        lock_.EnterWriteLock();
        try
        {
            this.data = MergeSortedLists(this.data, newData);
        }
        finally
        {
            lock_.ExitWriteLock();
        }
    }

    private bool IsChronological(List<(double timestamp, double value)> data)
    {
        for (int i = 1; i < data.Count; ++i)
        {
            if (data[i - 1].timestamp > data[i].timestamp)
                return false;
        }
        return true;
    }

    private List<(double, double)> MergeSortedLists(List<(double, double)> list1, List<(double, double)> list2)
    {
        // Implement this method to merge two sorted lists.
        throw new NotImplementedException();
    }
}
```
