    strcpy(node->ip_address, ip);
    node->port = port;
    node->status = status;
    node->next = NULL;
    return node;
}

void destroy_node(NetworkNode* node) {
    custom_free(node->ip_address);
    custom_free(node);
}

// Thread-safe linked list operations
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_node(NetworkNode** head, NetworkNode* node) {
    pthread_mutex_lock(&lock);
    if (*head == NULL) {
        *head = node;
    } else {
        NetworkNode* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
    pthread_mutex_unlock(&lock);
}

void remove_node(NetworkNode** head, NetworkNode* node) {
    pthread_mutex_lock(&lock);
    if (*head == NULL) return;
    if (*head == node) {
        *head = node->next;
        destroy_node(node);
    } else {
        NetworkNode* current = *head;
        while (current != NULL && current->next != node) {
            current = current->next;
        }
        if (current != NULL) {
            current->next = node->next;
            destroy_node(node);
        }
    }
    pthread_mutex_unlock(&lock);
}
```
