typedef struct {
    int count;
    int maxSize;
    bool safeMode;
} Status;

typedef struct {
    int value;
    char buffer[256];
    bool statusFlag;
    Status* status;
} Record;

Record* records = NULL;
int recordCount = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addRecord(int value, const char* buffer) {
    pthread_mutex_lock(&mutex);

    if (records == NULL || recordCount >= records->status->maxSize) {
        int newMaxSize = recordCount == 0 ? 1 : recordCount * 2;

        Record* temp = realloc(records, sizeof(Record) * newMaxSize);
        if (temp == NULL) {
            // Handle error: insufficient memory for new records
            pthread_mutex_unlock(&mutex);
            return;
        }

        records = temp;
        records->status->maxSize = newMaxSize;
    }

    Record* record = &records[recordCount++];
    record->value = value;
    strncpy(record->buffer, buffer, sizeof(record->buffer) - 1);
    record->buffer[sizeof(record->buffer) - 1] = '\0'; // Ensure null termination

    pthread_mutex_unlock(&mutex);
}

void activateSafeMode() {
    pthread_mutex_lock(&mutex);

    records->status->safeMode = true;

    pthread_mutex_unlock(&mutex);
}

void cleanupRecords() {
    free(records);
    records = NULL;
    recordCount = 0;
}
```
