class UnionFind {
public:
    UnionFind(int size) : parent_(size), rank_(size, 0) {
        for (int i = 0; i < size; ++i) {
            parent_[i] = i;
        }
    }

    int find(int x) {
        if (parent_[x] != x) {
            parent_[x] = find(parent_[x]);
        }
        return parent_[x];
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (rank_[x] < rank_[y]) {
            parent_[x] = y;
        } else {
            parent_[y] = x;
            if (rank_[x] == rank_[y]) {
                ++rank_[x];
            }
        }
    }

