import java.io.*;

public class CommandExecutor {
    private static final String FILENAME = "output.txt";

    public void executeCommand(String command, String directory) throws IOException, InterruptedException {
        File file = new File(FILENAME);

        // Delete the output file if it exists
        if (file.exists()) {
            if (!file.delete()) {
                throw new IOException("Failed to delete existing output file");
            }
        }

        Process process = Runtime.getRuntime().exec(command, null, new File(directory));

        // Read the output and error streams in separate threads
        Thread stdoutThread = new Thread(() -> readStream(process.getInputStream()));
        Thread stderrThread = new Thread(() -> readStream(process.getErrorStream()));

        stdoutThread.start();
        stderrThread.start();

        // Wait for the command to finish and threads to complete
        int exitCode = process.waitFor();

        stdoutThread.join();
        stderrThread.join();

        if (exitCode != 0) {
            throw new RuntimeException("Command execution failed with exit code " + exitCode);
        }
    }

    private void readStream(InputStream stream) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream))) {
            String line;

            while ((line = reader.readLine()) != null) {
                // Process the output or error line here
                System.out.println(line);
            }
        } catch (IOException e) {
            throw new RuntimeException("Failed to read stream", e);
        }
    }
}
