#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Entry {
    int key;
    float value;
    char* description;
    struct Entry *next;
} Entry;

Entry* create_entry(int key, float value, const char* description) {
    Entry* new_entry = malloc(sizeof(Entry));
    if (new_entry == NULL) {
        printf("Memory allocation failed.\n");
        exit(1);
    }

    new_entry->key = key;
    new_entry->value = value;
    new_entry->description = malloc(strlen(description) + 1);
    if (new_entry->description == NULL) {
        printf("Memory allocation failed.\n");
        exit(1);
    }

    strcpy(new_entry->description, description);
    new_entry->next = NULL;

    return new_entry;
}

void delete_entry(Entry* entry) {
    free(entry->description);
    free(entry);
}

void insert_entry(Entry** head, int key, float value, const char* description) {
    Entry* current = *head;

    while (current != NULL) {
        if (current->key == key) {
            return; // Ignore duplicates
        }

        if (current->next == NULL || current->next->key > key) {
            Entry* new_entry = create_entry(key, value, description);
            new_entry->next = current->next;
            current->next = new_entry;

            return;
        }

        current = current->next;
    }

    Entry* new_entry = create_entry(key, value, description);
    *head = new_entry;
}

void delete_entry_by_key(Entry** head, int key) {
    if (*head == NULL) {
        return; // List is empty
    }

    Entry* current = *head;
    Entry* previous = NULL;

    while (current != NULL && current->key < key) {
        previous = current;
        current = current->next;
    }

    if (current == NULL || current->key > key) {
        return; // Key not found
    }

    if (previous != NULL) {
        previous->next = current->next;
    } else {
        *head = current->next;
    }

    delete_entry(current);
}

void traverse_list(Entry* head) {
    Entry* current = head;

    while (current != NULL) {
        printf("Key: %d, Value: %f, Description: %s\n", 
               current->key, current->value, current->description);

        current = current->next;
    }
}
```
This code provides a basic linked list implementation with insertion and deletion operations. It also handles duplicate keys by storing the first occurrence and linking subsequent duplicates to it. The memory for each entry is managed efficiently, ensuring no leaks or fragmentation. 

