    int index = hashFunction(session->sessionID);
    while (index < ht->size && ht->table[index] != NULL) {
        if (!strcmp(ht->table[index]->sessionID, session->sessionID)) {
            // Log failed due to memory allocation issues
            pthread_mutex_unlock(&ht->lock);
            return;
        }

        index = (index + 1) % ht->size;
    }

    ht->table[index] = session;
