['Here is a basic outline of how you might implement this task in C. This code does not include all the features mentioned above due to its complexity and size but it gives an idea about how you can start implementing such a system. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct TaskNode {
    int priority;
    char *description;
    time_t deadline;
    int status;
    struct TaskNode *next;
} TaskNode;

TaskNode* createTask(int priority, const char *description, time_t deadline, int status) {
    TaskNode *newTask = (TaskNode*) malloc(sizeof(TaskNode));
    newTask->priority = priority;
    newTask->description = strdup(description);
    newTask->deadline = deadline;
    newTask->status = status;
    newTask->next = NULL;
    return newTask;
}

void addTask(TaskNode **head, TaskNode *newTask) {
    if (*head == NULL || (*head)->priority < newTask->priority) {
        newTask->next = *head;
        *head = newTask;
    } else {
        TaskNode *current = *head;
        while (current->next != NULL && current->next->priority > newTask->priority) {
            current = current->next;
        }
        newTask->next = current->next;
        current->next = newTask;
    }
}

void removeExpiredTasks(TaskNode **head) {
    time_t now = time(NULL);
    while (*head != NULL && (*head)->deadline < now) {
        TaskNode *temp = *head;
        *head = (*head)->next;
        free(temp->description);
        free(temp);
    }
}

void updateTaskDeadline(TaskNode **head, const char *description, time_t newDeadline) {
    TaskNode *current = *head;
    while (current != NULL && strcmp(current->description, description) != 0) {
        current = current->next;
    }
    if (current != NULL) {
        current->deadline = newDeadline;
    }
}
```
This code creates a linked list of `TaskNode` structures. Each task has a priority, description, deadline and status. The tasks are sorted by their priority in the list. When adding a new task, it is inserted at the correct position to maintain the order. 

