void generate_data(size_t array_length, size_t max_identifier_length, 
                   double min_double, double max_double, 
                   unsigned long min_ulong, unsigned long max_ulong) {
    srand((unsigned int)time(NULL));

    // Allocate memory for arrays
    double* double_array = malloc(sizeof(double) * array_length);
    unsigned long* ulong_array = calloc(array_length, sizeof(unsigned long));
    data_entry* entry_array = malloc(sizeof(data_entry) * array_length);

    // Populate arrays with random values
    for (size_t i = 0; i < array_length; ++i) {
        double_array[i] = min_double + ((double)rand() / RAND_MAX) * (max_double - min_double);

        unsigned long ulong_value;
        do {
            ulong_value = rand() % (max_ulong - min_ulong + 1) + min_ulong;
        } while(memchr(ulong_array, &ulong_value, i * sizeof(unsigned long)));

        char* identifier = malloc(sizeof(char) * max_identifier_length);
        snprintf(identifier, max_identifier_length, "ID%zu", ulong_value);

        entry_array[i].value = double_array[i];
        entry_array[i].identifier = identifier;
    }

    // Free memory upon function exit
    free(double_array);
    free(ulong_array);
    for (size_t i = 0; i < array_length; ++i) {
        free(entry_array[i].identifier);
    }
    free(entry_array);
}
