```javascript
function generateFooter(scripts) {
    const footer = document.createElement('footer');
    let scriptQueue = [];

    scripts.forEach((scriptObj) => {
        if (scriptObj && scriptObj.key && scriptObj.type === 'text/javascript') {
            // Validate src attribute if present
            if (scriptObj.src && !isLocalResource(scriptObj.src)) {
                console.error('Invalid source URL:', scriptObj.src);
                return;
            }

            const script = document.createElement('script');
            script.type = 'text/javascript';
            if (scriptObj.src) script.src = scriptObj.src;
            if (scriptObj.async) script.async = true;
            if (scriptObj.defer) script.defer = true;

            // Add script to queue for later execution
            scriptQueue.push(script);
        } else {
            console.error('Invalid script object:', scriptObj);
        }
    });

    // Execute scripts in order of their appearance in the array
    scriptQueue.forEach((script) => footer.appendChild(script));

    return footer;
}

function isLocalResource(url) {
    const anchor = document.createElement('a');
    anchor.href = url;
    return anchor.hostname === window.location.hostname;
}
```
This function creates a `footer` element and appends script elements to it based on the provided array of script objects. It validates each script object for required properties, checks if its source URL points to a local resource, and handles errors gracefully. 

