Record *head = NULL;
int totalRecords = 0;

void* initializeRecord(void* arg) {
    int minSize, maxSize, minValue, maxValue;
    sscanf((char*)arg, "%d %d %d %d", &minSize, &maxSize, &minValue, &maxValue);

    Record *record = malloc(sizeof(Record));
    assert(record != NULL);

    record->bufferSize = minSize + rand() % (maxSize - minSize + 1);
    record->buffer = malloc(record->bufferSize);
    assert(record->buffer != NULL);

    for(size_t i = 0; i < record->bufferSize; ++i) {
        record->buffer[i] = 'a' + rand() % 26;
    }

    record->value = minValue + rand() % (maxValue - minValue + 1);
    record->precision = 1.0 * rand() / RAND_MAX;

    pthread_mutex_lock(&lock);
    record->next = head;
    head = record;
    ++totalRecords;
    pthread_mutex_unlock(&lock);

    return NULL;
}

void initializeRecords(int numThreads, int minSize, int maxSize, int minValue, int maxValue) {
    srand(time(NULL));

    char arg[100];
    sprintf(arg, "%d %d %d %d", minSize, maxSize, minValue, maxValue);

    pthread_t threads[numThreads];
    for(int i = 0; i < numThreads; ++i) {
        if(pthread_create(&threads[i], NULL, initializeRecord, arg)) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    for(int i = 0; i < numThreads; ++i) {
        if(pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            return;
        }
    }
}
