void removeConnection(int id) {
    pthread_mutex_lock(&lock);

    for(int i = 0; i < connectionCount; ++i) {
        if(connections[i].id == id) {
            // shift all elements after the removed element one position to the left
            for(int j = i; j < connectionCount - 1; ++j) {
                connections[j] = connections[j + 1];
            }

            // decrease count and reallocate memory
            connections = (Connection*)realloc(connections, --connectionCount * sizeof(Connection));
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}
