typedef struct NFAPI_CRC_INDICATION_PDU_T {
    atomic_uint_fast64_t timestamp;
    pthread_mutex_t lock;
    // other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t listLock = PTHREAD_MUTEX_INITIALIZER;

void insert(NFAPI_CRC_INDICATION_PDU_T *data) {
    Node *newNode = malloc(sizeof(Node));
    newNode->data = data;

    pthread_mutex_lock(&listLock);
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&listLock);
}

void updateTimestamp(NFAPI_CRC_INDICATION_PDU_T *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    atomic_store_explicit(&data->timestamp, (uint_fast64_t)(ts.tv_sec * 1000000000L + ts.tv_nsec), memory_order_relaxed);
}
```
This code uses a simple linked list with a global lock for synchronization. Each node in the list contains a mutex that can be used to protect the data it holds from concurrent access by multiple threads. The `insert` function acquires the global lock, creates a new node and adds it at the head of the list before releasing the lock.

The `updateTimestamp` function uses atomic operations to update the timestamp field in the structure. This ensures that the operation is performed atomically and cannot be interrupted by other threads. 

