long* allocateOffsets(int max_offset) {
    long *offsets = malloc(max_offset * sizeof(*offsets));
    if (offsets == NULL) exit(1); // handle error

    for (int i = 0; i < max_offset; ++i) {
        offsets[i] = i;
    }

    return offsets;
}

int* allocateKeys(int max_keys) {
    int *keys = malloc(max_keys * sizeof(*keys));
    if (keys == NULL) exit(1); // handle error

    for (int i = 0; i < max_keys; ++i) {
        keys[i] = i;
    }

    return keys;
}

record* allocateRecords(int max_value, int count) {
    srand(time(NULL)); // seed the random number generator
    record *records = malloc(count * sizeof(*records));
    if (records == NULL) exit(1); // handle error

    for (int i = 0; i < count; ++i) {
        records[i].value = rand() % max_value;
    }

    return records;
}

size_t manageArraysAndStructures(long **offsets, int **keys, record ***records, 
                                int max_offset, int max_keys, int max_value) {
    pthread_mutex_lock(&lock); // lock for thread safety

    *offsets = allocateOffsets(max_offset);
    *keys = allocateKeys(max_keys);
    *records = allocateRecords(max_value, max_keys);

    size_t totalSize = 0;
    if (max_offset > 0) {
        totalSize += max_offset * sizeof(**offsets);
    }
    if (max_keys > 0) {
        totalSize += max_keys * sizeof(**keys);
    }
    if (max_value > 0 && max_keys > 0) {
        totalSize += max_keys * sizeof(***records);
    }

    pthread_mutex_unlock(&lock); // unlock after allocation

    return totalSize;
}
