['Here is a basic implementation of your requirements using Node.js with JavaScript. This code uses Cheerio to parse HTML, URL module to handle URLs, and LRU-Cache to implement caching. 

```javascript
const cheerio = require('cheerio');
const url = require('url');
const LRU = require('lru-cache');
let cache = new LRU({ max: 50 }); // Adjust the size according to your needs

function processDocument(html, options) {
    let documentHash = hashCode(html);
    if (cache.has(documentHash)) return cache.get(documentHash);

    const $ = cheerio.load(html);
    let links = $('a');
    let result = {};

    for (let i = 0; i < links.length; i++) {
        let href = $(links[i]).attr('href');

        if (!href || href.startsWith('#')) continue; // Ignore internal links and empty hrefs

        try {
            let parsedUrl = url.parse(href);

            if (parsedUrl.host && parsedUrl.host !== options.domain) { // External link
                if (!result[parsedUrl.host]) result[parsedUrl.host] = [];

                if (options.filterContentTypes && options.contentTypesToFilter.includes(parsedUrl.pathname.split('.').pop())) continue; // Filter out links based on content types

                result[parsedUrl.host].push(parsedUrl.pathname);
            }
        } catch (err) {
            console.error("Error parsing URL: ", href, err);
        }
    }

    cache.set(documentHash, result); // Cache the result
    return result;
}

function hashCode(str){
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
       hash = Math.imul(31, hash) + str.charCodeAt(i) | 0;
    }
    return hash.toString();
}
```

This function takes an HTML string and options as input. The options object can contain a domain property for the document's hostname, a filterContentTypes boolean to enable content type filtering, and a contentTypesToFilter array with the types of links to ignore. 

Please note that this is a basic implementation and may need further optimization based on your specific use case. For example, you might want to add error handling for cases where URL parsing fails or when the HTML string is not well-formed. Also, consider using a more efficient caching strategy if performance becomes an issue with large documents or high throughput.
']

