    int frameStructure;
    int subcarrierSpacing;
    pthread_mutex_t lock;
} MACConfig;

MACConfig* macConfigs[100]; // assuming a maximum of 100 MAC entities for simplicity
int macCount = 0;
pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;

void addMacEntity(int id, int frameStructure, int subcarrierSpacing) {
    pthread_mutex_lock(&globalLock);

    MACConfig* newConfig = (MACConfig*)malloc(sizeof(MACConfig));
    newConfig->id = id;
    newConfig->frameStructure = frameStructure;
    newConfig->subcarrierSpacing = subcarrierSpacing;
    pthread_mutex_init(&newConfig->lock, NULL);

    macConfigs[macCount++] = newConfig;

    pthread_mutex_unlock(&globalLock);
}

void addL2Entity(int macId, int l2Id) {
    for (int i = 0; i < macCount; ++i) {
        if (macConfigs[i]->id == macId) {
            pthread_mutex_lock(&macConfigs[i]->lock);

            L2Entity* newL2 = (L2Entity*)malloc(sizeof(L2Entity));
            newL2->id = l2Id;

            macConfigs[i]->l2Entities = realloc(macConfigs[i]->l2Entities, sizeof(L2Entity*) * (i + 1));
            macConfigs[i]->l2Entities[i] = newL2;

            pthread_mutex_unlock(&macConfigs[i]->lock);
        }
    }
}

void removeMacEntity(int id) {
    pthread_mutex_lock(&globalLock);

    for (int i = 0; i < macCount; ++i) {
        if (macConfigs[i]->id == id) {
            free(macConfigs[i]);

            // shift all elements after the removed one to fill the gap
            for (int j = i; j < macCount - 1; ++j) {
                macConfigs[j] = macConfigs[j + 1];
            }

            --macCount;
        }
    }

    pthread_mutex_unlock(&globalLock);
}

void removeL2Entity(int macId, int l2Id) {
    for (int i = 0; i < macCount; ++i) {
        if (macConfigs[i]->id == macId) {
            pthread_mutex_lock(&macConfigs[i]->lock);

            // find and remove the L2 entity with the given id
            for (int j = 0; j < sizeof(macConfigs[i]->l2Entities) / sizeof(L2Entity*); ++j) {
                if (macConfigs[i]->l2Entities[j]->id == l2Id) {
                    free(macConfigs[i]->l2Entities[j]);

                    // shift all elements after the removed one to fill the gap
                    for (int k = j; k < sizeof(macConfigs[i]->l2Entities) / sizeof(L2Entity*) - 1; ++k) {
                        macConfigs[i]->l2Entities[k] = macConfigs[i]->l2Entities[k + 1];
                    }
                }
            }

            pthread_mutex_unlock(&macConfigs[i]->lock);
        }
    }
}
```
