unsigned char* calculateMD5Hash(const char *filename, unsigned long *hashLength) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL; // Handle file opening failure
    }

    MD5_CTX mdContext;
    MD5_Init(&mdContext);

    int bytes;
    unsigned char data[1024];
    while ((bytes = fread(data, 1, 1024, file)) != 0) {
        MD5_Update(&mdContext, data, bytes);
    }

    unsigned char *hash = malloc(MD5_DIGEST_LENGTH);
    if (hash == NULL) {
        return NULL; // Handle memory allocation failure
    }

    MD5_Final(hash, &mdContext);
    fclose(file);

    *hashLength = MD5_DIGEST_LENGTH;
    return hash;
}
```
