SystemData* initializeSystem(size_t timestampSize, size_t tagSize, size_t eventSize, double* timestamps, char** tags) {
    srand((unsigned int)time(NULL));

    if (timestampSize * sizeof(double) + tagSize * sizeof(char*) + eventSize * sizeof(Event*) > availableMemory()) {
        printf("Requested system size exceeds available memory. Truncating request.\n");
        // Adjust sizes to fit within available memory
        timestampSize = availableMemory() / (sizeof(double) + sizeof(char*) + sizeof(Event*));
    }

    SystemData* data = malloc(sizeof(SystemData));
    if (!data) {
        printf("Failed to allocate memory for system data.\n");
        return NULL;
    }

    data->timestamps = calloc(timestampSize, sizeof(double));
    data->tags = malloc(tagSize * sizeof(char*));
    data->events = malloc(eventSize * sizeof(Event*));
    data->eventCounts = calloc(1, sizeof(int));

    if (!data->timestamps || !data->tags || !data->events || !data->eventCounts) {
        printf("Failed to allocate memory for system components.\n");
        freeSystemData(data);
        return NULL;
    }

    memcpy(data->timestamps, timestamps, timestampSize * sizeof(double));
    memcpy(data->tags, tags, tagSize * sizeof(char*));

    for (size_t i = 0; i < eventSize; ++i) {
        data->events[i] = malloc(sizeof(Event));

        if (!data->events[i]) {
            printf("Failed to allocate memory for an event.\n");
            freeSystemData(data);
            return NULL;
        }

        data->events[i]->description = malloc(7 * sizeof(char)); // "INFO" + null terminator

        if (!data->events[i]->description) {
            printf("Failed to allocate memory for an event description.\n");
            freeSystemData(data);
            return NULL;
        }

        strcpy(data->events[i]->description, "INFO");
        data->events[i]->duration = (rand() % 1000) + ((double)(rand() % 1000) / 1000.0); // Random duration in seconds
    }

    *(data->eventCounts) = eventSize;
    data->totalEvents = eventSize;

    return data;
}

void freeSystemData(SystemData* data) {
    if (data) {
        for (size_t i = 0; i < *(data->eventCounts); ++i) {
            free(data->events[i]->description);
            free(data->events[i]);
        }

        free(data->timestamps);
        free(data->tags);
        free(data->events);
        free(data->eventCounts);
        free(data);
    }
}
