```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <string.h>
#include <sys/resource.h>

typedef struct {
    time_t start;
    time_t end;
} Timer;

typedef struct {
    int priority;
    char* message;
    Timer timer;
} Task;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void logError(const char* msg) {
    // Implement structured logging here.
}

Task* createTask(int priority, const char* message) {
    Task* task = malloc(sizeof(Task));
    if (task == NULL) {
        logError("Failed to allocate memory for a new task.");
        return NULL;
    }

    task->priority = priority;
    task->message = strdup(message);
    if (task->message == NULL) {
        logError("Failed to duplicate message string.");
        free(task);
        return NULL;
    }

    time(&task->timer.start);
    task->timer.end = -1; // Not finished yet.

    return task;
}

void* initializeTask(void* arg) {
    int priority = rand() % 10 + 1; // Random priority between 1 and 10.
    const char* messages[] = {"Message 1", "Message 2", "Message 3"}; // Predefined messages.

    pthread_mutex_lock(&lock);
    Task* task = createTask(priority, messages[rand() % 3]); // Random message from the list.
    pthread_mutex_unlock(&lock);

    if (task == NULL) {
        logError("Failed to initialize a new task.");
    }

    return task;
}

Task** createTasks(size_t count) {
    Task** tasks = malloc(count * sizeof(Task*));
    if (tasks == NULL) {
        logError("Failed to allocate memory for the tasks array.");
        return NULL;
    }

    pthread_t threads[count];
    for (size_t i = 0; i < count; ++i) {
        int result = pthread_create(&threads[i], NULL, initializeTask, NULL);
        if (result != 0) {
            logError("Failed to create a new thread.");
            // Clean up previously allocated tasks.
            for (size_t j = 0; j < i; ++j) {
                free(tasks[j]->message);
                free(tasks[j]);
            }
            free(tasks);
            return NULL;
        }
    }

    // Wait for all threads to finish.
    for (size_t i = 0; i < count; ++i) {
        pthread_join(threads[i], &tasks[i]);
