int initializeAndSecureData(unsigned char *seed, size_t arraySize, const char *config) {
    // Initialize OpenSSL's cryptographic library
    OpenSSL_add_all_algorithms();

    // Allocate memory for arrays and structures
    long *offsetValues = malloc(sizeof(long) * arraySize);
    int *keys = malloc(sizeof(int) * arraySize);
    record *records = malloc(sizeof(record) * arraySize);

