        keys[i] = RAND_get0_positive();
        records[i].value = RAND_get0_positive();
    }

    // Parse the configuration string to determine which cryptographic algorithms to use
    char *token = strtok(config, ",");
    while (token != NULL) {
        if (strcmp(token, "AES") == 0) {
            EVP_add_cipher(EVP_aes_256_cbc());
        } else if (strcmp(token, "Camellia") == 0) {
