                int key = rand() % (int)(sizeof charset - 1);
                randomString[n] = charset[key];
            }
            randomString[length] = '\0';
        }
    }

    return randomString;
}

void findLongestStrings(NFAPI_STRING_PROCESSING_PDU_T* strings, int count) {
    size_t maxLength = 0;
    for (int i = 0; i < count; ++i) {
        size_t length = strlen(strings[i].string_indication);
        if (length > maxLength) {
            maxLength = length;
        }
    }

    printf("Longest strings:\n");
    for (int i = 0; i < count; ++i) {
        size_t length = strlen(strings[i].string_indication);
        if (length == maxLength) {
            printf("%s at index %d\n", strings[i].string_indication, i);
        }
    }
}

int process_nfaapi_and_strings() {
    srand((unsigned int) time(NULL));

    char buffer[51];
    char* strings[50] = { 0 };
    int count = 0;

    while (count < 50 && fgets(buffer, sizeof buffer, stdin)) {
        buffer[strcspn(buffer, "\n")] = 0; // Remove trailing newline

        for (int i = 0; i < count; ++i) {
            if (strcmp(strings[i], buffer) == 0) {
                fprintf(stderr, "Duplicate string detected: %s\n", buffer);
                return 1; // Duplicate string error code
            }
        }

        strings[count] = strdup(buffer);
        if (strings[count] == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            return 2; // Memory allocation failure error code
        }
        ++count;
    }

    if (count < 5 || count > 50) {
        fprintf(stderr, "Invalid number of strings: %d\n", count);
        return 3; // Invalid string count error code
    }

    NFAPI_STRING_PROCESSING_PDU_T* pdu = calloc(count, sizeof *pdu);
    if (pdu == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 2; // Memory allocation failure error code
    }

    for (int i = 0; i < count; ++i) {
        pdu[i].rx_cell_information = generateRandomString(1 + rand() % 10);
        pdu[i].string_indication = strings[i];
    }

    findLongestStrings(pdu, count);

    for (int i = 0; i < count; ++i) {
        free(strings[i]);
        free(pdu[i].rx_cell_information);
    }
    free(pdu);

    return 0; // Success code
}
```
