    int port;
    char* authKey;
} NetworkConfig;

// Global variables for managing the queue and cache
NetworkConfig** configQueue = NULL;
int queueSize = 0;
int maxQueueSize = 100; // You can adjust this based on your needs

pthread_mutex_t lock;

void* configureNetworkSettings(void *arg) {
    NetworkConfig* config = (NetworkConfig*) arg;

    if (!config || !config->ip || config->port < 0 || !config->authKey) {
        printf("Invalid configuration. Skipping...\n");
        return NULL;
    }

    // Allocate memory for the new config
    NetworkConfig* newConfig = (NetworkConfig*) malloc(sizeof(NetworkConfig));
    if (!newConfig) {
        printf("Failed to allocate memory. Skipping...\n");
        return NULL;
    }

    // Copy data from the input config to the new one
    newConfig->ip = strdup(config->ip);
    newConfig->port = config->port;
    newConfig->authKey = strdup(config->authKey);

    if (!newConfig->ip || !newConfig->authKey) {
        printf("Failed to copy data. Skipping...\n");
        free(newConfig->ip);
        free(newConfig->authKey);
        free(newConfig);
        return NULL;
    }

    // Add the new config to the queue
    pthread_mutex_lock(&lock);
    if (queueSize < maxQueueSize) {
        configQueue[queueSize++] = newConfig;
    } else {
        printf("Maximum queue size reached. Skipping...\n");
        free(newConfig->ip);
        free(newConfig->authKey);
        free(newConfig);
    }
    pthread_mutex_unlock(&lock);

    return NULL;
}
```
