#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    int value;
    char buffer[1024];
    bool flag;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    char** logs;
    bool** flags;
    size_t count;
    size_t maxSize;
    bool safeMode;
    size_t totalAttempts;
} status;

status* initStatus(size_t initialSize) {
    status* s = malloc(sizeof(status));
    if (s == NULL) return NULL;

    s->offsets = calloc(initialSize, sizeof(long));
    s->keys = calloc(initialSize, sizeof(int));
    s->records = calloc(initialSize, sizeof(record*));
    s->logs = calloc(initialSize, sizeof(char*));
    s->flags = calloc(initialSize, sizeof(bool));

    if (s->offsets == NULL || s->keys == NULL || s->records == NULL || 
        s->logs == NULL || s->flags == NULL) {
        freeStatus(s);
        return NULL;
    }

    s->count = 0;
    s->maxSize = initialSize;
    s->safeMode = false;
    s->totalAttempts = 0;

    return s;
}

void freeStatus(status* s) {
    if (s == NULL) return;

    for (size_t i = 0; i < s->count; ++i) {
        free(s->records[i]);
        free(s->logs[i]);
    }

    free(s->offsets);
    free(s->keys);
    free(s->records);
    free(s->logs);
    free(s->flags);
    free(s);
}
```
