typedef struct {
    int value;
    double decimal;
    char buffer[1024];
} Record;

void* initializeRecord(void *arg) {
    srand((unsigned int) time(NULL)); // seed the random number generator

    Record *record = (Record*) arg;
    record->value = rand() % 100 + 1; // generate a random value between 1 and 100
    record->decimal = ((double)rand() / (double)(RAND_MAX)) * 10.0; // generate a random double between 0 and 10

    return NULL;
}

Record* allocateAndInitializeRecords(size_t size) {
    Record *records = malloc(sizeof(Record) * size);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return NULL;
    }

    pthread_t threads[size];
    for (size_t i = 0; i < size; ++i) {
        if (pthread_create(&threads[i], NULL, initializeRecord, &records[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            // clean up allocated memory
            for (size_t j = 0; j < i; ++j) {
                pthread_join(threads[j], NULL);
            }
            free(records);
            return NULL;
        }
    }

    for (size_t i = 0; i < size; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Failed to join thread\n");
        }
    }

    return records;
}
