std::mutex mtx; // mutex for thread safety

void updateAndInsertInDistributedList(int nodeId, std::string sessionToken, 
                                      std::forward_list<std::string>& list, 
                                      const std::string& target, const std::string& toInsert) {
    std::lock_guard<std::mutex> lock(mtx); // acquire the lock

    auto it = find(list.begin(), list.end(), target);
    if (it != list.end()) {
        list.insert_after(it, toInsert);
    } else {
        list.push_front(toInsert);
    }
}
