void packet_manager_init(PacketManager* manager, size_t initial_capacity) {
    manager->packets = g_array_new(FALSE, FALSE, sizeof(DataPacket));
    manager->packets->data = g_malloc(initial_capacity * sizeof(DataPacket));
    manager->packets->len = 0;
    manager->packets->allocated_len = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void packet_manager_add(PacketManager* manager, DataPacket packet) {
    pthread_mutex_lock(&manager->lock);

    if (manager->packets->len == manager->packets->allocated_len) {
        size_t new_capacity = manager->packets->allocated_len * 2;
        DataPacket* new_data = g_realloc(manager->packets->data, new_capacity * sizeof(DataPacket));

        if (new_data == NULL) {
            printf("Failed to expand array\n");
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        manager->packets->data = new_data;
        manager->packets->allocated_len = new_capacity;
    }

    g_array_append_val(manager->packets, packet);

    pthread_mutex_unlock(&manager->lock);
}

void packet_manager_iterate(PacketManager* manager, void (*operation)(DataPacket)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->packets->len; ++i) {
        operation(g_array_index(manager->packets, DataPacket, i));
    }

    pthread_mutex_unlock(&manager->lock);
}
