```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    int value;
    char *str;
} Record;

typedef struct Node {
    Record record;
    struct Node *next;
} Node;

Node* create_node(int value, const char *str) {
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    new_node->record.value = value;
    new_node->record.str = strdup(str);
    new_node->next = NULL;

    return new_node;
}

void insert_node(Node **head, int value, const char *str) {
    Node *new_node = create_node(value, str);
    if (new_node == NULL) {
        return;
    }

    new_node->next = *head;
    *head = new_node;
}

void delete_node(Node **head, int value) {
    Node *temp = *head;
    Node *prev = NULL;

    if (temp != NULL && temp->record.value == value) {
        *head = temp->next;
        free(temp);
        return;
    }

    while (temp != NULL && temp->record.value != value) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) {
        printf("Record not found.\n");
        return;
    }

    prev->next = temp->next;
    free(temp);
}

void serialize_to_file(Node *head, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        printf("Failed to open file for writing.\n");
        return;
    }

    Node *temp = head;
    while (temp != NULL) {
        fwrite(&temp->record.value, sizeof(int), 1, fp);
        size_t len = strlen(temp->record.str);
        fwrite(&len, sizeof(size_t), 1, fp);
        fwrite(temp->record.str, sizeof(char), len, fp);

        temp = temp->next;
    }

    fclose(fp);
}

Node* deserialize_from_file(const char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Failed to open file for reading.\n");
        return NULL;
    }

    Node *head = NULL;
    while (!feof(fp)) {
        int value;
        size_t len;

        fread(&value, sizeof(int), 1, fp);
        fread(&len, sizeof(size_t), 1, fp);

        char *str = malloc(len + 1);
        if (str == NULL) {
            printf("Memory allocation failed.\n");
            break;
        }

        fread(str, sizeof(char), len, fp);
        str[len] = '\0';

        insert_node(&head, value, str);
    }

    fclose(fp);
    return head;
}
```
