#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct NetworkNode {
    char* ip;
    int port;
    atomic_int status; // 0: available, 1: unavailable
    void* metadata;
    size_t metadataSize;
    pthread_mutex_t lock;
    struct NetworkNode* next;
} NetworkNode;

typedef struct LinkedList {
    NetworkNode* head;
    atomic_size_t count;
    pthread_mutex_t lock; // for thread-safe operations
} LinkedList;

LinkedList* createList() {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (list == NULL) return NULL;

    list->head = NULL;
    atomic_init(&list->count, 0);
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroyList(LinkedList* list) {
    NetworkNode* node = list->head;
    while (node != NULL) {
        NetworkNode* next = node->next;

        pthread_mutex_destroy(&node->lock);
        free(node->ip);
        free(node->metadata);
        free(node);

        node = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

NetworkNode* createNode(const char* ip, int port, void* metadata, size_t metadataSize) {
    NetworkNode* node = malloc(sizeof(NetworkNode));
    if (node == NULL) return NULL;

    node->ip = strdup(ip);
    node->port = port;
    atomic_init(&node->status, 0);
    node->metadata = metadata;
    node->metadataSize = metadataSize;
    pthread_mutex_init(&node->lock, NULL);

    return node;
}

void addNode(LinkedList* list, NetworkNode* node) {
    pthread_mutex_lock(&list->lock);

    node->next = list->head;
    list->head = node;
    atomic_fetch_add(&list->count, 1);

    pthread_mutex_unlock(&list->lock);
}

void removeNode(LinkedList* list, NetworkNode* node) {
    pthread_mutex_lock(&list->lock);

    if (list->head == node) {
        list->head = node->next;
        atomic_fetch_sub(&list->count, 1);
    } else {
        NetworkNode* prev = list->head;
        while (prev != NULL && prev->next != node) {
            prev = prev->next;
        }

        if (prev != NULL) {
            prev->next = node->next;
            atomic_fetch_sub(&list->count, 1);
        }
    }

    pthread_mutex_unlock(&list->lock);
}
```
