#include <sys/wait.h>
#include <string.h>

typedef struct {
    char* payload;
    time_t timestamp;
    int id;
} Task;

void* worker(void *arg) {
    Task *task = (Task*) arg;

    // Set environment variables and check/delete temp file here...

    FILE *fpOut, *fpErr;
    char path[1035];

    /* Open the command for execution.  */
    fpOut = popen(task->payload, "r");
    fpErr = popen(task->payload, "r");

    if (fpOut == NULL || fpErr == NULL) {
        printf("Failed to run command\n" );
        exit(1);
    }

    /* Read the output a line at a time - output it. */
    while (fgets(path, sizeof(path)-1, fpOut) != NULL) {
        printf("%s", path);
    }

    // Logging here...

    /* close */
    pclose(fpOut);
    pclose(fpErr);

    free(task->payload);
    free(task);
}

void executeWorkload(Task **tasks, int taskCount) {
    pthread_t threads[taskCount];
    for (int i = 0; i < taskCount; ++i) {
        if (pthread_create(&threads[i], NULL, worker, tasks[i])) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    for (int i = 0; i < taskCount; ++i) {
        if (pthread_join(threads[i], NULL)) {
            printf("Error joining thread\n");
            return;
        }
    }
}
