    int severity_level;
    time_t timestamp;
} LogEntry;

typedef struct LogList {
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    LogEntry** entries;
} LogList;

LogList* create_loglist(size_t initial_capacity) {
    LogList* list = malloc(sizeof(LogList));
    if (list == NULL) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->capacity = initial_capacity;
    list->entries = malloc(sizeof(LogEntry*) * initial_capacity);
    if (list->entries == NULL) {
        free(list);
        return NULL;
    }

    return list;
}

void destroy_loglist(LogList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->entries[i]->message);
        free(list->entries[i]);
    }

    pthread_mutex_destroy(&list->lock);
    free(list->entries);
    free(list);
}

int add_logentry(LogList* list, LogEntry* entry) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        void* new_entries = realloc(list->entries, sizeof(LogEntry*) * new_capacity);
        if (new_entries == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1;  // Allocation failure.
        }

        list->entries = new_entries;
        list->capacity = new_capacity;
    }

    list->entries[list->count++] = entry;

    pthread_mutex_unlock(&list->lock);
    return 0;  // Success.
}
```
This code creates a dynamic list of `LogEntry` structures, with thread safety and efficient memory allocation. It uses a mutex to ensure that only one thread can modify the list at a time, avoiding race conditions. The function for adding an entry checks if there is enough space in the list before attempting to add it, dynamically allocating more space if necessary.
