    printf("Successfully allocated %d sessions\n", numSessions);
    return sessions;
}

char* getClientAddressWithRetries() {
    int maxAttempts = 5;
    for (int attempt = 1; attempt <= maxAttempts; ++attempt) {
        char* clientAddress = resolveClientAddress(); // Assume this function exists and returns NULL on failure

        if (clientAddress != NULL) {
            return clientAddress;
        } else {
            printf("Failed to resolve client address. Attempt %d of %d\n", attempt, maxAttempts);

            // Exponential backoff with jitter
            int sleepTime = pow(2, attempt) * 1000 + rand() % 1000;
            usleep(sleepTime);
        }
    }

    return NULL;
}
