["Here's an example of how you might implement such a function in C using pthread mutexes for synchronization and error handling. This code is simplified and does not include all the features mentioned, but it should give you a good starting point. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
    char* string;
} record;

typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t count;
    record** records;
} memory_pool;

memory_pool pool = { .capacity = 0, .count = 0, .records = NULL };
pthread_once_t init_mutex = PTHREAD_ONCE_INIT;

void init_mutex_callback(void) {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&pool.mutex, &attr);
}

record* allocate_record(int value, const char* string) {
    record* rec = malloc(sizeof(record));
    if (rec == NULL) return NULL;

    rec->value = value;
    rec->string = malloc(strlen(string) + 1);
    if (rec->string == NULL) {
        free(rec);
        return NULL;
    }

    strcpy(rec->string, string);
    return rec;
}

void deallocate_record(record* rec) {
    free(rec->string);
    free(rec);
}

int add_to_pool(record* rec) {
    pthread_once(&init_mutex, init_mutex_callback);

    pthread_mutex_lock(&pool.mutex);

    if (pool.count == pool.capacity) {
        size_t new_capacity = pool.capacity == 0 ? 1 : pool.capacity * 2;
        record** new_records = realloc(pool.records, sizeof(record*) * new_capacity);

        if (new_records == NULL) {
            pthread_mutex_unlock(&pool.mutex);
            return -1;
        }

        pool.records = new_records;
        pool.capacity = new_capacity;
    }

    pool.records[pool.count++] = rec;

    pthread_mutex_unlock(&pool.mutex);

    return 0;
}
```
This code provides a simple memory pool that grows dynamically as needed, and uses mutexes to ensure thread safety. It also includes error handling for failed allocations. However, it does not include the features mentioned in your requirements such as resetting the memory pool when the application restarts or logging memory usage statistics.
