#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *data;
} List;

List* createList(size_t initialCapacity, size_t maxSize) {
    List *list = malloc(sizeof(List));
    if (list == NULL) return NULL;

    list->capacity = initialCapacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (list->data == NULL) {
        free(list);
        return NULL;
    }

    return list;
}

void destroyList(List *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
    free(list);
}

int addElement(List *list, NFAPI_CRC_INDICATION_PDU_T element, size_t maxSize) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == element.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate RNTI found
        }
    }

    if (list->size >= maxSize) {
        pthread_mutex_unlock(&list->lock);
        return 0; // List is full
    }

    if (list->size == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (newData == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Reallocation failed
        }

        list->capacity = newCapacity;
        list->data = newData;
    }

    list->data[list->size++] = element;

    pthread_mutex_unlock(&list->lock);
    return 1; // Element added successfully
}
```
This code creates a thread-safe dynamic list that can be used to store NFAPI_CRC_INDICATION_PDU_T structures. It checks for duplicate RNTI values and ensures the total number of elements does not exceed a specified maximum size, truncating the list if necessary. The function is optimized for performance by minimizing allocations and ensuring efficient memory usage.
']

