['Here is a basic implementation of your requirements in C. This code does not include all the features you requested such as integration with external systems or detailed logging mechanism but it provides a good starting point. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char *name;
    double distance_from_source;
    int visited;
    struct Node **adjacent_nodes;
    int adjacent_node_count;
} Node;

Node* create_node(char *name) {
    Node *new_node = malloc(sizeof(Node));
    new_node->name = strdup(name);
    new_node->distance_from_source = 0.0;
    new_node->visited = 0;
    new_node->adjacent_nodes = NULL;
    new_node->adjacent_node_count = 0;
    return new_node;
}

void add_edge(Node *src, Node *dest) {
    src->adjacent_nodes = realloc(src->adjacent_nodes, sizeof(Node*)*(src->adjacent_node_count+1));
    src->adjacent_nodes[src->adjacent_node_count] = dest;
    (src->adjacent_node_count)++;
}

void bfs(Node *start) {
    Node **queue = malloc(sizeof(Node*));
    int queue_front = 0, queue_back = 1;
    start->visited = 1;
    queue[0] = start;

    while (queue_front < queue_back) {
        Node *current = queue[queue_front++];

        for(int i=0; i<current->adjacent_node_count; ++i){
            if(!current->adjacent_nodes[i]->visited){
                current->adjacent_nodes[i]->distance_from_source = current->distance_from_source + 1.0;
                current->adjacent_nodes[i]->visited = 1;
                queue = realloc(queue, sizeof(Node*)*(++queue_back));
                queue[queue_back - 1] = current->adjacent_nodes[i];
            }
        }
    }

    free(queue);
}
```
This code creates a graph with nodes that have names, distances from the source node, and an array of pointers to adjacent nodes. The `bfs` function performs a breadth-first search starting at a specified node. It uses a queue data structure to keep track of which nodes to visit next. 

Please note that this is a basic implementation and does not include many features you requested such as integration with external systems or detailed logging mechanism. You would need to add these features yourself based on your specific requirements. Also, the code does not handle edge cases like disconnected components and cycles. These are complex issues that require more sophisticated handling and may involve additional data structures and algorithms.
