['Here is an example of how you might implement such a function in C. This code does not include all the features mentioned as it would require a lot more context and specifics about your environment and requirements. However, this should give you a good starting point for building out your own caching system with error handling, thread safety, and integration with an external key-value store API:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct ResourceRequest {
    char* key;
    void* value;
    time_t timestamp;
} ResourceRequest;

// Assume we have an external API for a key-value store
extern int kvstore_put(char* key, void* value);
extern void* kvstore_get(char* key);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int totalRequests = 0;
int successfulCachedRequests = 0;
FILE *logFile;

void cacheResourceRequest(ResourceRequest *request, int memoryLimit) {
    pthread_mutex_lock(&lock);

    if (totalRequests >= memoryLimit) {
        fprintf(logFile, "Memory limit exceeded. Unable to cache request %d\n", totalRequests + 1);
        pthread_mutex_unlock(&lock);
        return;
    }

    ResourceRequest *newRequest = malloc(sizeof(ResourceRequest));
    if (newRequest == NULL) {
        fprintf(logFile, "Failed to allocate memory for request %d\n", totalRequests + 1);
        pthread_mutex_unlock(&lock);
        return;
    }

    newRequest->key = strdup(request->key);
    if (newRequest->key == NULL) {
        fprintf(logFile, "Failed to duplicate key for request %d\n", totalRequests + 1);
        free(newRequest);
        pthread_mutex_unlock(&lock);
        return;
    }

    newRequest->value = malloc(sizeof(request->value));
    if (newRequest->value == NULL) {
        fprintf(logFile, "Failed to allocate memory for value of request %d\n", totalRequests + 1);
        free(newRequest->key);
        free(newRequest);
        pthread_mutex_unlock(&lock);
        return;
    }

    memcpy(newRequest->value, request->value, sizeof(request->value));
    newRequest->timestamp = time(NULL);

    if (kvstore_put(newRequest->key, newRequest->value) != 0) {
        fprintf(logFile, "Failed to store request %d in key-value store\n", totalRequests + 1);
        free(newRequest->key);
        free(newRequest->value);
        free(newRequest);
        pthread_mutex_unlock(&lock);
        return;
    }

    successfulCachedRequests++;
    fprintf(logFile, "Successfully cached request %d\n", totalRequests + 1);

    pthread_mutex_unlock(&lock);
}
```
This code assumes that the `kvstore_put` function returns 0 on success and a non-zero value otherwise. It also uses a simple file for logging, which may not be suitable for all use cases. You would need to adapt this code based on your specific requirements and environment.
']

