#include <time.h>

typedef struct Record {
    int value;
    char* string;
    time_t timestamp;
    struct Record *next;
} Record;

Record* createRecords(int num) {
    srand(time(NULL)); // seed the random number generator

    Record *head = NULL, *tail = NULL;
    for (int i = 0; i < num; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE); // or return NULL depending on your needs
        }

        record->value = rand(); // generate a random int value
        record->string = malloc(10 * sizeof(char)); // allocate memory for string
        if (!record->string) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE); // or return NULL depending on your needs
        }

        sprintf(record->string, "%d", record->value); // convert int to string
        record->timestamp = time(NULL); // get current timestamp
        record->next = NULL;

        if (!head) {
            head = tail = record;
        } else {
            tail->next = record;
            tail = record;
        }
    }

    return head;
}

void freeRecords(Record *records) {
    Record *current, *next;
    for (current = records; current != NULL; current = next) {
        next = current->next;
        free(current->string); // free string memory
        free(current); // free record structure
    }
}
