typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutexHead = PTHREAD_MUTEX_INITIALIZER;

void insert(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation failure
        return;
    }

    newNode->data = data;
    pthread_mutex_lock(&mutexHead);
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&mutexHead);
}

void clear() {
    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_lock(&mutexHead);
    head = NULL;
    pthread_mutex_unlock(&mutexHead);
}

void iterate() {
    Node* current = head;
    while (current != NULL) {
        // Process data in some way...

        current = current->next;
    }
}
