public class RandomValueGenerator {
    private int minInt;
    private int maxInt;
    private float minFloat;
    private float maxFloat;

    public RandomValueGenerator(int minInt, int maxInt, float minFloat, float maxFloat) {
        this.minInt = minInt;
        this.maxInt = maxInt;
        this.minFloat = minFloat;
        this.maxFloat = maxFloat;
    }

