        double val = (rand.NextDouble() * (this.maxFloat - this.minFloat) + this.minFloat);
        return (float)val;
    }

    public override string ToString() {
        return $"Integer range: [{this.minInt}, {this.maxInt}], Float range: [{this.minFloat}, {this.maxFloat}]";
    }

    public void Serialize(string filePath) {
        using (Stream stream = File.Open(filePath, FileMode.Create)) {
            BinaryFormatter binaryFormatter = new BinaryFormatter();
            binaryFormatter.Serialize(stream, this);
        }
    }

    public static RandomValueGenerator Deserialize(string filePath) {
        using (Stream stream = File.Open(filePath, FileMode.Open)) {
            BinaryFormatter binaryFormatter = new BinaryFormatter();
            return (RandomValueGenerator)binaryFormatter.Deserialize(stream);
        }
    }
}
