#include <string.h>

typedef struct TX_EVM_HISTORY_RECORD {
    int userID;
    char* message;
    struct TX_EVM_HISTORY_RECORD* prev;
    struct TX_EVM_HISTORY_RECORD* next;
} TX_EVM_HISTORY_RECORD;

typedef struct {
    pthread_mutex_t lock;
    TX_EVM_HISTORY_RECORD* head;
    TX_EVM_HISTORY_RECORD* tail;
} RecordList;

RecordList recordList = {PTHREAD_MUTEX_INITIALIZER, NULL, NULL};

TX_EVM_HISTORY_RECORD* findRecord(int userID) {
    pthread_mutex_lock(&recordList.lock);
    TX_EVM_HISTORY_RECORD* current = recordList.head;
    while (current != NULL && current->userID != userID) {
        current = current->next;
    }
    pthread_mutex_unlock(&recordList.lock);
    return current;
}

void insertRecord(int userID, char* message) {
    TX_EVM_HISTORY_RECORD* newRecord = malloc(sizeof(TX_EVM_HISTORY_RECORD));
    newRecord->userID = userID;
    newRecord->message = strdup(message);
    pthread_mutex_lock(&recordList.lock);
    if (recordList.head == NULL) {
        recordList.head = newRecord;
        recordList.tail = newRecord;
    } else {
        recordList.tail->next = newRecord;
        newRecord->prev = recordList.tail;
        recordList.tail = newRecord;
    }
    pthread_mutex_unlock(&recordList.lock);
}

void removeRecord(int userID) {
    TX_EVM_HISTORY_RECORD* recordToRemove = findRecord(userID);
    if (recordToRemove != NULL) {
        pthread_mutex_lock(&recordList.lock);
        if (recordToRemove->prev != NULL) {
            recordToRemove->prev->next = recordToRemove->next;
        } else {
            recordList.head = recordToRemove->next;
        }
        if (recordToRemove->next != NULL) {
            recordToRemove->next->prev = recordToRemove->prev;
        } else {
            recordList.tail = recordToRemove->prev;
        }
        pthread_mutex_unlock(&recordList.lock);
        free(recordToRemove->message);
        free(recordToRemove);
    }
}
```
