long* offsets = NULL;
int* keys = NULL;
char** strings = NULL;
int num_records = 0;
pthread_mutex_t lock;

void init(int size, int min, int max) {
    srand(time(NULL));

    records = malloc(sizeof(Record*) * size);
    offsets = malloc(sizeof(long) * size);
    keys = malloc(sizeof(int) * size);
    strings = malloc(sizeof(char*) * size);

    for (int i = 0; i < size; i++) {
        records[i] = malloc(sizeof(Record));
        offsets[i] = rand() % 1000000;
        keys[i] = rand() % (max - min + 1) + min;

        int string_index = rand() % size;
        strings[string_index] = malloc(sizeof(char) * 256);
        sprintf(strings[string_index], "String%d", string_index);

        records[i]->value = keys[i];
        records[i]->string = strings[string_index];
    }

    num_records = size;
}

void insert(Record* record) {
    pthread_mutex_lock(&lock);

    records = realloc(records, sizeof(Record*) * (num_records + 1));
    offsets = realloc(offsets, sizeof(long) * (num_records + 1));
    keys = realloc(keys, sizeof(int) * (num_records + 1));

    records[num_records] = record;
    offsets[num_records] = rand() % 1000000;
    keys[num_records] = record->value;

    num_records++;

    pthread_mutex_unlock(&lock);
}

void delete(int key) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_records; i++) {
        if (keys[i] == key) {
            free(strings[i]);
            free(records[i]);

            strings[i] = strings[num_records - 1];
            offsets[i] = offsets[num_records - 1];
            keys[i] = keys[num_records - 1];
            records[i] = records[num_records - 1];

            num_records--;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void cleanup() {
    for (int i = 0; i < num_records; i++) {
        free(strings[i]);
        free(records[i]);
    }

    free(records);
    free(offsets);
    free(keys);
    free(strings);
}
```
