```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;

public class DecryptionService
{
    private readonly ILogger<DecryptionService> _logger;
    private readonly string _authToken;

    public DecryptionService(ILogger<DecryptionService> logger, string authToken)
    {
        _logger = logger;
        _authToken = authToken;
    }

    public async Task<string> DecryptAsync(string base64Input, byte[] key, byte[] iv, CipherMode mode)
    {
        if (key.Length != 24 || iv.Length != 24)
        {
            _logger.LogError("Invalid key or IV length");
            throw new ArgumentException("Key and IV must be exactly 24 bytes each");
        }

        byte[] encryptedBytes;
        try
        {
            encryptedBytes = Convert.FromBase64String(base64Input);
        }
        catch (FormatException)
        {
            _logger.LogError("Invalid Base64 string format");
            throw new ArgumentException("Invalid Base64 string format");
        }

        using var tripleDes = TripleDES.Create();
        tripleDes.Key = key;
        tripleDes.IV = iv;
        tripleDes.Mode = mode;
        tripleDes.Padding = PaddingMode.PKCS7;

        var decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV);
        using var memoryStream = new MemoryStream();
        using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Write))
        {
            await cryptoStream.WriteAsync(encryptedBytes, 0, encryptedBytes.Length);
        }

        var decryptedBytes = memoryStream.ToArray();
        return Encoding.UTF8.GetString(decryptedBytes);
    }
}
```

