#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h> // For inet_pton() function

typedef struct UdpSocketConfig {
    char ip[INET6_ADDRSTRLEN];
    int port;
    int ttl;
} UdpSocketConfig;

UdpSocketConfig* initializeSockets(int num, const char* startIp, int startPort, int ttl) {
    // Allocate memory for the array of structures
    UdpSocketConfig* sockets = (UdpocketConfig*)malloc(num * sizeof(UdpSocketConfig));

    if (sockets == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Convert the start IP to a binary representation for incrementing
    struct in_addr addr;
    inet_pton(AF_INET, startIp, &addr);

    // Initialize each socket configuration
    for (int i = 0; i < num; ++i) {
        strncpy(sockets[i].ip, startIp, INET6_ADDRSTRLEN);
        sockets[i].port = startPort + i;
        sockets[i].ttl = ttl;

        // Increment the IP address for the next socket
        addr.s_addr = htonl(ntohl(addr.s_addr) + 1);
    }

    return sockets;
}
```
This function takes in a number of sockets to initialize, a starting IP and port, and a default TTL value. It allocates memory for the array of structures using malloc, then initializes each socket configuration with an incrementing IP address and unique port number. The IP address is converted to binary representation for easy incrementing.

