        return NULL;
    }

    char* newDescription = descriptionBuffer + numDescriptions;
    strncpy(newDescription, description, MAX_DESCRIPTION_LEN - numDescriptions);
    newDescription[MAX_DESCRIPTION_LEN - numDescriptions - 1] = '\0'; // Ensure null-termination

    numDescriptions += strlen(description) + 1;

    pthread_mutex_unlock(&descriptionMutex);

    return newDescription;
}

void addTask(const char* description, double deadline, Worker* handler) {
    pthread_mutex_lock(&taskMutex);

    tasks = realloc(tasks, (numTasks + 1) * sizeof(Task));
    if (!tasks) {
        fprintf(stderr, "Error: Failed to allocate memory for task.\n");
        return;
    }

    Task* newTask = &tasks[numTasks];
    newTask->description = addDescription(description);
    newTask->deadline = deadline;
    newTask->handler = handler;

    numTasks++;

    pthread_mutex_unlock(&taskMutex);
}

void* calculateProgress(void* arg) {
    Task* task = (Task*)arg;

    while (1) {
        double progress = 100.0 * ((double)clock() / CLOCKS_PER_SEC) / task->deadline;

        printf("Progress for task '%s': %.2f%%\n", task->description, progress);

        // Sleep for a while to avoid busy waiting
        sleep(1);
    }

    return NULL;
}
```
This code creates a fixed-size buffer for pre-allocated descriptions and dynamically manages an array of tasks. It uses mutexes to ensure thread safety when accessing shared resources, such as the description buffer and task array. The `calculateProgress` function is run in its own thread to periodically calculate and print the progress percentage of each task.
']

