#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t size;
    pthread_mutex_t lock;
} DataStructures;

DataStructures* init(size_t size, int min, int max) {
    srand(time(NULL));

    if (size <= 0 || min >= max) return NULL;

    DataStructures* ds = malloc(sizeof(DataStructures));
    if (!ds) return NULL;

    ds->offsets = aligned_alloc(64, size * sizeof(long)); // align to cache line
    ds->keys = calloc(max - min + 1, sizeof(int));
    ds->records = malloc(size * sizeof(record));

    if (!ds->offsets || !ds->keys || !ds->records) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
        return NULL;
    }

    ds->size = size;
    pthread_mutex_init(&ds->lock, NULL);

    for (size_t i = 0; i < size; ++i) {
        int key;

        do {
            key = rand() % (max - min + 1) + min;
        } while (ds->keys[key]);

        ds->offsets[i] = i * sizeof(record);
        ds->keys[key] = 1;
        ds->records[i].value = key;
    }

    return ds;
}

void destroy(DataStructures* ds) {
    if (!ds) return;

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}
```
