public class ThemeCacheManager {
    private static final String DEFAULT_THEME_DIR = System.getenv("THEME_DIR") != null ? 
        System.getenv("THEME_DIR") : "/default/theme/dir";

    private ConcurrentHashMap<String, SoftReference<BufferedImage>> cache;
    private ExecutorService executorService;
    private String themeDirPath = DEFAULT_THEME_DIR;

    public ThemeCacheManager() {
        this.cache = new ConcurrentHashMap<>();
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

