    public BufferedImage getTheme(String themeName) {
        SoftReference<BufferedImage> ref = cache.get(themeName);
        BufferedImage image = (ref != null) ? ref.get() : null;

        if (image == null) {
            try {
                File file = Paths.get(themeDirPath, themeName + ".png").toFile();
                image = ImageIO.read(file);

                // Add to cache
                cache.put(themeName, new SoftReference<>(image));
            } catch (IOException e) {
                System.err.println("Failed to load theme: " + themeName);
            }
        }

        return image;
    }

    // Clear the entire cache
