["Here is a simplified version of how you might implement this in C. This code does not include all the features mentioned such as error handling, logging, garbage collection, thread safety etc. Also, it's important to note that real-world applications would require more robust error checking and handling mechanisms. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char* key;
    time_t timestamp;
    double value;
    long offset;
    int indexKey;
} Record;

typedef struct Node {
    Record record;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock;

void* customAlloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Handle memory allocation failure
    }
    return ptr;
}

Record createRecord(char* key, time_t timestamp, double value, long offset, int indexKey) {
    Record record;
    record.key = customAlloc(strlen(key) + 1);
    strcpy(record.key, key);
    record.timestamp = timestamp;
    record.value = value;
    record.offset = offset;
    record.indexKey = indexKey;
    return record;
}

void insertRecord(char* key, time_t timestamp, double value, long offset, int indexKey) {
    pthread_mutex_lock(&lock);

    Node *newNode = customAlloc(sizeof(Node));
    newNode->record = createRecord(key, timestamp, value, offset, indexKey);
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void deleteRecord(char* key) {
    pthread_mutex_lock(&lock);

    Node *temp = head, *prev = NULL;
    while (temp != NULL && strcmp(temp->record.key, key)) {
        prev = temp;
        temp = temp->next;
    }
    if (temp == NULL) return; // Record not found

    if (prev != NULL) 
        prev->next = temp->next;

    if (head == temp) 
        head = temp->next;

    free(temp);

    pthread_mutex_unlock(&lock);
}
```
