#include <stdlib.h>
#include <pthread.h>
#include <glib.h>

typedef struct {
    int value;
} Record;

GHashTable* long_offsets = NULL;
GHashTable* int_keys = NULL;
GArray* records = NULL;

pthread_mutex_t lock;

void init() {
    pthread_mutex_init(&lock, NULL);

    long_offsets = g_hash_table_new(g_direct_hash, g_direct_equal);
    int_keys = g_hash_table_new(g_direct_hash, g_direct_equal);
    records = g_array_new(FALSE, FALSE, sizeof(Record));
}

void* read_data(int key) {
    void* data;

    pthread_mutex_lock(&lock);
    data = g_hash_table_lookup(int_keys, &key);
    pthread_mutex_unlock(&lock);

    return data;
}

void write_data(long offset, int key, Record* record) {
    pthread_mutex_lock(&lock);

    g_hash_table_insert(long_offsets, &offset, record);
    g_hash_table_insert(int_keys, &key, record);
    g_array_append_val(records, *record);

    pthread_mutex_unlock(&lock);
}

void delete_data(long offset, int key) {
    pthread_mutex_lock(&lock);

    Record* record = g_hash_table_lookup(int_keys, &key);
    if (record != NULL) {
        g_hash_table_remove(long_offsets, &offset);
        g_hash_table_remove(int_keys, &key);

        int index = record - (Record*)records->data;
        g_array_remove_index_fast(records, index);
    }

    pthread_mutex_unlock(&lock);
}

void destroy() {
    pthread_mutex_destroy(&lock);

    g_hash_table_destroy(long_offsets);
    g_hash_table_destroy(int_keys);
    g_array_free(records, TRUE);
}
