        if (!packet) continue;  // Handle allocation failure gracefully

        packet->payload = malloc(payloadSize);
        if (!packet->payload) {
            free(packet);
            continue;
        }

        packet->timestamp = time(NULL);
        packets[i] = packet;
    }
    pthread_mutex_unlock(&lock);

    return packets;
}
