#include <stdatomic.h>

typedef struct node {
    int value;
    char *data;
    double d_value;
    struct node *next, *prev;
} Node;

// Memory pool for nodes
Node* memoryPool = NULL;
atomic_int nextFree = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initMemoryPool(size_t size) {
    pthread_mutex_lock(&mutex);
    memoryPool = (Node*) malloc(sizeof(Node) * size);
    for (int i = 0; i < size - 1; ++i) {
        memoryPool[i].next = &memoryPool[i + 1];
    }
    memoryPool[size - 1].next = NULL;
    pthread_mutex_unlock(&mutex);
}

Node* getNewNode() {
    Node *node = &memoryPool[atomic_fetch_add(&nextFree, 1)];
    node->data = malloc(sizeof(char) * MAX_DATA_SIZE); // Assuming MAX_DATA_SIZE is defined somewhere else in your code.
    return node;
}

void insertNodeSorted(Node **head, Node *node) {
    pthread_mutex_lock(&mutex);
    if (*head == NULL || (*head)->value >= node->value) {
        node->next = *head;
        node->prev = NULL;
        if (*head != NULL) {
            (*head)->prev = node;
        }
        *head = node;
    } else {
        Node* current = *head;
        while (current->next != NULL && current->next->value < node->value) {
            current = current->next;
        }
        node->next = current->next;
        if (current->next != NULL) {
            current->next->prev = node;
        }
        current->next = node;
        node->prev = current;
    }
    pthread_mutex_unlock(&mutex);
}

void cleanup(Node **head) {
    Node* current = *head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp->data);
    }
    free(memoryPool);
}
```
This code implements a memory pool for nodes, which can be used to optimize allocation and reduce fragmentation. It also uses a doubly linked list to maintain sorted order based on integer values. The cleanup function frees all allocated resources when the function execution ends. 

