#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct {
    size_t capacity;
    size_t count;
    Record* records;
} Collection;

Collection* create_collection(size_t initial_capacity) {
    Collection* collection = malloc(sizeof(Collection));
    if (collection == NULL) return NULL;

    collection->records = malloc(initial_capacity * sizeof(Record));
    if (collection->records == NULL) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;

    return collection;
}

void destroy_collection(Collection* collection) {
    if (collection == NULL) return;

    free(collection->records);
    free(collection);
}

int resize_collection(Collection* collection, size_t new_capacity) {
    Record* new_records = realloc(collection->records, new_capacity * sizeof(Record));
    if (new_records == NULL) return -1;

    collection->records = new_records;
    collection->capacity = new_capacity;

    return 0;
}

int add_record(Collection* collection, Record record) {
    if (collection->count == collection->capacity) {
        size_t new_capacity = 2 * collection->capacity;
        int res = resize_collection(collection, new_capacity);
        if (res != 0) return -1;
    }

    collection->records[collection->count] = record;
    collection->count++;

    return 0;
}

void iterate_over_records(Collection* collection, void (*callback)(Record*, void*), void* user_data) {
    for (size_t i = 0; i < collection->count; ++i) {
        callback(&collection->records[i], user_data);
    }
}
```
This code uses a simple realloc strategy to resize the collection. It doubles the capacity each time it needs to resize, which is efficient but may lead to frequent resizing for large datasets. A more sophisticated strategy could be used based on specific requirements and trade-offs between memory usage, iteration speed, and resizing frequency.

