ConnectionList* createConnectionList() {
    ConnectionList* list = malloc(sizeof(ConnectionList));
    list->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    list->connections = NULL;
    list->count = 0;
    list->capacity = 0;
    return list;
}

void addConnection(ConnectionList* list, Connection* connection) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity == 0 ? 1 : list->capacity * 2;
        Connection** newConnections = realloc(list->connections, sizeof(Connection*) * newCapacity);

        if (newConnections == NULL) {
            pthread_mutex_unlock(&list->lock);
            return;
        }

        list->capacity = newCapacity;
        list->connections = newConnections;
    }

    list->connections[list->count++] = connection;

    pthread_mutex_unlock(&list->lock);
}

void removeConnection(ConnectionList* list, int id) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->connections[i]->id == id) {
            free(list->connections[i]);

            // Shift all elements after the removed one to fill the gap.
            for (size_t j = i; j < list->count - 1; ++j) {
                list->connections[j] = list->connections[j + 1];
            }

            --list->count;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}
