void initializeRecordsAndEncrypt() {
    // Define the number of record sets and their size
    const int num_sets = 10;
    const int set_size = 1024;

    // Allocate memory for each record set
    long* offsets = malloc(num_sets * sizeof(long));
    Record** records = malloc(num_sets * sizeof(Record*));

    // Initialize OpenSSL library
    EVP_add_cipher(EVP_aes_256_cbc());
