#include <pthread.h>
#include <stdatomic.h>
#include <stdlib.h>
#include <string.h>

typedef struct File {
    int id;
    time_t timestamp;
} File;

typedef struct Directory {
    char* name;
    atomic_int accessFlag;
    pthread_mutex_t mutex;
    File** files;
    size_t fileCount;
    size_t maxFiles;
} Directory;

typedef struct FileSystem {
    pthread_mutex_t mutex;
    atomic_int directoryCount;
    int readOnly;
    Directory** directories;
} FileSystem;

FileSystem* createFileSystem(size_t initialSize, size_t maxFilesPerDir) {
    FileSystem* fs = malloc(sizeof(FileSystem));
    pthread_mutex_init(&fs->mutex, NULL);
    atomic_store(&fs->directoryCount, 0);
    fs->readOnly = 0;
    fs->directories = calloc(initialSize, sizeof(Directory*));

    for (size_t i = 0; i < initialSize; ++i) {
        Directory* dir = malloc(sizeof(Directory));
        dir->name = NULL;
        atomic_store(&dir->accessFlag, 0);
        pthread_mutex_init(&dir->mutex, NULL);
        dir->files = calloc(maxFilesPerDir, sizeof(File*));
        dir->fileCount = 0;
        dir->maxFiles = maxFilesPerDir;

        fs->directories[i] = dir;
    }

    return fs;
}

void addDirectory(FileSystem* fs, const char* name) {
    if (fs->readOnly) {
        // Handle error: file system is read-only
        return;
    }

    size_t index = atomic_fetch_add(&fs->directoryCount, 1);
    Directory* dir = fs->directories[index];

    pthread_mutex_lock(&dir->mutex);
    if (dir->name != NULL) {
        // Handle error: directory already exists
        pthread_mutex_unlock(&dir->mutex);
        return;
    }

    dir->name = strdup(name);
    pthread_mutex_unlock(&dir->mutex);
}

void addFile(FileSystem* fs, const char* dirName, int fileId) {
    for (size_t i = 0; i < atomic_load(&fs->directoryCount); ++i) {
        Directory* dir = fs->directories[i];

        pthread_mutex_lock(&dir->mutex);
        if (strcmp(dir->name, dirName) == 0) {
            if (atomic_load(&dir->accessFlag)) {
                // Handle error: directory is currently being accessed
                pthread_mutex_unlock(&dir->mutex);
                return;
            }

            atomic_store(&dir->accessFlag, 1);
            if (dir->fileCount >= dir->maxFiles) {
                // Handle error: directory is full
                atomic_store(&dir->accessFlag, 0);
                pthread_mutex_unlock(&dir->mutex);
                return;
            }

            File* file = malloc(sizeof(File));
            file->id = fileId;
            time(&file->timestamp);
            dir->files[dir->fileCount++] = file;

            atomic_store(&dir->accessFlag, 0);
            pthread_mutex_unlock(&dir->mutex);
            return;
        }

        pthread_mutex_unlock(&dir->mutex);
    }

    // Handle error: directory not found
}
```
