#include <pthread.h>

typedef struct {
    int value;
} Record;

long* offsets;
int* keys;
Record* records;
FILE* data_file;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init() {
    srand(time(NULL));
    offsets = malloc(10000 * sizeof(long));
    keys = malloc(10000 * sizeof(int));
    records = calloc(5000, sizeof(Record));
}

void populate_arrays() {
    for (int i = 0; i < 10000; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 901 + 100; // random number between 100 and 1000
    }
}

void populate_records() {
    for (int i = 0; i < 5000; i++) {
        pthread_mutex_lock(&lock);
        records[i].value = rand() % 901 + 100; // random number between 100 and 1000
        pthread_mutex_unlock(&lock);
    }
}

void read_data(char* filename) {
    data_file = fopen(filename, "r");
    if (data_file == NULL) {
        printf("Error opening file\n");
        return;
    }

    int i = 0;
    while (!feof(data_file)) {
        pthread_mutex_lock(&lock);
        fscanf(data_file, "%d,%d", &offsets[i], &keys[i]);
        pthread_mutex_unlock(&lock);
        i++;
    }

    fclose(data_file);
}

void serialize() {
    FILE* file = fopen("records.bin", "wb");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    fwrite(records, sizeof(Record), 5000, file);
    fclose(file);
}

void deserialize() {
    FILE* file = fopen("records.bin", "rb");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    fread(records, sizeof(Record), 5000, file);
    fclose(file);
}

void filter_records() {
    int count = 0;
    for (int i = 0; i < 5000; i++) {
        if (records[i].value % 5 == 0) {
            records[i].value = 0;
            count++;
        }
    }

    printf("Number of filtered records: %d\n", count);
}
```
