#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct DataPacket {
    void* payload; // replace with actual data type if known
    time_t timestamp;
} DataPacket;

typedef struct Node {
    DataPacket* packet;
    struct Node* next;
} Node;

Node* head = NULL;
int nodeCount = 0;

void add_node(DataPacket* data) {
    Node* newNode = (Node*)malloc(sizeof(Node));

    if(newNode == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    newNode->packet = data;
    newNode->next = NULL;

    if(head == NULL) {
        head = newNode;
    } else {
        Node* current = head;

        while(current->next != NULL) {
            current = current->next;
        }

        current->next = newNode;
    }

    nodeCount++;
}

void free_nodes() {
    Node* current = head;

    while(current != NULL) {
        Node* temp = current;
        current = current->next;

        free(temp->packet);
        free(temp);
    }

    nodeCount = 0;
}
```
