typedef struct SensorReading {
    time_t timestamp;
    uint16_t sensorID;
    float measurementValue;
    struct SensorReading *next;
} SensorReading;

SensorReading *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* simulateSensorReadings(void *arg) {
    while (1) {
        float min = 0.0f, max = 100.0f; // specify your range here
        SensorReading *newReading = malloc(sizeof(SensorReading));
        if (!newReading) {
            g_critical("Failed to allocate memory for new sensor reading");
            continue;
        }
        newReading->timestamp = time(NULL);
        newReading->sensorID = 0; // specify your ID here
        newReading->measurementValue = min + ((float)rand() / (float)(RAND_MAX)) * max;

        pthread_mutex_lock(&lock);
        newReading->next = head;
        head = newReading;
        pthread_mutex_unlock(&lock);
    }
}

int main() {
    srand(time(NULL)); // seed the random number generator

    pthread_t thread1, thread2;
    if (pthread_create(&thread1, NULL, &simulateSensorReadings, NULL) != 0 ||
        pthread_create(&thread2, NULL, &simulateSensorReadings, NULL) != 0) {
        g_critical("Failed to create threads");
        return 1;
    }

    if (pthread_join(thread1, NULL) != 0 || pthread_join(thread2, NULL) != 0) {
        g_critical("Failed to join threads");
        return 1;
    }

    // clean up allocated resources
    while (head) {
        SensorReading *next = head->next;
        free(head);
        head = next;
    }

    return 0;
}
