    size_t recordCount;
    pthread_mutex_t lock;
} DataContainer;

DataContainer* allocateAndPopulate(size_t offsetSize, size_t keySize, size_t recordSize) {
    if (offsetSize + keySize > SIZE_MAX - sizeof(DataContainer)) {
        return NULL; // Error: Not enough memory
    }

    DataContainer* container = malloc(sizeof(DataContainer));
    if (!container) {
        return NULL; // Error: Failed to allocate memory for the container
    }

    container->offsets = calloc(offsetSize, sizeof(long));
    container->keys = calloc(keySize, sizeof(int));
    container->records = malloc(recordSize * sizeof(Record));
    if (!container->offsets || !container->keys || !container->records) {
        freeDataContainer(container); // Error: Failed to allocate memory for arrays
        return NULL;
    }

    container->recordCount = recordSize;
    pthread_mutex_init(&container->lock, NULL);

    srand(time(NULL));
    for (size_t i = 0; i < recordSize; ++i) {
        container->records[i].value = rand();
        container->records[i].string = malloc(11); // 10 characters + null terminator
