```c
#include <pthread.h>
#include <openssl/sha.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    char* id;
    int value;
    double timestamp;
    char status;
    struct Record *next;
} Record;

Record* hashTable[1024];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

unsigned long hash(char *str) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, str, strlen(str));
    SHA256_Final(hash, &sha256);

    unsigned long hashVal = 0;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        hashVal += hash[i];
    }
    return hashVal % 1024;
}

Record* createRecord(char *id, int value, double timestamp, char status) {
    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        // Handle allocation failure
        return NULL;
    }

    record->id = id;
    record->value = value;
    record->timestamp = timestamp;
    record->status = status;
    record->next = NULL;

    return record;
}

void insertRecord(char *id, int value, double timestamp, char status) {
    pthread_mutex_lock(&lock);

    unsigned long index = hash(id);
    Record* newRecord = createRecord(id, value, timestamp, status);
    if (newRecord == NULL) {
        // Handle allocation failure
        return;
    }

    newRecord->next = hashTable[index];
    hashTable[index] = newRecord;

    pthread_mutex_unlock(&lock);
}

// Implement other functions like updateRecord, deleteRecord, getRecord etc. 
