    inet_ntop(AF_INET, &(iph->daddr), p->destIP, INET6_ADDRSTRLEN);
}

void managePackets(char *dev, int portRangeStart, int portRangeEnd) {
    char errbuf[PCAP_ERRBUF_SIZE];

    // Open the device for live capture.
    pcap_t *handle = pcap_open_live(dev, BUFSIZ, 1 /* promiscuous mode */, -1, errbuf);
    if (handle == NULL) {
