    Packet *packets = malloc(sizeof(Packet) * 1024);
    int packetCount = 0;

    // Start the capture loop.
    pcap_loop(handle, -1, packetHandler, (u_char*) &packets[packetCount]);

    // Filter packets based on port range.
    for (int i = 0; i < packetCount; ++i) {
        if (/* packet falls within the specified port range */) {
            // Keep this packet.
        } else {
            // Discard this packet.
        }
    }

    // Log packets to a file or send them to another system.
