    for (int i = 0; i < packetCount; ++i) {
        fprintf(logFile, "%ld %s -> %s\n", packets[i].timestamp, packets[i].sourceIP, packets[i].destIP);
    }

    // Clean up.
    pcap_close(handle);
    free(packets);
}
