void manageArray(int N) {
    pthread_mutex_lock(&lock);

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T* newArray = (NFAPI_CRC_INDICATION_PDU_T*) realloc(array, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

