```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <assert.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
    int size;
} LinkedList;

LinkedList* createList() {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (list == NULL) return NULL; // Handle memory allocation failure

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;

    return list;
}

void insert(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) return; // Handle memory allocation failure

    newNode->data = data;
    pthread_mutex_lock(&list->lock);
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void delete(LinkedList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) return; // No matching RNTI found

    if (prev == NULL) list->head = current->next;
    else prev->next = current->next;

    free(current);
    list->size--;
    pthread_mutex_unlock(&list->lock);
}

void updateCRCFLAG(LinkedList* list, int RNTI, int newValue) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current != NULL && current->data.RNTI != RNTI) {
        current = current->next;
    }

    if (current == NULL) return; // No matching RNTI found

    current->data.CRCFLAG = newValue;
    pthread_mutex_unlock(&list->lock);
}
```
