                --i; // try again with a different key
                break;
            }
        }
    }

    // Populate records array
    for (int i = 0; i < num_records; ++i) {
        records[i].key = keys[i];
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    // Free memory for keys and offsets arrays
    free(keys);
    free(offsets);

    return records;
}

void deallocate(record *records) {
