#include <pthread.h>

typedef struct node {
    char* string;
    int priority;
    struct node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert(char* str, int prio) {
    if (str == NULL || prio < 0) {
        printf("Invalid input\n");
        return;
    }

    pthread_mutex_lock(&lock);

    Node *newNode = malloc(sizeof(Node));
    newNode->string = strdup(str);
    newNode->priority = prio;

    if (head == NULL || head->priority < prio) {
        newNode->next = head;
        head = newNode;
    } else {
        Node *current = head;

        while (current->next != NULL && current->next->priority > prio) {
            current = current->next;
        }

        if (current->next != NULL && current->next->priority == prio) {
            newNode->next = current->next->next;
        } else {
            newNode->next = current->next;
        }

        current->next = newNode;
    }

    pthread_mutex_unlock(&lock);
}

void printList() {
    Node *current = head;

    while (current != NULL) {
        printf("String: %s, Priority: %d\n", current->string, current->priority);
        current = current->next;
    }
}

void freeList() {
    Node *current = head;

    while (current != NULL) {
        Node *temp = current;
        current = current->next;

        free(temp->string);
        free(temp);
    }
}
```
