#include <pthread.h>

typedef struct {
    char* key;
    void* value;
    void* metadata;
} ResourceEntry;

typedef struct {
    size_t count;
    size_t maxSize;
    float loadFactor;
    pthread_mutex_t lock;
    ResourceEntry** entries;
} HashTable;

HashTable* createHashTable(size_t initialSize, float loadFactor) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->count = 0;
    table->maxSize = initialSize;
    table->loadFactor = loadFactor;
    pthread_mutex_init(&table->lock, NULL);

    table->entries = malloc(sizeof(ResourceEntry*) * initialSize);
    if (table->entries == NULL) {
        free(table);
        return NULL;
    }

    memset(table->entries, 0, sizeof(ResourceEntry*) * initialSize);
    return table;
}

void destroyHashTable(HashTable* table) {
    for (size_t i = 0; i < table->maxSize; ++i) {
        if (table->entries[i] != NULL) {
            free(table->entries[i]->key);
            free(table->entries[i]);
        }
    }

    pthread_mutex_destroy(&table->lock);
    free(table->entries);
    free(table);
}

int addEntryToTable(HashTable* table, const char* key, void* value, void* metadata) {
    if (table == NULL || key == NULL) return -1;

    pthread_mutex_lock(&table->lock);

    // Check load factor and resize if necessary
    float currentLoadFactor = table->count / (float)table->maxSize;
    if (currentLoadFactor > table->loadFactor) {
        size_t newMaxSize = table->maxSize * 2; // Double the size for simplicity

        ResourceEntry** newEntries = realloc(table->entries, sizeof(ResourceEntry*) * newMaxSize);
        if (newEntries == NULL) {
            pthread_mutex_unlock(&table->lock);
            return -1; // Failed to resize table
        }

        table->maxSize = newMaxSize;
        table->entries = newEntries;
    }

    ResourceEntry* entry = malloc(sizeof(ResourceEntry));
    if (entry == NULL) {
        pthread_mutex_unlock(&table->lock);
        return -1; // Failed to allocate memory for entry
    }

    entry->key = strdup(key);
    if (entry->key == NULL) {
        free(entry);
        pthread_mutex_unlock(&table->lock);
        return -1; // Failed to copy key string
    }

    entry->value = value;
    entry->metadata = metadata;

    table->entries[table->count++] = entry;

    pthread_mutex_unlock(&table->lock);
    return 0; // Successfully added entry
}
```
This code provides a basic hash table implementation with dynamic resizing and thread safety. It does not include the logging functionality or external dependency handling as those would require additional details about your use case. You should add appropriate error checking, synchronization mechanisms, and logging to meet your specific requirements.
