['Here is a basic implementation in C for a linked list with priority insertion and string consolidation. This code does not include all the features you mentioned due to their complexity and size. However, it should give you a good starting point. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char* string;
    int priority;
    struct Node* next;
} Node;

Node* create_node(char* str, int prio) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->string = malloc(strlen(str) + 1);
    strcpy(new_node->string, str);
    new_node->priority = prio;
    new_node->next = NULL;

    return new_node;
}

void insert_sorted(Node** head, char* str, int prio) {
    Node* new_node = create_node(str, prio);
    if (!new_node) return;

    // If the list is empty or the priority of the first node is less than the new node's priority
    if (*head == NULL || (*head)->priority < prio) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;

        // Traverse the list until we find a node with lower priority or reach the end of the list
        while (current->next != NULL && current->next->priority >= prio) {
            if (strcmp(current->string, str) == 0) break; // If strings are equal, stop here
            current = current->next;
        }

        new_node->next = current->next;
        current->next = new_node;
    }
}

void print_list(Node* head) {
    Node* temp = head;

    while (temp != NULL) {
        printf("String: %s, Priority: %d\n", temp->string, temp->priority);
        temp = temp->next;
    }
}

int main() {
    Node* head = NULL;

    insert_sorted(&head, "Hello", 3);
    insert_sorted(&head, "World", 2);
    insert_sorted(&head, "Hello", 1); // This will be inserted after the first "Hello" node due to identical strings and different priorities

    print_list(head);

    return 0;
}
```
This code creates a linked list where nodes are sorted by priority. If two nodes have the same string, they are placed next to each other in the list. The `insert_sorted` function handles this logic. It first checks if the list is empty or if the head node's priority is less than the new node's priority. If so, it inserts the new node at the beginning of the list. Otherwise, it traverses the list until it finds a node with lower priority or reaches the end of the list. It then inserts the new node after this node.
']

