typedef struct {
    int key;
    long *offset;
} record;

int manage_memory(size_t size, int minKey, int maxKey, int **keys, long **offsets, record ***records) {
    srand(time(NULL)); // seed the random number generator

    if (minKey > maxKey || size <= 0) return -1; // invalid input

    *keys = malloc(sizeof(int)*size);
    *offsets = calloc(size, sizeof(long));
    *records = malloc(sizeof(record*)*size);

    if (*keys == NULL || *offsets == NULL || *records == NULL) return -2; // allocation failed

    int i, count = 0;
    for (i=0; i<size; ++i) {
        (*keys)[i] = rand() % (maxKey-minKey+1) + minKey;

        if ((*offsets)[i] >= size || (*offsets)[i] < 0) continue; // out of bounds access

        (*records)[count] = malloc(sizeof(record));
        if ((*records)[count] == NULL) return -2; // allocation failed

        (*records)[count]->key = (*keys)[i];
        (*records)[count]->offset = &((*offsets)[(*offsets)[i]]);
        ++count;
    }

    return count;
}
```
