#include <stdlib.h>
#include <time.h>
#include <math.h>

typedef struct record {
    double floatingPoint;
    char identifier;
} Record;

typedef enum status {
    VALID,
    INVALID
} Status;

typedef struct node {
    int value;
    struct node* prev;
    struct node* next;
} Node;

void initializeDataStructures(int size, double minFP, double maxFP, char identifier, 
                             double rangeStart, double rangeEnd, int listMin, int listMax) {

    srand((unsigned int)time(NULL));

    // Allocate memory for arrays and linked list
    Record* records = (Record*)malloc(sizeof(Record)*size);
    Status* statusFlags = (Status*)calloc(size, sizeof(Status));
    Node* head = NULL;
    Node* tail = NULL;

    // Check for memory allocation failures
    if (!records || !statusFlags) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize records array and status flags
    double prevFP = 0.0;
    for (int i = 0; i < size; ++i) {
        double fp = minFP + ((double)rand() / RAND_MAX) * (maxFP - minFP);

        // Ensure no two adjacent records have floating-point values within 0.01 of each other
        while (fabs(fp - prevFP) < 0.01) {
            fp = minFP + ((double)rand() / RAND_MAX) * (maxFP - minFP);
        }

        records[i].floatingPoint = fp;
        records[i].identifier = identifier;

        // Set status flag based on predefined range mappings
        if (fp >= rangeStart && fp <= rangeEnd) {
            statusFlags[i] = VALID;
        } else {
            statusFlags[i] = INVALID;
        }

        prevFP = fp;
    }

    // Populate doubly linked list with integers from a predefined range
    int prevValue = 0;
    for (int i = 0; i < size; ++i) {
        Node* newNode = (Node*)malloc(sizeof(Node));

        if (!newNode) {
            printf("Memory allocation failed.\n");
            return;
        }

        int value = listMin + rand() % ((listMax + 1) - listMin);

        // Ensure no two consecutive nodes in the list have integer values differing by less than 5
        while (abs(value - prevValue) < 5) {
            value = listMin + rand() % ((listMax + 1) - listMin);
        }

        newNode->value = value;
        newNode->prev = tail;
        newNode->next = NULL;

        if (tail != NULL) {
            tail->next = newNode;
        } else {
            head = newNode;
        }

        tail = newNode;
        prevValue = value;
