            free(packet);
            break;
        }

        totalSize += sizeof(DataPacket) + rand() % 100 + 1;
        if (totalSize > maxSize) {
            printf("Maximum size limit reached\n");
            for (size_t j = 0; j <= i; ++j) {
                free(array[j]->payload);
                free(array[j]);
            }
            free(array);
            return NULL;
        }

        packet->timestamp = time(NULL);
        array[i] = packet;
