#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <msgpack.h>
#include <vector>
#include <map>
#include <algorithm>

typedef struct {
    float field;
    char* tag;
    time_t timestamp;
    int id;
    bool status;
} Record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void processAndPersistData(std::vector<double>& numbers, std::map<char, int>& map, 
                           std::vector<Record>& records, time_t windowStart, time_t windowEnd) {
    // Sort the floating-point numbers in ascending order.
    pthread_mutex_lock(&lock);
    std::sort(numbers.begin(), numbers.end());

    // Update the integer values in the map based on specific criteria.
    for (auto& record : records) {
        if (record.timestamp >= windowStart && record.timestamp <= windowEnd) {
            char key = record.tag[0];  // Example update rule: use first character of tag as key.
            auto it = map.find(key);
            if (it != map.end()) {
                it->second += record.status ? 1 : -1;  // Example update rule: increment or decrement based on status.
            } else {
                map[key] = record.status ? 1 : -1;  // If key not found, initialize with status value.
            }
        }
    }

    // Serialize the processed data into a compact binary format using MessagePack.
    msgpack_sbuffer* buffer = msgpack_sbuffer_new();
    msgpack_packer* pk = msgpack_packer_new(buffer, msgpack_sbuffer_write);

    // Pack the numbers.
    msgpack_pack_array(pk, numbers.size());
    for (double num : numbers) {
        msgpack_pack_double(pk, num);
    }

    // Pack the map.
    msgpack_pack_map(pk, map.size());
    for (auto& pair : map) {
        msgpack_pack_char(pk, pair.first);
        msgpack_pack_int(pk, pair.second);
    }

    // Pack the records within the window and matching criteria.
    msgpack_pack_array(pk, std::count_if(records.begin(), records.end(), [&](const Record& record) {
        return record.timestamp >= windowStart && record.timestamp <= windowEnd;  // Example criteria: timestamp within window.
    }));

    for (auto& record : records) {
        if (record.timestamp >= windowStart && record.timestamp <= windowEnd) {
            msgpack_pack_map(pk, 5);  // Assuming each Record has 5 fields. Adjust as needed.
            msgpack_pack_str(pk, strlen("field"));
            msgpack_pack_float(pk, record.field);
            msgpack_pack_str(pk, strlen("tag"));
            msgpack_pack_raw(pk, strlen(record.tag));
            msgpack_pack_char* (pk, record.tag);
            // Continue packing other fields...
        }
    }

    pthread_mutex_unlock(&lock);

    // Persist the serialized data to disk.
    FILE* file = fopen("data.msgpack", "wb");
    if (file != NULL) {
        fwrite(buffer->data, buffer->size, 1, file);
        fclose(file);
    }

    msgpack_sbuffer_free(buffer);
}
```
