#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <assert.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    int value;
    float data;
} record;

typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    record* records;
} RecordArray;

RecordArray* create_array(size_t initialCapacity) {
    RecordArray* array = malloc(sizeof(RecordArray));
    if (array == NULL) return NULL;

    array->records = malloc(initialCapacity * sizeof(record));
    if (array->records == NULL) {
        free(array);
        return NULL;
    }

    array->capacity = initialCapacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    srand(time(NULL)); // seed the random number generator

    return array;
}

void insert_record(RecordArray* array, size_t position, record rec) {
    assert(position <= array->count);

    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        // Double the capacity when full
        size_t newCapacity = array->capacity * 2;
        record* newRecords = realloc(array->records, newCapacity * sizeof(record));

        if (newRecords == NULL) {
            pthread_mutex_unlock(&array->lock);
            return;
        }

        array->capacity = newCapacity;
        array->records = newRecords;
    }

    // Shift records to make space for the new one
    memmove(array->records + position + 1, array->records + position, (array->count - position) * sizeof(record));

    array->records[position] = rec;
    array->count++;

    pthread_mutex_unlock(&array->lock);
}

void delete_record(RecordArray* array, size_t position) {
    assert(position < array->count);

    pthread_mutex_lock(&array->lock);

    // Shift records to fill the gap
    memmove(array->records + position, array->records + position + 1, (array->count - position - 1) * sizeof(record));

    array->count--;

    pthread_mutex_unlock(&array->lock);
}
```
This is a simplified version and does not include logging or error handling. Also, the memory management strategy used here (doubling capacity when full) can lead to significant memory fragmentation for large datasets. A more sophisticated approach might use a linked list or other data structure that allows efficient insertion at arbitrary positions without reallocating the entire array.
