#include <errno.h>

typedef struct {
    long offset;
    int key;
    float data;
} record;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    record *records;
} RecordArray;

RecordArray* create_record_array(size_t initial_capacity) {
    RecordArray *arr = malloc(sizeof(RecordArray));
    if (arr == NULL) return NULL;

    arr->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    arr->capacity = initial_capacity;
    arr->size = 0;
    arr->records = malloc(initial_capacity * sizeof(record));

    if (arr->records == NULL) {
        free(arr);
        return NULL;
    }

    return arr;
}

void destroy_record_array(RecordArray *arr) {
    pthread_mutex_destroy(&arr->lock);
    free(arr->records);
    free(arr);
}

int insert_record(RecordArray *arr, size_t index, record rec) {
    if (index > arr->size) return -1; // out of bounds

    pthread_mutex_lock(&arr->lock);

    if (arr->size == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        record *new_records = realloc(arr->records, new_capacity * sizeof(record));

        if (new_records == NULL) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // allocation failed
        }

        arr->records = new_records;
        arr->capacity = new_capacity;
    }

    memmove(arr->records + index + 1, arr->records + index, (arr->size - index) * sizeof(record));
    arr->records[index] = rec;
    arr->size++;

    pthread_mutex_unlock(&arr->lock);

    return 0; // success
}
