#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    int value;
    char buffer[256];
    bool flag;
} Data;

typedef struct Node {
    Data *data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    size_t count;
    size_t max_nodes;
    bool safety_mode;
} ListStatus;

ListStatus list_status = {NULL, 0, 1000000, false}; // Initialize with a safe limit of 1 million nodes.
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Node* create_node(Data *data) {
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory allocation failure.
        return NULL;
    }

    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

bool add_node(Data *data) {
    pthread_mutex_lock(&lock); // Lock to prevent race conditions.
    if (list_status.count >= list_status.max_nodes) {
        pthread_mutex_unlock(&lock); // Unlock before returning.
        return false; // Node overflow.
    }

    Node *new_node = create_node(data);
    if (new_node == NULL) {
        pthread_mutex_unlock(&lock); // Unlock before returning.
        return false; // Memory allocation failure.
    }

    new_node->next = list_status.head;
    list_status.head = new_node;
    list_status.count++;

    pthread_mutex_unlock(&lock); // Unlock after modifying the list.
    return true;
}

void cleanup() {
    Node *current = list_status.head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;

        free(temp->data); // Free the data structure.
        free(temp); // Free the node itself.
    }

    list_status.head = NULL;
    list_status.count = 0;
}
```
This code provides a basic linked list with thread safety and memory management. It does not include error handling for external services or logging, but it could be added in the future. The cleanup function frees all nodes and their associated data structures when called. 

Please note that this is a simplified example and real-world usage would require more complex code to handle edge cases and potential errors.
