#include <time.h>

typedef struct {
    float *readings;
    time_t timestamp;
} Sensor;

void readCSV(const char* filename, int bufferSize) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    // Allocate memory for sensor array and readings arrays
    Sensor *sensors = malloc(sizeof(Sensor) * bufferSize);
    float *readingsBuffer = malloc(sizeof(float) * bufferSize);
    short *indicesBuffer = malloc(sizeof(short) * bufferSize);

    int numRecords = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Parse the CSV line into readings and timestamp
        float reading;
        time_t timestamp;
        if (sscanf(line, "%f,%ld", &reading, &timestamp) != 2) {
            printf("Warning: malformed data\n");
            continue;
        }

        // Add the reading to the buffer
        readingsBuffer[numRecords] = reading;
        indicesBuffer[numRecords] = numRecords % bufferSize;

        // If we've filled up the buffer, process it
        if (++numRecords == bufferSize) {
            for (int i = 0; i < bufferSize; ++i) {
                sensors[indicesBuffer[i]].readings = &readingsBuffer[i];
                sensors[indicesBuffer[i]].timestamp = timestamp;
            }

            // Process the sensors here...
        }
    }

    // If there are any remaining records, process them
    if (numRecords > 0) {
        for (int i = 0; i < numRecords; ++i) {
            sensors[indicesBuffer[i]].readings = &readingsBuffer[i];
            sensors[indicesBuffer[i]].timestamp = timestamp;
        }

        // Process the sensors here...
    }

    fclose(file);
    free(sensors);
    free(readingsBuffer);
    free(indicesBuffer);
}
```
