#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int *key;
    unsigned long offset;
    int value;
} record;

void allocate_and_initialize(int n, int max_offset_sum, int min_value, int max_value, 
                             record **records, size_t *total_size) {
    if (n <= 0 || max_offset_sum < n - 1) {
        fprintf(stderr, "Invalid input parameters\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // seed the random number generator

    *records = malloc(sizeof(record) * n);
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int *keys = malloc(sizeof(int) * n);
    if (keys == NULL) {
        free(*records);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < n; ++i) {
        (*records)[i].key = &keys[i];
        *((*records)[i].key) = i; // unique key

        int offset_sum = 0;
        for (int j = 0; j < i; ++j) {
            offset_sum += (*records)[j].offset;
        }
        if (max_offset_sum - offset_sum < n - i) {
            fprintf(stderr, "Maximum offset sum exceeded\n");
            free(*records);
            free(keys);
            exit(EXIT_FAILURE);
        }

        (*records)[i].offset = rand() % (max_offset_sum - offset_sum + 1); // random offset

        int value;
        do {
            value = rand() % (max_value - min_value + 1) + min_value;
        } while (i > 0 && (*records)[i-1].value == value); // ensure no adjacent records have the same value

        (*records)[i].value = value;
    }

    *total_size = sizeof(record) * n + sizeof(int) * n;
}
```
This code assumes that `max_offset_sum` is large enough to accommodate all required offsets. If it's not, the program will fail with an error message. It also assumes that `min_value` and `max_value` are valid such that no two adjacent records have the same value.
