typedef struct {
    atomic_int* offsets;
    int* keys;
    Record** records;
    void** metadata;
    size_t capacity;
    pthread_mutex_t lock;
    atomic_size_t totalRecords;
} MemoryPool;

MemoryPool* createMemoryPool(size_t initialCapacity) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (pool == NULL) return NULL;

    pool->offsets = calloc(initialCapacity, sizeof(atomic_int));
    pool->keys = malloc(initialCapacity * sizeof(int));
    pool->records = malloc(initialCapacity * sizeof(Record*));
    pool->metadata = malloc(initialCapacity * sizeof(void*));

    if (pool->offsets == NULL || pool->keys == NULL || pool->records == NULL || pool->metadata == NULL) {
        freeMemoryPool(pool);
        return NULL;
    }

    pool->capacity = initialCapacity;
    pthread_mutex_init(&pool->lock, NULL);
    atomic_init(&pool->totalRecords, 0);

    return pool;
}

void freeMemoryPool(MemoryPool* pool) {
    if (pool == NULL) return;

    for (size_t i = 0; i < pool->capacity; ++i) {
        free(pool->records[i]);
    }

    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    free(pool->metadata);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void addRecordToPool(MemoryPool* pool, int key, double value) {
    if (pool == NULL) return;

    pthread_mutex_lock(&pool->lock);

    size_t index = atomic_fetch_add(&pool->totalRecords, 1);
    if (index >= pool->capacity) {
        // Handle out of memory condition here.
        // You might want to resize the pool or log an error message.
    } else {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        Record* record = malloc(sizeof(Record));
        if (record == NULL) return; // Handle out of memory condition here.

        record->timestamp = ts.tv_sec * 1000000000L + ts.tv_nsec;
        record->value = value;

        pool->offsets[index] = 1; // Set offset to 1 for simplicity.
        pool->keys[index] = key;
        pool->records[index] = record;
    }

    pthread_mutex_unlock(&pool->lock);
}
