#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* message;
    time_t timestamp;
    int priority;
    unsigned long sessionID;
} LogEntry;

LogEntry* allocate_logs(int num, size_t maxSize) {
    if (num <= 0 || num > maxSize) return NULL;

    LogEntry* logs = malloc(sizeof(LogEntry) * num);
    if (!logs) return NULL; // handle memory allocation failure

    for (int i = 0; i < num; ++i) {
        logs[i].message = malloc(maxSize);
        if (!logs[i].message) { // handle memory allocation failure
            free_logs(logs, i);
            return NULL;
        }
    }

    return logs;
}

int validate_logs(LogEntry* logs, int num) {
    for (int i = 0; i < num; ++i) {
        if (!logs[i].message || strlen(logs[i].message) == 0 || 
            logs[i].priority < 1 || logs[i].priority > 5) { // adjust priority levels as needed
            free_logs(logs, num);
            return -1; // indicate error
        }
    }

    return 0; // all entries are valid
}

void free_logs(LogEntry* logs, int num) {
    for (int i = 0; i < num; ++i) {
        if (logs[i].message) free(logs[i].message);
    }

    free(logs);
}
