    TaskManager* manager = malloc(sizeof(TaskManager));
    if (manager == NULL) return NULL;

    manager->taskCount = 0;
    manager->taskCapacity = 10;
    manager->tasks = malloc(sizeof(Task*) * manager->taskCapacity);
    if (manager->tasks == NULL) {
        free(manager);
        return NULL;
