    if (manager->taskCount >= manager->taskCapacity) {
        size_t newCapacity = manager->taskCapacity * 2;
        Task** newTasks = realloc(manager->tasks, sizeof(Task*) * newCapacity);
        if (newTasks == NULL) return;

        manager->tasks = newTasks;
        manager->taskCapacity = newCapacity;
    }

    Task* task = malloc(sizeof(Task));
    if (task == NULL) return;

    task->name = strdup(name);
    for (int i = 0; i < 500; ++i) {
        task->priority[i] = priority;
        task->status[i] = status;
    }

    manager->tasks[manager->taskCount++] = task;
}

void updateTask(TaskManager* manager, const char* name, int index, int newPriority, TaskStatus newStatus) {
    for (int i = 0; i < manager->taskCount; ++i) {
        if (strcmp(manager->tasks[i]->name, name) == 0) {
            manager->tasks[i]->priority[index] = newPriority;
            manager->tasks[i]->status[index] = newStatus;
            break;
        }
    }
}

