            return manager->tasks[i];
        }
    }

    return NULL;
}

Task* getTaskByIndex(TaskManager* manager, size_t index) {
    if (index < manager->taskCount) {
        return manager->tasks[index];
    } else {
        return NULL;
    }
}

void clearTasks(TaskManager* manager) {
    for (int i = 0; i < manager->taskCount; ++i) {
        free(manager->tasks[i]->name);
        free(manager->tasks[i]);
    }

    free(manager->tasks);
    free(manager);
}
