void process_nfaapi_crc_indications() {
    srand(time(NULL));

    int *array = NULL;
    int capacity = 0;
    int size = 0;

    while (1) {
        int num;
        if (scanf("%d", &num) != 1) break;

        // Check for duplicates
        int i;
        for (i = 0; i < size; ++i) {
            if (array[i] == num) break;
        }
        if (i < size) continue;  // Duplicate found, skip this number

        // Resize array if necessary
        if (size >= capacity) {
            capacity = capacity == 0 ? 1 : capacity * 2;
            array = realloc(array, capacity * sizeof(*array));
            if (!array) exit(EXIT_FAILURE);
        }

        // Insert new number in sorted order
        int j;
        for (j = 0; j < size && array[j] < num; ++j);
        memmove(&array[j+1], &array[j], (size - j) * sizeof(*array));
        array[j] = num;
        ++size;
    }

    // Find maximum value
    int max_value = 0;
    if (size > 0) {
        max_value = array[size-1];
    }

