#include <string.h>

typedef struct {
    char* sessionID;
    void* userMetadata; // replace with actual type if known
    int authStatus;
} SessionInfo;

typedef struct HashTableEntry {
    SessionInfo* data;
    struct HashTableEntry* next;
} HashTableEntry;

typedef struct {
    pthread_mutex_t lock;
    size_t tableSize;
    HashTableEntry** entries;
} DynamicHashTable;

DynamicHashTable* createHashTable(size_t initialSize) {
    DynamicHashTable* hashTable = malloc(sizeof(DynamicHashTable));
    if (hashTable == NULL) return NULL;

    pthread_mutex_init(&hashTable->lock, NULL);
    hashTable->tableSize = initialSize;
    hashTable->entries = calloc(initialSize, sizeof(HashTableEntry*));
    if (hashTable->entries == NULL) {
        free(hashTable);
        return NULL;
    }

    return hashTable;
}

void destroyHashTable(DynamicHashTable* hashTable) {
    for (size_t i = 0; i < hashTable->tableSize; ++i) {
        HashTableEntry* entry = hashTable->entries[i];
        while (entry != NULL) {
            HashTableEntry* next = entry->next;
            free(entry->data);
            free(entry);
            entry = next;
        }
    }

    pthread_mutex_destroy(&hashTable->lock);
    free(hashTable->entries);
    free(hashTable);
}

size_t hashFunction(const char* key, size_t tableSize) {
    // Simple hash function for demonstration purposes. Replace with a more robust one in production.
    size_t hash = 0;
    while (*key != '\0') {
        hash = (hash << 5) + hash + *key++;
    }

    return hash % tableSize;
}

void addToHashTable(DynamicHashTable* hashTable, SessionInfo* sessionInfo) {
    size_t index = hashFunction(sessionInfo->sessionID, hashTable->tableSize);

    pthread_mutex_lock(&hashTable->lock);
    HashTableEntry* entry = malloc(sizeof(HashTableEntry));
    if (entry == NULL) {
        // Handle memory allocation failure.
        return;
    }

    entry->data = sessionInfo;
    entry->next = hashTable->entries[index];
    hashTable->entries[index] = entry;
    pthread_mutex_unlock(&hashTable->lock);
}
```
