['Here is an example of how you might implement this in C using pthreads for synchronization. This code does not include all the features mentioned in your request due to its complexity and size but it gives a basic idea on how to manage multiple dynamic data structures in a high-performance server application. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    int key;
    long offset;
    struct record *next;
} Record;

Record* root = NULL;
int count = 0;
pthread_mutex_t lock;

void* initialize(void* arg) {
    pthread_mutex_lock(&lock);

    // Allocate memory for arrays
    long *offsets = malloc(sizeof(long) * 1000);
    int *keys = malloc(sizeof(int) * 1000);
    Record **records = malloc(sizeof(Record*) * 1000);

    // Initialize records with random values within specified ranges
    for (int i = 0; i < 1000; i++) {
        offsets[i] = rand() % INT_MAX;
        keys[i] = rand() % INT_MAX;

        // Check if key is unique and does not exceed the maximum integer limit
        for (int j = 0; j < i; j++) {
            while(keys[j] == keys[i]) {
                keys[i] = rand() % INT_MAX;
            }
        }

        records[i] = malloc(sizeof(Record));
        records[i]->key = keys[i];
        records[i]->offset = offsets[i];
        records[i]->next = NULL;
    }

    // Link the records into a linked list
    for (int i = 999; i >= 0; i--) {
        records[i]->next = root;
        root = records[i];
    }

    count += 1000;

    pthread_mutex_unlock(&lock);
}

void delete(int key) {
    pthread_mutex_lock(&lock);

    Record *current = root, *prev = NULL;
    while (current != NULL && current->key != key) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        printf("Key not found\n");
        return;
    }

    // Delete the record from the linked list
    if (prev != NULL) {
        prev->next = current->next;
    } else {
        root = current->next;
    }

    free(current);
    count--;

    pthread_mutex_unlock(&lock);
}

int main() {
    srand(time(NULL));
    pthread_t threads[10];
    int i;
    pthread_mutex_init(&lock, NULL);

    for (i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, initialize, NULL) != 0) {
            perror("Failed to create thread");
        }
    }

    for (i = 0; i < 10; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
        }
    }

    printf("Number of active records: %d\n", count);

    pthread_mutex_destroy(&lock);

    return 0;
}
```
This code creates a linked list of records, each with a unique key and offset. It uses threads to initialize multiple data structures concurrently. The `delete` function removes a record from the linked list based on its key. Note that this is a basic example and does not include all the features mentioned in your request due to its complexity and size.
']

