        result.records[i].value = rand();

        result.records[i].str = malloc(strlen(exampleStr) + 1);
        if (result.records[i].str == NULL) goto error;

        strcpy(result.records[i].str, exampleStr);
    }

    result.numRecords = recordSize;
    result.status = 0; // success
    return result;

error:
    // Clean up allocated memory on error
    free(result.offsets);
    free(result.keys);
    for (size_t i = 0; i < recordSize; ++i) {
        free(result.records[i].str);
    }
    free(result.records);

    return result;
}
```
