['Here is an example of how you might implement this in C. This code does not include all the features mentioned above due to its complexity and size but it provides a basic structure that can be expanded upon. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    void *data;
    struct Record *next;
} Record;

typedef struct DataStructure {
    Record **records;
    pthread_mutex_t lock;
    size_t size;
    size_t capacity;
} DataStructure;

DataStructure* init(size_t initialCapacity) {
    DataStructure *ds = malloc(sizeof(DataStructure));
    if (ds == NULL) return NULL;

    ds->records = calloc(initialCapacity, sizeof(Record*));
    if (ds->records == NULL) {
        free(ds);
        return NULL;
    }

    ds->size = 0;
    ds->capacity = initialCapacity;
    pthread_mutex_init(&ds->lock, NULL);

    return ds;
}

void destroy(DataStructure *ds) {
    for (size_t i = 0; i < ds->size; ++i) {
        free(ds->records[i]->data);
        free(ds->records[i]);
    }

    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

int addRecord(DataStructure *ds, int key, long offset, void *data) {
    if (key < 0 || offset < 0 || data == NULL) return -1;

    pthread_mutex_lock(&ds->lock);

    // Check for uniqueness of keys
    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->records[i]->key == key) {
            pthread_mutex_unlock(&ds->lock);
            return -1;
        }
    }

    // Resize the array if necessary
    if (ds->size >= ds->capacity) {
        size_t newCapacity = ds->capacity * 2;
        Record **newRecords = realloc(ds->records, newCapacity * sizeof(Record*));

        if (newRecords == NULL) {
            pthread_mutex_unlock(&ds->lock);
            return -1;
        }

        ds->capacity = newCapacity;
        ds->records = newRecords;
    }

    // Create a new record and add it to the array
    Record *record = malloc(sizeof(Record));
    if (record == NULL) {
        pthread_mutex_unlock(&ds->lock);
        return -1;
    }

    record->key = key;
    record->offset = offset;
    record->data = data;
    ds->records[ds->size++] = record;

    pthread_mutex_unlock(&ds->lock);
    return 0;
}
```
This code provides a basic structure for managing a dynamic, concurrent linked list. It uses a mutex to synchronize access to the data structure and handles allocation failures by returning NULL when memory cannot be allocated. The addRecord function checks that keys are unique before adding new records. If the array is full, it doubles its size using realloc to minimize reallocation overhead.
']

