['Here is an example of how you might implement this in C using pthreads for thread safety and a simple hash table for efficient record retrieval by key. This is a simplified version and does not cover all the constraints mentioned above. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int value;
    long offset;
    int key;
} Record;

typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

Node **hashTable = NULL;
int hashTableSize = 0;
pthread_rwlock_t rwLock = PTHREAD_RWLOCK_INITIALIZER;

void initHashTable(int size) {
    if (size <= 0) return;

    hashTableSize = size;
    hashTable = malloc(sizeof(Node*) * size);
    for (int i = 0; i < size; ++i) {
        hashTable[i] = NULL;
    }
}

void addRecord(Record *record) {
    if (!hashTable || !record) return;

    int index = record->key % hashTableSize;
    Node *node = malloc(sizeof(Node));
    node->record = record;
    pthread_rwlock_wrlock(&rwLock);
    node->next = hashTable[index];
    hashTable[index] = node;
    pthread_rwlock_unlock(&rwLock);
}

Record *getRecord(int key) {
    if (!hashTable) return NULL;

    int index = key % hashTableSize;
    pthread_rwlock_rdlock(&rwLock);
    Node *node = hashTable[index];
    while (node) {
        if (node->record->key == key) {
            pthread_rwlock_unlock(&rwLock);
            return node->record;
        }
        node = node->next;
    }
    pthread_rwlock_unlock(&rwLock);
    return NULL;
}

void removeRecord(int key) {
    if (!hashTable) return;

    int index = key % hashTableSize;
    pthread_rwlock_wrlock(&rwLock);
    Node *node = hashTable[index];
    Node *prev = NULL;
    while (node) {
        if (node->record->key == key) {
            if (prev) {
                prev->next = node->next;
            } else {
                hashTable[index] = node->next;
            }
            free(node);
            break;
        }
        prev = node;
        node = node->next;
    }
    pthread_rwlock_unlock(&rwLock);
}
```
This code provides a simple hash table for efficient record retrieval by key. It uses read-write locks to ensure thread safety, allowing multiple threads to read from the hash table simultaneously but only one thread to write at a time. This is a basic implementation and does not cover all the constraints mentioned above such as error handling, memory management, logging, data validation etc.
']

