typedef struct {
    char* ip_address;
    int port_number;
    int status_flag;
} Session;

Session* createSessions(const char* configFilePath, size_t* numOfSessions) {
    json_error_t error;
    json_t *root = json_load_file(configFilePath, 0, &error);

    if(!root) {
        fprintf(stderr, "Error loading configuration file: on line %d: %s\n", error.line, error.text);
        return NULL;
    }

    json_t *numOfSessionsJson = json_object_get(root, "numberOfSessions");
    if(!json_is_integer(numOfSessionsJson)) {
        fprintf(stderr, "Invalid configuration: numberOfSessions must be an integer\n");
        return NULL;
    }

    *numOfSessions = json_integer_value(numOfSessionsJson);
    Session* sessions = malloc(*numOfSessions * sizeof(Session));
    if(!sessions) {
        fprintf(stderr, "Failed to allocate memory for sessions\n");
        return NULL;
    }

    json_t *defaultPortJson = json_object_get(root, "defaultPortNumber");
    int defaultPort = (json_is_integer(defaultPortJson)) ? json_integer_value(defaultPortJson) : 8080; // Default port number is 8080 if not specified in the config file

    for(size_t i = 0; i < *numOfSessions; ++i) {
        sessions[i].ip_address = strdup("127.0.0.1"); // Default IP address is localhost
        sessions[i].port_number = defaultPort;
        sessions[i].status_flag = 0; // Default status flag is 0 (active)
    }

    json_decref(root);
    return sessions;
}

void destroySessions(Session* sessions, size_t numOfSessions) {
    for(size_t i = 0; i < numOfSessions; ++i) {
        free(sessions[i].ip_address);
    }

    free(sessions);
}
```
