#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    int event_type;
    char* message;
} log_entry;

typedef struct {
    int key;
    char* value;
    long offset;
} record;

typedef struct {
    pthread_mutex_t lock;
    size_t size;
    size_t capacity;
    log_entry* entries;
    record* records;
} Logger;

Logger* create_logger(size_t initial_capacity) {
    Logger* logger = malloc(sizeof(Logger));
    if (logger == NULL) return NULL;

    pthread_mutex_init(&logger->lock, NULL);
    logger->size = 0;
    logger->capacity = initial_capacity;
    logger->entries = malloc(initial_capacity * sizeof(log_entry));
    if (logger->entries == NULL) {
        free(logger);
        return NULL;
    }

    logger->records = malloc(initial_capacity * sizeof(record));
    if (logger->records == NULL) {
        free(logger->entries);
        free(logger);
        return NULL;
    }

    return logger;
}

void add_entry(Logger* logger, long timestamp, int event_type, char* message) {
    pthread_mutex_lock(&logger->lock);

    if (logger->size == logger->capacity) {
        size_t new_capacity = logger->capacity * 2;
        log_entry* new_entries = realloc(logger->entries, new_capacity * sizeof(log_entry));
        if (new_entries == NULL) return;

        record* new_records = realloc(logger->records, new_capacity * sizeof(record));
        if (new_records == NULL) {
            free(new_entries);
            return;
        }

        logger->entries = new_entries;
        logger->records = new_records;
        logger->capacity = new_capacity;
    }

    log_entry* entry = &logger->entries[logger->size];
    entry->timestamp = timestamp;
    entry->event_type = event_type;
    entry->message = strdup(message);

    logger->size++;

    pthread_mutex_unlock(&logger->lock);
}

void free_logger(Logger* logger) {
    for (size_t i = 0; i < logger->size; ++i) {
        log_entry* entry = &logger->entries[i];
        free(entry->message);

        record* record = &logger->records[i];
        free(record->value);
    }

    pthread_mutex_destroy(&logger->lock);
    free(logger->entries);
    free(logger->records);
    free(logger);
}
```
This code creates a `Logger` struct that holds an array of `log_entry` and `record` structures. The `create_logger` function initializes the logger with a given capacity, and the `add_entry` function adds new entries to the logger. If the logger is full, it doubles its size using realloc. The `free_logger` function frees all memory allocated by the logger.
