#include <stdlib.h>
#include <time.h>

typedef struct record {
    int *key;
    unsigned long offset;
    int value;
    struct record *prev, *next;
} Record;

Record* create_records(int n, unsigned long max_offset_sum, int min_value, int max_value) {
    if (n == 0) return NULL;

    // Allocate memory for keys and offsets
    int *keys = malloc(sizeof(int) * n);
    unsigned long *offsets = malloc(sizeof(unsigned long) * n);
    if (!keys || !offsets) {
        free(keys);
        free(offsets);
        return NULL; // Handle memory allocation failure
    }

    // Initialize keys and offsets
    unsigned long total_sum = 0;
    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        keys[i] = rand(); // Assuming unique keys

        // Generate offset values evenly distributed across the range
        unsigned long max_offset = max_offset_sum - total_sum;
        offsets[i] = (unsigned long)((double)rand() / RAND_MAX * max_offset);
        total_sum += offsets[i];
    }

    // Allocate memory for records and initialize doubly linked list
    Record *records = malloc(sizeof(Record) * n);
    if (!records) {
        free(keys);
        free(offsets);
        return NULL; // Handle memory allocation failure
    }

    // Initialize records and doubly linked list
    for (int i = 0; i < n; ++i) {
        records[i].key = &keys[i];
        records[i].offset = offsets[i];

        // Generate random value ensuring no two adjacent records have the same value
        int value;
        do {
            value = rand() % (max_value - min_value + 1) + min_value;
        } while(i > 0 && records[i-1].value == value);

        records[i].value = value;

        if (i > 0) {
            records[i].prev = &records[i - 1];
            records[i - 1].next = &records[i];
        } else {
            records[i].prev = NULL;
        }
    }

    return records;
}
```
