    time_t timestamp;
    int active;
} Stream;

GHashTable* streams;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Stream* create_stream(char* id) {
    Stream* stream = malloc(sizeof(Stream));
    stream->id = strdup(id);
    stream->timestamp = time(NULL);
    stream->active = 1;
    return stream;
