void remove_stream(char* id) {
    pthread_mutex_lock(&lock);

    Stream* stream = g_hash_table_lookup(streams, id);
    if (stream != NULL) {
        g_hash_table_remove(streams, id);
        free(stream->id);
        free(stream);
    }

    pthread_mutex_unlock(&lock);
}

void modify_stream(char* id, int active) {
    pthread_mutex_lock(&lock);

    Stream* stream = g_hash_table_lookup(streams, id);
    if (stream != NULL) {
        stream->active = active;
        stream->timestamp = time(NULL);
    }

    pthread_mutex_unlock(&lock);
}
