    streams[id].timestamp = time(NULL);
    pthread_mutex_unlock(&lock);
}

DataStreamConfig* getStreamStatus(int id) {
    pthread_mutex_lock(&lock);
    DataStreamConfig* config = &streams[id];
    pthread_mutex_unlock(&lock);
    return config;
}

void* retryFetchExternalSettings() {
    int delay = 100; // Initial delay in milliseconds.
    while (1) {
        if (fetchExternalSettings()) {
            break;
        }
        usleep(delay * 1000); // Sleep for the current delay.
        delay = delay << 1; // Exponential backoff.
        if (delay > 1000) {
            delay = 1000; // Maximum delay is 1 second.
        }
    }
}

void* monitorMemoryUsage() {
    while (1) {
        size_t totalMemory = getTotalMemory();
        if (totalMemory > MEMORY_THRESHOLD) {
            logWarning("Exceeded memory threshold!");
        }
        usleep(500 * 1000); // Check every half second.
    }
}
