    size_t capacity;
    size_t size;
    size_t head;
    size_t tail;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initialCapacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    assert(array != NULL);

    array->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    assert(array->data != NULL);

    array->capacity = initialCapacity;
    array->size = 0;
    array->head = 0;
    array->tail = 0;

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    free(array->data);
    free(array);
}

int check_duplicate(DynamicArray* array, int RNTI) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[(array->head + i) % array->capacity].RNTI == RNTI) {
            return 1;
        }
    }

    return 0;
}

void add_element(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
    if (check_duplicate(array, element.RNTI)) {
        // Handle duplicate RNTI case here
        return;
    }

    if (array->size == array->capacity) {
        // Handle overflow case here
        return;
    }

    array->data[array->tail] = element;
    array->tail = (array->tail + 1) % array->capacity;
    ++array->size;
}

void iterate_over_elements(DynamicArray* array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    for (size_t i = 0; i < array->size; ++i) {
        callback(array->data[(array->head + i) % array->capacity]);
    }
}
