        }
    } else {
        validate_and_extract(processor, key, value);
    }
}

void process_field(JsonProcessor *processor, const char *key, json_t *value) {
    pthread_mutex_lock(&processor->lock);
    if (strlen(json_dumps(processor->json)) > processor->limit) {
        pthread_mutex_unlock(&processor->lock);
        return;
    }
    pthread_mutex_unlock(&processor->lock);

    process_object(processor, key, value);
}

