}

char* process_json(const char *input, size_t limit) {
    JsonProcessor processor;
    pthread_mutex_init(&processor.lock, NULL);

    json_error_t error;
    processor.json = json_loads(input, 0, &error);
    if (!processor.json) {
        fprintf(stderr, "Failed to parse JSON: %s\n", error.text);
        return NULL;
    }

    processor.limit = limit;
    process_field(&processor, "", processor.json);

    char *result = json_dumps(processor.json);
    if (strlen(result) > limit) {
        free(result);
        result = NULL;
    }

    pthread_mutex_destroy(&processor.lock);
    json_decref(processor.json);

    return result;
}
