typedef struct {
    int* value;
    int key;
    long* offset;
} record;

void manage_memory(size_t size, unsigned int seed) {
    if (size == 0 || seed == 0) {
        printf("Invalid parameters\n");
        return;
    }

    srand(seed); // Initialize pseudo-random number generator with the provided seed.

    long* offsets = malloc(size * sizeof(long));
    if (offsets == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    int* keys = malloc(size * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        printf("Memory allocation failed\n");
        return;
    }

    record* records = malloc(size * sizeof(record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize arrays with pseudo-random values.
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand();
        keys[i] = rand();

        records[i].value = NULL;
        records[i].key = keys[i];
        records[i].offset = &offsets[i];
    }

    // Randomly assign valid integer values to the int fields of the record structures.
    for (size_t i = 0; i < size; ++i) {
        int value = rand();

        if (records[i].value == NULL) {
            records[i].value = malloc(sizeof(int));

            if (records[i].value == NULL) {
                printf("Memory allocation failed\n");

                // Deallocate previously allocated memory.
                for (size_t j = 0; j < i; ++j) {
                    free(records[j].value);
                }

                free(offsets);
                free(keys);
                free(records);
                return;
            }
        }

        *records[i].value = value;
    }

    // Deallocate memory.
    for (size_t i = 0; i < size; ++i) {
        free(records[i].value);
    }

    free(offsets);
    free(keys);
    free(records);
}
```
This code uses the `rand()` function to generate pseudo-random numbers. It also checks for memory allocation failures and deallocates all previously allocated memory if an error occurs. 

