typedef struct UserAccount {
    char* name;
    char* email;
    char* password;
    time_t timestamp;
} UserAccount;

UserAccount** accounts = NULL;
int accountCount = 0;
pthread_mutex_t lock;

void handleRequest(char* request) {
    // Parse the request and extract 'id', 'name', 'email', 'password' and 'action'.
    char* id = getValueFromRequest(request, "id");
    char* name = getValueFromRequest(request, "name");
    char* email = getValueFromRequest(request, "email");
    char* password = getValueFromRequest(request, "password");
    char* action = getValueFromRequest(request, "action");

    // Lock the accounts array to prevent race conditions.
    pthread_mutex_lock(&lock);

    if (strcmp(action, "delete") == 0 && id != NULL) {
        deleteAccount(id);
    } else if ((strcmp(action, "create") == 0 || action == NULL) && name != NULL && email != NULL && password != NULL) {
        createAccount(name, email, password);
    } else if (strcmp(action, "update") == 0 && id != NULL && name != NULL && email != NULL && password != NULL) {
        updateAccount(id, name, email, password);
    } else {
        printf("Invalid request\n");
    }

    // Unlock the accounts array.
    pthread_mutex_unlock(&lock);
}

void deleteAccount(char* id) {
    int index = findAccountIndexById(id);
    if (index != -1) {
        freeUserAccount(accounts[index]);

        // Shift all elements after the deleted one to fill the gap.
        for (int i = index; i < accountCount - 1; i++) {
            accounts[i] = accounts[i + 1];
        }

        accountCount--;
    } else {
        printf("Account not found\n");
    }
}

void createAccount(char* name, char* email, char* password) {
    UserAccount* newAccount = malloc(sizeof(UserAccount));
    if (newAccount == NULL) {
        printf("Failed to allocate memory for a new account\n");
        return;
    }

    newAccount->name = name;
    newAccount->email = email;
    newAccount->password = password;
    newAccount->timestamp = time(NULL);

    // Reallocate the accounts array to make room for the new account.
    accounts = realloc(accounts, (accountCount + 1) * sizeof(UserAccount*));
    if (accounts == NULL) {
        printf("Failed to allocate memory for a new account\n");
        free(newAccount);
        return;
    }

    accounts[accountCount] = newAccount;
    accountCount++;
}

void updateAccount(char* id, char* name, char* email, char* password) {
    int index = findAccountIndexById(id);
    if (index != -1) {
        freeUserAccount(accounts[index]);

        accounts[index] = malloc(sizeof(UserAccount));
        if (accounts[index] == NULL) {
            printf("Failed to allocate memory for an updated account\n");
            return;
        }

        accounts[index]->name = name;
        accounts[index]->email = email;
        accounts[index]->password = password;
        accounts[index]->timestamp = time(NULL);
    } else {
        printf("Account not found\n");
    }
}

int findAccountIndexById(char* id) {
    for (int i = 0; i < accountCount; i++) {
        if (strcmp(accounts[i]->name, id) == 0) {
            return i;
        }
    }

    return -1;
}

void freeUserAccount(UserAccount* account) {
    free(account->name);
    free(account->email);
    free(account->password);
    free(account);
}
