static int poolIndex = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Thread-local storage for efficient concurrent access
__thread NFAPI_CRC_INDICATION_PDU_T* threadLocalBuffer[POOL_SIZE];
