int precomputed[PRECOMPUTED_VALUES];

void initPrecomputed() {
    srand(time(NULL)); // seed the random number generator
    for (int i = 0; i < PRECOMPUTED_VALUES; ++i) {
        precomputed[i] = rand();
    }
}

NFAPI_UL_CQI_REPORT_PDU_T* generateReport(int N, int loggingLevel) {
    // Initialize the precomputed values
    initPrecomputed();

    clock_t start = clock(), diff;

    NFAPI_UL_CQI_REPORT_PDU_T* reports = malloc(N * sizeof(NFAPI_UL_CQI_REPORT_PDU_T));
    assert(reports != NULL); // check for memory allocation failure

    for (int i = 0; i < N; ++i) {
        diff = clock() - start;
        int msec = diff * 1000 / CLOCKS_PER_SEC;

        if (msec > 5) {
            // If the execution time exceeds 5 milliseconds, log an error and return NULL
            logging(loggingLevel, "Execution time exceeded for UE instance %d", i);
            free(reports);
            return NULL;
        }

        reports[i].RX_UE_INFORMATION_TAG = rand(); // replace with actual value
        reports[i].RNTI = rand(); // replace with actual value
        reports[i].CQI_REPORT_REL15_TAG = precomputed[rand() % PRECOMPUTED_VALUES];

        logging(loggingLevel, "Generated CQI report for UE instance %d", i);
    }

    return reports;
}
