void add_config(ConfigArray* array, NFapiUEConfig config) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->configs = realloc(array->configs, sizeof(NFapiUEConfig) * array->capacity);
    }

    array->configs[array->count++] = config;

    pthread_mutex_unlock(&array->lock);
