void update_config(ConfigArray* array, int ue_id, NFapiUEConfig new_config) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->configs[i].ue_id == ue_id) {
            array->configs[i] = new_config;
            break;
        }
