    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->configs[i].ue_id == ue_id) {
            pthread_mutex_unlock(&array->lock);
            return &array->configs[i];
        }
    }

    pthread_mutex_unlock(&array->lock);
    return NULL;
}

void serialize(ConfigArray* array, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&array->lock);
    fwrite(array->configs, sizeof(NFapiUEConfig), array->count, file);
    pthread_mutex_unlock(&array->lock);

    fclose(file);
}

void deserialize(ConfigArray* array, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }

    pthread_mutex_lock(&array->lock);
    array->count = 0;
    NFapiUEConfig config;
    while (fread(&config, sizeof(NFapiUEConfig), 1, file)) {
        add_config(array, config);
    }
    pthread_mutex_unlock(&array->lock);

    fclose(file);
}
