    atomic_init(&db->count, 0);
    pthread_mutex_init(&db->lock, NULL);
}

int addRecord(Database* db, NFAPI_CRC_INDICATION_PDU_T* record) {
    if (atomic_load(&db->count) >= 10000000) return -1; // Database is full

    pthread_mutex_lock(&db->lock);
    int index = atomic_fetch_add(&db->count, 1);
    db->data[index] = record;
    pthread_mutex_unlock(&db->lock);

    return index;
}

