    if (index < 0 || index >= atomic_load(&db->count)) return NULL; // Invalid index

    pthread_mutex_lock(&db->lock);
    NFAPI_CRC_INDICATION_PDU_T* record = db->data[index];
    pthread_mutex_unlock(&db->lock);

    return record;
