["Here is a basic implementation in C that meets your requirements. This code does not include all the features you mentioned, but it provides a starting point for further development. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/sha.h> // For SHA256 hash function

typedef struct record {
    int value;
} record_t;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char* RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    char* CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    record_t record;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct node* next;
} node_t;

node_t* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_record(int value, const char* RX_UE_INFORMATION_TAG, unsigned long RNTI, 
                const char* CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    node_t* newNode = malloc(sizeof(node_t));
    newNode->record.value = value;
    newNode->pdu.RX_UE_INFORMATION_TAG = strdup(RX_UE_INFORMATION_TAG);
    newNode->pdu.RNTI = RNTI;
    newNode->pdu.CRC_INDICATION_REL8_TAG = strdup(CRC_INDICATION_REL8_TAG);
    newNode->pdu.CRCFLAG = CRCFLAG;
    newNode->next = NULL;

    pthread_mutex_lock(&lock);
    if (head == NULL) {
        head = newNode;
    } else {
        node_t* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&lock);
}

void remove_record(int value) {
    pthread_mutex_lock(&lock);
    node_t* temp = head, *prev;

    if (temp != NULL && temp->record.value == value) {
        head = temp->next;
        free(temp);
        return;
    }

    while (temp != NULL && temp->record.value != value) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;

    prev->next = temp->next;

    free(temp);
    pthread_mutex_unlock(&lock);
}
```
This code uses a linked list to manage the records. It also uses a mutex for thread safety when adding or removing nodes from the list. The `add_record` function adds a new node at the end of the list, and the `remove_record` function removes a node with a specific value. 

