```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t listSize;
    size_t maxListSize;
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *list;
} ListManager;

void initListManager(ListManager *lm, size_t maxListSize) {
    lm->maxListSize = maxListSize;
    lm->listSize = 0;
    lm->list = NULL;
    pthread_mutex_init(&lm->mutex, NULL);
}

int addToList(ListManager *lm, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&lm->mutex);

    if (lm->listSize >= lm->maxListSize) {
        pthread_mutex_unlock(&lm->mutex);
        return -1; // list is full
    }

    for(size_t i = 0; i < lm->listSize; ++i) {
        if (lm->list[i].RNTI == item.RNTI) {
            pthread_mutex_unlock(&lm->mutex);
            return -2; // RNTI already exists in list
        }
    }

    lm->list = realloc(lm->list, (lm->listSize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    lm->list[lm->listSize++] = item;

    pthread_mutex_unlock(&lm->mutex);
    return 0; // success
}

void freeListManager(ListManager *lm) {
    pthread_mutex_lock(&lm->mutex);
    free(lm->list);
    lm->list = NULL;
    lm->listSize = 0;
    pthread_mutex_unlock(&lm->mutex);

    pthread_mutex_destroy(&lm->mutex);
}
```
This code uses a mutex to ensure that only one thread can modify the list at a time. It checks if the list is full before adding an item and ensures that RNTI values are unique within the list. The `freeListManager` function frees all allocated memory when it's no longer needed, ensuring efficient use of resources.
