typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t count;
    size_t maxSize;
    bool safeMode;
    time_t globalTimestamp;
    pthread_mutex_t lock;
} status;

status* initStatus(size_t maxSize) {
    status* s = malloc(sizeof(status));
    if (s == NULL) return NULL;

    s->offsets = calloc(maxSize, sizeof(long));
    s->keys = calloc(maxSize, sizeof(int));
    s->records = calloc(maxSize, sizeof(record*));
    if (s->offsets == NULL || s->keys == NULL || s->records == NULL) {
        freeStatus(s);
        return NULL;
    }

    s->count = 0;
    s->maxSize = maxSize;
    s->safeMode = false;
    pthread_mutex_init(&s->lock, NULL);

    return s;
}

record* initRecord(int value) {
    record* r = malloc(sizeof(record));
    if (r == NULL) return NULL;

    r->value = value;
    pthread_mutex_init(&r->lock, NULL);

    return r;
}

bool addRecord(status* s, int key, record* r) {
    if (s == NULL || r == NULL || s->count >= s->maxSize) return false;

    pthread_mutex_lock(&s->lock);
    s->keys[s->count] = key;
    s->records[s->count] = r;
    s->offsets[s->count] = (long)r;
    pthread_mutex_unlock(&s->lock);

    return true;
}

void freeStatus(status* s) {
    if (s == NULL) return;

    for (size_t i = 0; i < s->count; ++i) {
        pthread_mutex_destroy(&s->records[i]->lock);
        free(s->records[i]);
    }

    pthread_mutex_destroy(&s->lock);
    free(s->offsets);
    free(s->keys);
    free(s->records);
    free(s);
}
