    int RSSI;
    char BSSID[20];
    WIFI_STATION_METRICS metrics;
} WIFI_STA_INFO_TAG;

typedef struct Node {
    WIFI_STA_INFO_TAG data;
    struct Node* next;
    struct Node* prev;
} Node;

Node *head = NULL;
pthread_mutex_t lock;
int maxEntries = 1000; // limit the maximum number of entries in the list

void addToList(WIFI_STA_INFO_TAG data) {
    pthread_mutex_lock(&lock);

    Node* newNode = (Node*) malloc(sizeof(Node));
    if(newNode == NULL) {
        // handle memory allocation failure gracefully
        pthread_mutex_unlock(&lock);
        return;
    }

    newNode->data = data;
    newNode->next = head;
    newNode->prev = NULL;

    if(head != NULL) {
        head->prev = newNode;
    }

    head = newNode;

    // ensure we don't exceed the maximum number of entries
    Node* tail = head;
    int count = 1;
    while(tail->next != NULL && count < maxEntries) {
        tail = tail->next;
        count++;
    }

    if(count == maxEntries) {
        // remove the last node (oldest entry) from the list
        Node* oldNode = tail;
        tail = tail->prev;

        if(tail != NULL) {
            tail->next = NULL;
        }

        free(oldNode);
    }

    pthread_mutex_unlock(&lock);
}
```
