    int recordCount;
    size_t totalMemoryUsed;
} DataPipeline;

DataPipeline* initDataPipeline() {
    DataPipeline* pipeline = malloc(sizeof(DataPipeline));
    pthread_mutex_init(&pipeline->lock, NULL);
    pipeline->offsets = calloc(10000000, sizeof(long));
    pipeline->keys = calloc(10000000, sizeof(int));
    pipeline->records = calloc(10000000, sizeof(Record));
    pipeline->customRecords = calloc(10000000, sizeof(CustomRecord));
    pipeline->recordCount = 0;
    pipeline->totalMemoryUsed = 0;
    return pipeline;
}

void addRecord(DataPipeline* pipeline, long offset, int key, Record record) {
    pthread_mutex_lock(&pipeline->lock);

    pipeline->offsets[pipeline->recordCount] = offset;
    pipeline->keys[pipeline->recordCount] = key;
    pipeline->records[pipeline->recordCount] = record;

    pipeline->totalMemoryUsed += sizeof(Record);
    pipeline->recordCount++;

    pthread_mutex_unlock(&pipeline->lock);
}

void addCustomRecord(DataPipeline* pipeline, CustomRecord customRecord) {
    pthread_mutex_lock(&pipeline->lock);

    pipeline->customRecords[pipeline->recordCount] = customRecord;

    pipeline->totalMemoryUsed += sizeof(CustomRecord) + customRecord.size;
