#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int value;
    long offset;
    int key;
    double timestamp;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert(Record record) {
    pthread_mutex_lock(&lock);

    Node* newNode = malloc(sizeof(Node));
    newNode->record = record;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void delete(int key) {
    pthread_mutex_lock(&lock);

    Node* prev = NULL;
    for (Node* curr = head; curr != NULL; prev = curr, curr = curr->next) {
        if (curr->record.key == key) {
            if (prev == NULL) {
                head = curr->next;
            } else {
                prev->next = curr->next;
            }

            free(curr);
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

Record* get(int key) {
    pthread_mutex_lock(&lock);

    for (Node* curr = head; curr != NULL; curr = curr->next) {
        if (curr->record.key == key) {
            pthread_mutex_unlock(&lock);
            return &(curr->record);
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}
```
This code implements a simple linked list with insert, delete and get operations. It uses mutex to ensure thread safety. 

