#include <time.h>

typedef struct {
    void* payload;
    time_t timestamp;
    int errorFlag;
} DataPacket;

typedef struct {
    DataPacket** packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PacketArray;

int init_packet(DataPacket* packet) {
    packet->payload = malloc(sizeof(void*));
    if (packet->payload == NULL) return -1;

    time(&packet->timestamp);
    packet->errorFlag = 0;
    return 0;
}

int init_array(PacketArray* array, size_t initialCapacity) {
    array->capacity = initialCapacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    array->packets = malloc(sizeof(DataPacket*) * array->capacity);
    if (array->packets == NULL) return -1;

    for (size_t i = 0; i < array->capacity; ++i) {
        array->packets[i] = malloc(sizeof(DataPacket));
        if (array->packets[i] == NULL || init_packet(array->packets[i]) != 0) return -1;
    }

    return 0;
}

int add_to_array(PacketArray* array, DataPacket* packet) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    array->packets[array->count++] = packet;

    pthread_mutex_unlock(&array->lock);
    return 0;
}
```
