```php
class ProductManager {
    private $db; // Database connection object

    public function __construct($db) {
        $this->db = $db;
    }

    public function processProductRequest() {
        if (!isset($_SESSION['authenticated']) || !$_SESSION['authenticated']) {
            // User is not authenticated, return an error response
            http_response_code(401);
            echo json_encode(['error' => 'Unauthorized']);
            return;
        }

        $method = $_SERVER['REQUEST_METHOD'];
        $data = array_merge($_GET, $_POST); // Merge GET and POST parameters

        if ($method === 'POST') {
            $this->createOrUpdateProduct($data);
        } elseif ($method === 'PUT') {
            if (!isset($data['id'])) {
                http_response_code(400);
                echo json_encode(['error' => 'Missing product id']);
                return;
            }
            $this->createOrUpdateProduct($data, true);
        } elseif ($method === 'DELETE') {
            if (!isset($data['id'])) {
                http_response_code(400);
                echo json_encode(['error' => 'Missing product id']);
                return;
            }
            $this->deleteProduct($data['id']);
        } elseif ($method === 'GET') {
            if (!isset($data['id'])) {
                http_response_code(400);
                echo json_encode(['error' => 'Missing product id']);
                return;
            }
            $this->getProduct($data['id']);
        } else {
            http_response_code(405);
            echo json_encode(['error' => 'Method not allowed']);
        }
    }

    private function createOrUpdateProduct($data, $update = false) {
        // Validate the data and handle errors accordingly

        $productData = $this->validateAndSanitizeInputs($data);

        if ($update && isset($data['id'])) {
            $this->db->update('products', $productData, ['id' => $data['id']]);
        } else {
            $this->db->insert('products', $productData);
        }

        http_response_code(200);
    }

    private function deleteProduct($id) {
        $this->db->delete('products', ['id' => $id]);
        http_response_code(204); // No content
    }

    private function getProduct($id) {
        $product = $this->db->select('products', '*', ['id' => $id])[0];

        if (!$product) {
            http_response_code(404);
            echo json_encode(['error' => 'Product not found']);
            return;
        }

        echo json_encode($product);
    }

    private function validateAndSanitizeInputs($data) {
        // Implement your own validation and sanitization logic here
        // This is a basic example, you should use more robust methods for production code

        $validatedData = [];

        if (isset($data['name'])) {
            $validatedData['name'] = substr(filter_var($data['name'], FILTER_SANITIZE_STRING), 0, 100);
