    list->pdus = calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    list->capacity = initialCapacity;
    list->size = 0;
    return list;
}

void add_record(List* list, Record* record) {
    if (list->size == list->capacity) {
        list->records = realloc(list->records, list->capacity * 2 * sizeof(Record*));
        list->pdus = realloc(list->pdus, list->capacity * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        list->capacity *= 2;
    }
    list->records[list->size] = record;
    list->size++;
}

void remove_record(List* list, size_t index) {
    if (index >= list->size) return;
    free(list->records[index]);
    for (size_t i = index; i < list->size - 1; ++i) {
        list->records[i] = list->records[i + 1];
    }
    list->size--;
}

void destroy_list(List* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->records[i]);
    }
    free(list->records);
    free(list);
}
