#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct record {
    int value;
    long offset;
    int key;
    double timestamp;
} Record;

typedef struct node {
    int timestamp;
    struct node* next;
    Record* record;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
atomic_int processing = 0;
Node *head = NULL, *tail = NULL;
Record* records[1024]; // assuming a maximum of 1024 records for simplicity
extern void externalDataSource(Record*, int); // assume this function exists and fetches data from an external source

void* process_data(void* arg) {
    Record* record = (Record*)arg;
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;

    atomic_fetch_add(&processing, 1); // increment processing count
    pthread_mutex_lock(&lock); // lock to ensure thread safety

    externalDataSource(record, sizeof(Record)); // fetch data from external source
    node->timestamp = record->timestamp;
    node->next = NULL;
    node->record = record;

    if (!head) {
        head = tail = node;
    } else {
        tail->next = node;
        tail = node;
    }

    pthread_mutex_unlock(&lock); // unlock after operation
    atomic_fetch_sub(&processing, 1); // decrement processing count
}

int main() {
    for (size_t i = 0; i < 1024; ++i) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) return -1;

        pthread_t thread;
        pthread_create(&thread, NULL, process_data, records[i]); // create a new thread for each record
    }

    while (atomic_load(&processing) > 0); // wait until all threads are done processing

    Node* node = head;
    while (node) {
        Node* next = node->next;
        free(node); // free memory of each node
        node = next;
    }

    for (size_t i = 0; i < 1024; ++i) {
        free(records[i]); // free memory of each record
    }
}
