public interface IHashService
{
    Task<string> ComputeMD5Async(string filePath);
}

public class HashService : IHashService
{
    private const int DefaultChunkSize = 4096;

    public async Task<string> ComputeMD5Async(string filePath)
    {
        using (var md5 = MD5.Create())
        {
            byte[] hashBytes;

            try
            {
                // Read file in chunks to optimize memory usage
                var buffer = new byte[DefaultChunkSize];

                using (var stream = File.OpenRead(filePath))
                {
                    int bytesRead;

                    while ((bytesRead = await stream.ReadAsync(buffer, 0, DefaultChunkSize)) > 0)
                    {
                        md5.TransformBlock(buffer, 0, bytesRead, buffer, 0);
                    }

                    md5.TransformFinalBlock(buffer, 0, 0);
                }

                hashBytes = md5.Hash;
            }
            catch (IOException)
            {
                // Retry up to three times on I/O errors
                if (retryCount < 3)
                {
                    await Task.Delay(100);
                    return await ComputeMD5Async(filePath, retryCount + 1);
                }

                throw;
            }

            var sb = new StringBuilder();

            for (var i = 0; i < hashBytes.Length; i++)
            {
                sb.Append(hashBytes[i].ToString("X2"));
            }

            return sb.ToString();
        }
    }
}
