#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct NetworkEntityStats {
    int UE_ID;
    float signalStrength;
    float latency;
    float throughput;
    time_t lastUpdated;
} NetworkEntityStats;

typedef struct Node {
    NetworkEntityStats *data;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int updateAttempts = 0;
int failedUpdateAttempts = 0;
time_t windowStartTime = time(NULL);

void addEntity(NetworkEntityStats *stats) {
    pthread_mutex_lock(&lock);

    Node *newNode = malloc(sizeof(Node));
    newNode->data = stats;
    newNode->next = head;
    head = newNode;

    updateAttempts++;
    if (stats->signalStrength < 0) {
        failedUpdateAttempts++;
    }

    time_t currentTime = time(NULL);
    double elapsedSeconds = difftime(currentTime, windowStartTime);
    if (elapsedSeconds >= 60.0) {
        printf("In the last minute, %d update attempts were made with %d failures.\n", 
               updateAttempts, failedUpdateAttempts);
        updateAttempts = 0;
        failedUpdateAttempts = 0;
        windowStartTime = currentTime;
    }

    pthread_mutex_unlock(&lock);
}

NetworkEntityStats *getWeakestSignal() {
    pthread_mutex_lock(&lock);

    Node *currentNode = head;
    NetworkEntityStats *weakest = NULL;
    while (currentNode != NULL) {
        if (weakest == NULL || currentNode->data->signalStrength < weakest->signalStrength) {
            weakest = currentNode->data;
        }
        currentNode = currentNode->next;
    }

    pthread_mutex_unlock(&lock);
    return weakest;
}
