void add(NFAPI_CRC_INDICATION_PDU_T value) {
    pthread_mutex_lock(&lock);

    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->data = value;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void clear() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;

    pthread_mutex_unlock(&lock);
}
