} Record;

typedef struct {
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    Record* records;
} Collection;

Collection* create_collection(size_t initialCapacity) {
    Collection* collection = malloc(sizeof(Collection));
    if (collection == NULL) return NULL;

    pthread_mutex_init(&collection->lock, NULL);
    collection->count = 0;
    collection->capacity = initialCapacity;
    collection->records = malloc(initialCapacity * sizeof(Record));
    if (collection->records == NULL) {
        free(collection);
        return NULL;
    }

    return collection;
}

void destroy_collection(Collection* collection) {
    pthread_mutex_destroy(&collection->lock);
    free(collection->records);
    free(collection);
}

int insert_record(Collection* collection, Record record) {
    clock_t start = clock();

    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        Record* newRecords = realloc(collection->records, newCapacity * sizeof(Record));
        if (newRecords == NULL) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }

        collection->capacity = newCapacity;
        collection->records = newRecords;
    }

    collection->records[collection->count++] = record;

    pthread_mutex_unlock(&collection->lock);

    clock_t end = clock();
    double timeSpent = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Insertion took %f seconds\n", timeSpent);

    return 0;
}
```
This code creates a `Collection` structure that manages an array of `Record` structures. The `insert_record` function is thread-safe and can handle up to 1,000,000 records efficiently by doubling the capacity when it's full. It also measures the time taken for insertion operations and logs this information.

