void addContext(UEContextInfo *context) {
    pthread_mutex_lock(&lock);

    if (contextPool->len >= maxSize) {
        // Handle pool full scenario here. You could evict expired contexts, 
        // or simply drop the new context if you can't add it to the pool.
    } else {
        g_array_append_val(contextPool, *context);
    }

    pthread_mutex_unlock(&lock);
}

void removeExpiredContexts() {
    time_t currentTime = time(NULL);

    pthread_mutex_lock(&lock);

    for (int i = 0; i < contextPool->len; ++i) {
        UEContextInfo *context = &g_array_index(contextPool, UEContextInfo, i);

        if (difftime(currentTime, context->timestamp) >= 0) {
            g_array_remove_index_fast(contextPool, i);
            --i; // Decrement index to account for removed element
        }
    }

    pthread_mutex_unlock(&lock);
}
