```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* data;
    int timestamp;
    bool flag;
} record;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    record** records;
} RecordList;

RecordList* create_list(size_t initial_capacity) {
    RecordList* list = malloc(sizeof(RecordList));
    if (list == NULL) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->records = calloc(initial_capacity, sizeof(record*));
    if (list->records == NULL) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    return list;
}

void add_record(RecordList* list, char* template, size_t length) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        // Resize the array
        list->records = realloc(list->records, 2 * list->capacity * sizeof(record*));
        if (list->records == NULL) return;

        list->capacity *= 2;
    }

    record* new_record = malloc(sizeof(record));
    if (new_record == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    // Allocate memory for the data buffer and copy from template
    new_record->data = malloc(length + 1);
    if (new_record->data == NULL) {
        free(new_record);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    memcpy(new_record->data, template, length);
    new_record->data[length] = '\0'; // Null terminate the string

    // Set default values for timestamp and flag
    new_record->timestamp = 0;
    new_record->flag = false;

    list->records[list->size++] = new_record;

    pthread_mutex_unlock(&list->lock);
}

void remove_record(RecordList* list, size_t index) {
    pthread_mutex_lock(&list->lock);

    if (index >= list->size) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    free(list->records[index]->data); // Free the data buffer
    free(list->records[index]); // Free the record itself

    list->size--;
    if (index < list->size) {
        memmove(&list->records[index], &list->records[index + 1], 
                (list->size - index) * sizeof(record*)); // Shift remaining records to fill the gap
    }

    pthread_mutex_unlock(&list->lock);
}
```
This code uses a mutex for thread safety. It also checks if memory allocation was successful before proceeding, and frees any allocated resources in case of failure. The list is resized when it's full to avoid frequent reallocations. 

