void add(int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&lock);

    Node *newNode = malloc(sizeof(Node));
    newNode->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->next = NULL;

    // Validate the data before adding it to the list.
    if (RX_UE_INFORMATION_TAG < 0 || RNTI < 0 || CRCFLAG < 0) {
        free(newNode);
        pthread_mutex_unlock(&lock);
        return;
    }

    newNode->data->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data->RNTI = RNTI;
    newNode->data->CRCFLAG = CRCFLAG;

    if (head == NULL) {
        head = newNode;
    } else {
        Node *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&lock);
}
