typedef struct {
    long* offsets;
    int* keys;
    record** records;
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
} collection;

collection* init_collection(size_t initial_capacity) {
    collection* col = malloc(sizeof(collection));
    if (col == NULL) return NULL;

    col->offsets = malloc(initial_capacity * sizeof(long));
    col->keys = malloc(initial_capacity * sizeof(int));
    col->records = malloc(initial_capacity * sizeof(record*));
    if (col->offsets == NULL || col->keys == NULL || col->records == NULL) {
        free(col->offsets);
        free(col->keys);
        free(col->records);
        free(col);
        return NULL;
    }

    col->capacity = initial_capacity;
    col->count = 0;
    pthread_mutex_init(&col->lock, NULL);

    return col;
}

void add_record(collection* col, long offset, int key, record* rec) {
    if (col->count == col->capacity) {
        size_t new_capacity = col->capacity * 2;

        col->offsets = realloc(col->offsets, new_capacity * sizeof(long));
        col->keys = realloc(col->keys, new_capacity * sizeof(int));
        col->records = realloc(col->records, new_capacity * sizeof(record*));

        if (col->offsets == NULL || col->keys == NULL || col->records == NULL) {
            // handle allocation failure...
        } else {
            col->capacity = new_capacity;
        }
    }

    col->offsets[col->count] = offset;
    col->keys[col->count] = key;
    col->records[col->count] = rec;
    col->count++;
}
